8.5 src/metric.ts

// src/metric.ts

import { ValidationError } from "./errors.js";
import type { ExperimentRun } from "./run.js";

export function getBestMetric(values: number[]): number {
  if (values.length === 0) {
    throw new ValidationError("values must not be empty");
  }

  return Math.max(...values);
}

export function getAverageMetric(values: number[]): number {
  if (values.length === 0) {
    throw new ValidationError("values must not be empty");
  }

  const total = values.reduce((sum, value) => sum + value, 0);
  return total / values.length;
}

export function getBestRunByMetric(
  runs: ExperimentRun[],
  metricName: string,
): ExperimentRun {
  if (runs.length === 0) {
    throw new ValidationError("runs must not be empty");
  }

  let bestRun: ExperimentRun | undefined;
  let bestValue = Number.NEGATIVE_INFINITY;

  for (const run of runs) {
    const value = run.metrics[metricName];

    if (typeof value !== "number") {
      continue;
    }

    if (value > bestValue) {
      bestValue = value;
      bestRun = run;
    }
  }

  if (!bestRun) {
    throw new ValidationError(`metric "${metricName}" does not exist in runs`);
  }

  return bestRun;
}

这里练习了：

import type
数组 reduce
for...of
undefined 类型收窄
业务错误处理

注意：

import type { ExperimentRun } from "./run.js";

import type 表示只导入类型。
这在现代 TypeScript / Node ESM 项目里是好习惯。

8.6 src/config.ts

// src/config.ts

import { ValidationError } from "./errors.js";

export type ExperimentConfig = {
  model: string;
  dataset: string;
  seed: number;
  learningRate: number;
};

export function createExperimentConfig(
  input: ExperimentConfig,
): ExperimentConfig {
  if (input.model.trim().length === 0) {
    throw new ValidationError("model must not be empty");
  }

  if (input.dataset.trim().length === 0) {
    throw new ValidationError("dataset must not be empty");
  }

  if (!Number.isInteger(input.seed)) {
    throw new ValidationError("seed must be an integer");
  }

  if (input.learningRate <= 0) {
    throw new ValidationError("learningRate must be positive");
  }

  return input;
}

export function summarizeConfig(config: ExperimentConfig): string {
  return [
    `model=${config.model}`,
    `dataset=${config.dataset}`,
    `seed=${config.seed}`,
    `learningRate=${config.learningRate}`,
  ].join(", ");
}

LabPilot 场景：

