// scripts/generate-runs.ts

import { mkdir, writeFile } from "node:fs/promises";
import { join } from "node:path";

const outputDir = "generated";
const outputFile = join(outputDir, "runs.json");

const runs = [
  {
    id: "run_001",
    experimentId: "exp_001",
    status: "finished",
    metrics: {
      accuracy: 0.91,
      loss: 0.23,
    },
    startedAt: new Date().toISOString(),
    finishedAt: new Date().toISOString(),
  },
  {
    id: "run_002",
    experimentId: "exp_001",
    status: "failed",
    metrics: {
      accuracy: 0.72,
      loss: 0.89,
    },
    startedAt: new Date().toISOString(),
    finishedAt: new Date().toISOString(),
  },
];

await mkdir(outputDir, {
  recursive: true,
});

await writeFile(outputFile, JSON.stringify(runs, null, 2), "utf-8");

console.log(`Generated ${runs.length} runs at ${outputFile}`);

这个脚本的作用：

生成实验 run 样例数据。

它属于：

开发辅助脚本

所以放在：

scripts/

而不是：

src/

