练习 6：数组比较

const runsA = ["run_001", "run_002"];
const runsB = ["run_001", "run_002"];
const runsC = runsA;

console.log("runsA === runsB:", runsA === runsB);
console.log("runsA === runsC:", runsA === runsC);

