练习 7：写 isValidMetricValue

function isValidMetricValue(value: unknown): value is number {
  return typeof value === "number" && Number.isFinite(value);
}

console.log(isValidMetricValue(0.91));      // true
console.log(isValidMetricValue(0));         // true
console.log(isValidMetricValue(NaN));       // false
console.log(isValidMetricValue(Infinity));  // false
console.log(isValidMetricValue("0.91"));    // false
console.log(isValidMetricValue(undefined)); // false

要求理解：

