10.5 排查配置 normalize 结果

function debugConfig(input: Record<string, unknown>): void {
  console.log("raw input:", input);

  const seed = parseIntegerOrNull(input["seed"]);
  const learningRate = parsePositiveNumberOrNull(input["learningRate"]);
  const useWandb = parseBooleanFlag(input["useWandb"]);

  console.log("normalized:", {
    seed,
    learningRate,
    useWandb,
  });
}

function parseIntegerOrNull(value: unknown): number | null {
  if (typeof value === "string" && value.trim().length === 0) {
    return null;
  }

  const parsed = Number(value);

  if (!Number.isInteger(parsed)) {
    return null;
  }

  return parsed;
}

function parsePositiveNumberOrNull(value: unknown): number | null {
  if (typeof value === "string" && value.trim().length === 0) {
    return null;
  }

  const parsed = Number(value);

  if (!Number.isFinite(parsed) || parsed <= 0) {
    return null;
  }

  return parsed;
}

function parseBooleanFlag(value: unknown): boolean | null {
  if (value === true || value === "true") {
    return true;
  }

  if (value === false || value === "false") {
    return false;
  }

  return null;
}

debugConfig({
  seed: "42",
  learningRate: "0.00002",
  useWandb: "false",
});

