练习 7：写 Run 类型守卫

function isRunStatus(value: unknown): value is RunStatus {
  return (
    value === "queued" ||
    value === "running" ||
    value === "finished" ||
    value === "failed"
  );
}

function isMetricMap(value: unknown): value is Record<string, number> {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    return false;
  }

  for (const metricValue of Object.values(value)) {
    if (typeof metricValue !== "number" || !Number.isFinite(metricValue)) {
      return false;
    }
  }

  return true;
}

function isExperimentRun(value: unknown): value is ExperimentRun {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    return false;
  }

  const obj = value as Record<string, unknown>;

  return (
    typeof obj["id"] === "string" &&
    isRunStatus(obj["status"]) &&
    isMetricMap(obj["metrics"]) &&
    typeof obj["createdAt"] === "string" &&
    (
      obj["finishedAt"] === undefined ||
      typeof obj["finishedAt"] === "string"
    )
  );
}

const parsedRun = safeJsonParse(prettyJson);

if (isExperimentRun(parsedRun)) {
  console.log("valid run:", parsedRun.id);
} else {
  console.log("invalid run");
}

