8.1 解析实验配置

type RawExperimentConfig = {
  seed?: unknown;
  epochs?: unknown;
  learningRate?: unknown;
  useWandb?: unknown;
  runName?: unknown;
};

type ExperimentConfig = {
  seed: number;
  epochs: number;
  learningRate: number;
  useWandb: boolean;
  runName: string;
};

function normalizeExperimentConfig(
  input: RawExperimentConfig,
): ExperimentConfig {
  return {
    seed: parseSeed(input.seed) ?? 42,
    epochs: parsePositiveInteger(input.epochs) ?? 3,
    learningRate: parsePositiveNumber(input.learningRate) ?? 0.00002,
    useWandb: parseBooleanFlag(input.useWandb) ?? false,
    runName: normalizeOptionalString(input.runName) ?? "untitled-run",
  };
}

可处理：

normalizeExperimentConfig({
  seed: "0",
  epochs: "3",
  learningRate: "0.00002",
  useWandb: "false",
  runName: "  bert baseline  ",
});

得到：

{
  seed: 0,
  epochs: 3,
  learningRate: 0.00002,
  useWandb: false,
  runName: "bert baseline"
}

