12.2 排查 JSON 输入

function debugJsonInput(text: string): void {
  const parsed = safeJsonParse(text);

  console.log("parsed:", parsed);
  console.log("parsed type:", typeof parsed);

  if (typeof parsed === "object" && parsed !== null) {
    console.log("keys:", Object.keys(parsed));
  }
}

使用：

debugJsonInput(`{"id":"run_001"}`);
debugJsonInput(`null`);
debugJsonInput(`[1,2,3]`);
debugJsonInput(`{ invalid json }`);

12.3 排查 Run 解析失败原因

可以写一个临时 debug 版：

function debugRunInput(value: unknown): void {
  console.log("raw:", value);

  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    console.log("not object");
    return;
  }

  const obj = value as Record<string, unknown>;

  console.log({
    id: obj["id"],
    idType: typeof obj["id"],
    experimentId: obj["experimentId"],
    experimentIdType: typeof obj["experimentId"],
    status: obj["status"],
    isRunStatus: isRunStatus(obj["status"]),
    metrics: obj["metrics"],
    normalizedMetrics: normalizeMetricMap(obj["metrics"]),
    startedAt: obj["startedAt"],
    startedAtType: typeof obj["startedAt"],
  });
}

用于排查：

