export type PaperInput = {
  title: string;
  doi?: string;
  venue?: string;
  tags: string[];
};

export function normalizePaperInput(value: unknown): PaperInput | null {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    return null;
  }

  const obj = value as Record<string, unknown>;

  const title = normalizeOptionalString(obj["title"]);

  if (title === undefined) {
    return null;
  }

  return {
    title,
    doi: normalizeOptionalString(obj["doi"]),
    venue: normalizeOptionalString(obj["venue"]),
    tags: normalizeTags(obj["tags"]),
  };
}

