5. 最小可运行示例

创建文件：

New-Item src/function-params-demo.ts

在 package.json 添加：

{
  "scripts": {
    "demo:function-params": "tsx src/function-params-demo.ts"
  }
}

写入代码：

// src/function-params-demo.ts

type RunStatus = "queued" | "running" | "finished" | "failed";

type ExperimentRun = {
  id: string;
  experimentId: string;
  status: RunStatus;
  metrics: Record<string, number>;
  startedAt: string;
};

function formatMetric(value: number, digits = 4): string {
  return value.toFixed(digits);
}

function normalizeRunName(name?: string): string {
  return name?.trim() || "untitled-run";
}

function parsePage(value: unknown, defaultPage = 1): number {
  const parsed = Number(value);

  if (!Number.isInteger(parsed) || parsed < 1) {
    return defaultPage;
  }

  return parsed;
}

function logInfo(scope: string, ...messages: string[]): void {
  console.log(`[${scope}] ${messages.join(" ")}`);
}

type CreateRunInput = {
  id?: string;
  experimentId: string;
  status?: RunStatus;
  metrics?: Record<string, number>;
  startedAt?: string;
};

function createRun(input: CreateRunInput): ExperimentRun {
  return {
    id: input.id ?? `run_${Date.now()}`,
    experimentId: input.experimentId,
    status: input.status ?? "queued",
    metrics: input.metrics ?? {},
    startedAt: input.startedAt ?? new Date().toISOString(),
  };
}

type FormatMetricOptions = {
  name: string;
  value: number;
  digits?: number;
};

function formatNamedMetric({
  name,
  value,
  digits = 4,
}: FormatMetricOptions): string {
  return `${name}=${value.toFixed(digits)}`;
}

const run = createRun({
  experimentId: "exp_001",
  status: "finished",
  metrics: {
    accuracy: 0.912345,
    loss: 0.23,
  },
});

console.log("run:", run);
console.log("formatMetric:", formatMetric(0.912345));
console.log("formatMetric 2 digits:", formatMetric(0.912345, 2));
console.log("normalizeRunName:", normalizeRunName("  bert baseline  "));
console.log("normalizeRunName default:", normalizeRunName());
console.log("parsePage:", parsePage("2"));
console.log("parsePage default:", parsePage("abc"));
console.log(
  "formatNamedMetric:",
  formatNamedMetric({
    name: "accuracy",
    value: 0.912345,
    digits: 2,
  }),
);

logInfo("run", "created", run.id, run.status);

运行：

pnpm demo:function-params

重点观察：

digits 没传时使用默认值 4。
normalizeRunName 没传时返回 untitled-run。
parsePage("abc") 返回默认页码。
logInfo 可以接收任意数量 messages。
createRun 使用参数对象模式。

