const moduleValue = "module";

function outer(): void {
  const outerValue = "outer";

  function inner(): void {
    console.log(moduleValue, outerValue);
  }

  inner();
}

项目
说明
作用
变量从内向外查找
查找顺序
当前函数 → 外层函数 → 模块作用域
工程用途
callback 访问外部上下文
注意点
同名变量会被最近作用域遮蔽

4.3 callback 访问外层变量

runs.filter((run) => run.status === targetStatus);

项目
说明
作用
