这会形成闭包，下一小点深入

4.5 局部 helper 函数

function parseConfig(value: unknown) {
  function isObject(input: unknown): input is Record<string, unknown> {
    return typeof input === "object" && input !== null && !Array.isArray(input);
  }

  if (!isObject(value)) {
    return null;
  }

  return value;
}

项目
说明
作用
