    return input.trim().length === 0;
  }

  if (isBlank(value)) {
    return null;
  }

  return value.trim();
}

console.log(normalizeRunName("  bert baseline  "));
console.log(normalizeRunName("   "));

理解：

isBlank 只在 normalizeRunName 内使用。
所以可以放到函数内部。

12. 本小点总结

本节必须记住：

JavaScript / TypeScript 是词法作用域。
函数能访问什么变量，由函数定义位置决定，不由调用位置决定。

核心规律：

内层函数可以访问外层变量。
外层函数不能访问内层变量。
变量查找从内向外。
最近作用域优先。
同名变量会发生遮蔽。
callback 可以访问定义位置的外层变量。
函数返回函数时，返回的函数仍能访问定义时的外层变量。

工程口诀：

看函数能访问什么 → 看它在哪里定义
看变量来自哪里 → 从当前位置向外找最近声明
callback 能用外层参数 → 因为词法作用域
logger 能记住 scope → 因为词法作用域
metric formatter 能记住 metricName → 因为词法作用域
不要用模块级可变变量模拟上下文
上下文要么通过参数传入，要么通过工厂函数显式保存

LabPilot 推荐写法：

function createLogger(scope: string) {
  return function log(message: string): void {
    console.log(`[${scope}] ${message}`);
  };
}

function createStatusChecker(targetStatus: RunStatus) {
  return function check(run: ExperimentRun): boolean {
    return run.status === targetStatus;
  };
}

function getRunsByStatus(
  runs: ExperimentRun[],
  targetStatus: RunStatus,
): ExperimentRun[] {
  return runs.filter((run) => run.status === targetStatus);
}

