// src/closure-demo.ts

type RunStatus = "queued" | "running" | "finished" | "failed";

type ExperimentRun = {
  id: string;
  status: RunStatus;
  metrics: Record<string, number>;
};

function createLogger(scope: string): (message: string) => void {
  return function log(message: string): void {
    console.log(`[${scope}] ${message}`);
  };
}

function createMetricFormatter(
  metricName: string,
  digits = 4,
): (value: number) => string {
  return function format(value: number): string {
    return `${metricName}=${value.toFixed(digits)}`;
  };
}

function createStatusChecker(
  targetStatus: RunStatus,
): (run: ExperimentRun) => boolean {
  return function check(run: ExperimentRun): boolean {
    return run.status === targetStatus;
  };
}

function createCounter(): () => number {
  let count = 0;

  return function increment(): number {
    count += 1;
    return count;
  };
}

function createRunStatusCounter() {
  let finished = 0;
  let failed = 0;

  return {
    add(status: RunStatus) {
      if (status === "finished") {
        finished += 1;
      }

      if (status === "failed") {
        failed += 1;
      }

      return {
        finished,
        failed,
      };
    },
    reset(): void {
      finished = 0;
      failed = 0;
    },
    getCount() {
      return {
        finished,
        failed,
      };
    },
  };
}

const runs: ExperimentRun[] = [
  {
    id: "run_001",
    status: "finished",
    metrics: {
      accuracy: 0.91,
      loss: 0.23,
    },
  },
  {
    id: "run_002",
    status: "failed",
    metrics: {
      accuracy: 0.7,
      loss: 0.9,
    },
  },
  {
    id: "run_003",
    status: "finished",
    metrics: {
      accuracy: 0.95,
      loss: 0.18,
    },
  },
];

const runLogger = createLogger("run");
const agentLogger = createLogger("agent");

runLogger("started run_001");
agentLogger("called tool plot_metric_curve");

const formatAccuracy = createMetricFormatter("accuracy", 2);
const formatLoss = createMetricFormatter("loss", 4);

console.log(formatAccuracy(0.912345));
console.log(formatLoss(0.23456));

const isFinishedRun = createStatusChecker("finished");
const isFailedRun = createStatusChecker("failed");

console.log("finished:", runs.filter(isFinishedRun).map((run) => run.id));
console.log("failed:", runs.filter(isFailedRun).map((run) => run.id));

const counterA = createCounter();
const counterB = createCounter();

console.log("counterA:", counterA());
console.log("counterA:", counterA());
console.log("counterB:", counterB());
console.log("counterB:", counterB());

const statusCounter = createRunStatusCounter();

for (const run of runs) {
  console.log(statusCounter.add(run.status));
}

console.log("final count:", statusCounter.getCount());

statusCounter.reset();

console.log("after reset:", statusCounter.getCount());

运行：

pnpm demo:closure

重点观察：

runLogger 记住 scope = "run"。
agentLogger 记住 scope = "agent"。
formatAccuracy 记住 metricName = "accuracy"。
isFinishedRun 记住 targetStatus = "finished"。
counterA 和 counterB 有各自独立的 count。
statusCounter 里的 finished / failed 外部不能直接访问。

