5. 最小可运行示例

创建文件：

New-Item src/higher-order-function-demo.ts

在 package.json 添加：

{
  "scripts": {
    "demo:higher-order": "tsx src/higher-order-function-demo.ts"
  }
}

写入代码：

// src/higher-order-function-demo.ts

type RunStatus = "queued" | "running" | "finished" | "failed";

type ExperimentRun = {
  id: string;
  status: RunStatus;
  metrics: Record<string, number>;
};

type RunPredicate = (run: ExperimentRun) => boolean;
type MetricFormatter = (value: number) => string;

const runs: ExperimentRun[] = [
  {
    id: "run_001",
    status: "finished",
    metrics: {
      accuracy: 0.91,
      loss: 0.23,
    },
  },
  {
    id: "run_002",
    status: "failed",
    metrics: {
      accuracy: 0.7,
      loss: 0.9,
    },
  },
  {
    id: "run_003",
    status: "finished",
    metrics: {
      accuracy: 0.95,
      loss: 0.18,
    },
  },
];

function filterRuns(
  runs: ExperimentRun[],
  predicate: RunPredicate,
): ExperimentRun[] {
  return runs.filter(predicate);
}

function createStatusChecker(targetStatus: RunStatus): RunPredicate {
  return function check(run: ExperimentRun): boolean {
    return run.status === targetStatus;
  };
}

function createMetricFormatter(
  metricName: string,
  digits = 4,
): MetricFormatter {
  return function format(value: number): string {
    return `${metricName}=${value.toFixed(digits)}`;
  };
}

function withTiming<T>(name: string, task: () => T): T {
  const start = Date.now();

  const result = task();

  const duration = Date.now() - start;

  console.log(`[timing] ${name} took ${duration}ms`);

  return result;
}

function withLogging<T>(name: string, task: () => T): T {
  console.log(`[${name}] started`);

  const result = task();

  console.log(`[${name}] finished`);

  return result;
}

function withErrorBoundary<T>(
  name: string,
  task: () => T,
): T | null {
  try {
    return task();
  } catch (error) {
    console.error(`[${name}] failed`, error);

    return null;
  }
}

const isFinishedRun = createStatusChecker("finished");
const isFailedRun = createStatusChecker("failed");

const finishedRuns = withTiming("filter finished runs", () =>
  filterRuns(runs, isFinishedRun),
);

const failedRuns = withLogging("filter failed runs", () =>
  filterRuns(runs, isFailedRun),
);

const formatAccuracy = createMetricFormatter("accuracy", 2);

const formattedAccuracies = finishedRuns.map((run) => {
  const accuracy = run.metrics.accuracy ?? 0;

  return formatAccuracy(accuracy);
});

const parsed = withErrorBoundary("parse invalid json", () => {
  return JSON.parse("{ invalid json }") as unknown;
});

console.log("finished runs:", finishedRuns.map((run) => run.id));
console.log("failed runs:", failedRuns.map((run) => run.id));
console.log("formatted accuracies:", formattedAccuracies);
console.log("parsed:", parsed);

运行：

pnpm demo:higher-order

重点观察：

filterRuns 接收 predicate 函数。
createStatusChecker 返回 predicate 函数。
createMetricFormatter 返回 formatter 函数。
withTiming 接收 task 函数并返回 task 的结果。
withLogging 给任意任务加日志。
withErrorBoundary 给任意任务加错误捕获。

6. AI / 深度学习 / 论文复现 / 实验管理平台场景示例

6.1 实验 run 筛选器

type RunPredicate = (run: ExperimentRun) => boolean;

function createStatusChecker(targetStatus: RunStatus): RunPredicate {
  return function check(run: ExperimentRun): boolean {
    return run.status === targetStatus;
  };
}

const isFinishedRun = createStatusChecker("finished");
const isFailedRun = createStatusChecker("failed");

const finishedRuns = runs.filter(isFinishedRun);
const failedRuns = runs.filter(isFailedRun);

工程意义：

把“目标状态”保存进函数。
后续可以直接传给 filter。

6.2 metric 阈值筛选器

function createMetricThresholdFilter(
  metricName: string,
  threshold: number,
): RunPredicate {
  return function filterByMetric(run: ExperimentRun): boolean {
    const value = run.metrics[metricName];

    return typeof value === "number" && value >= threshold;
  };
}

const highAccuracyFilter = createMetricThresholdFilter("accuracy", 0.9);

const highAccuracyRuns = runs.filter(highAccuracyFilter);

用途：

筛选 accuracy >= 0.9 的实验。
筛选 f1 >= 0.8 的模型。
筛选 loss 达到目标的 run。

