6.5 Agent tool 执行 wrapper

type ToolExecutor = (args: unknown) => unknown;

function withToolLogging(
  toolName: string,
  executor: ToolExecutor,
): ToolExecutor {
  return function wrappedExecutor(args: unknown): unknown {
    console.log(`[tool:${toolName}] started`);

    const result = executor(args);

    console.log(`[tool:${toolName}] finished`);

    return result;
  };
}

使用：

const plotMetricCurve = withToolLogging(
  "plot_metric_curve",
  (args: unknown) => {
    console.log("plot args:", args);

    return {
      ok: true,
      chartId: "chart_001",
    };
  },
);

const result = plotMetricCurve({
  runIds: ["run_001", "run_003"],
  metricName: "accuracy",
