// src/logger.ts

export type Logger = (...messages: string[]) => void;

export function logInfo(scope: string, ...messages: string[]): void {
  console.log(`[${scope}] ${messages.join(" ")}`);
}

export function createLogger(scope: string): Logger {
  return function log(...messages: string[]): void {
    console.log(`[${scope}] ${messages.join(" ")}`);
  };
}

export function createPrefixedLogger(
  appName: string,
  scope: string,
): Logger {
  return function log(...messages: string[]): void {
    console.log(`[${appName}][${scope}] ${messages.join(" ")}`);
  };
}

export function withLogScope<T>(
  scope: string,
  task: () => T,
): T {
  const logger = createLogger(scope);

  logger("started");

  const result = task();

  logger("finished");

  return result;
}

export type LogContext = {
  scope: string;
};

export function logWithThis(
  this: LogContext,
  message: string,
): void {
  console.log(`[${this.scope}] ${message}`);
}

export function createBoundLogger(context: LogContext): (message: string) => void {
  return logWithThis.bind(context);
}

重点解释：

函数
