// src/run-utils.ts

import type {
  CreateRunInput,
  ExperimentRun,
  RunPredicate,
  RunStatus,
} from "./run-types.js";

export function createRun(input: CreateRunInput): ExperimentRun {
  return {
    id: input.id ?? `run_${Date.now()}`,
    experimentId: input.experimentId,
    status: input.status ?? "queued",
    metrics: input.metrics ?? {},
    startedAt: input.startedAt ?? new Date().toISOString(),
    ...(input.finishedAt !== undefined ? { finishedAt: input.finishedAt } : {}),
    ...(input.failedReason !== undefined ? { failedReason: input.failedReason } : {}),
  };
}

export function isTerminalRun(status: RunStatus): boolean {
  return status === "finished" || status === "failed";
}

export function createStatusChecker(targetStatus: RunStatus): RunPredicate {
  return function check(run: ExperimentRun): boolean {
    return run.status === targetStatus;
  };
}

export function filterRuns(
  runs: ExperimentRun[],
  predicate: RunPredicate,
): ExperimentRun[] {
  return runs.filter(predicate);
}

export function getRunsByStatus(
  runs: ExperimentRun[],
  targetStatus: RunStatus,
): ExperimentRun[] {
  return runs.filter((run) => run.status === targetStatus);
}

export function getMetricValues(
  runs: ExperimentRun[],
  metricName: string,
): number[] {
  return runs
    .map((run) => run.metrics[metricName])
    .filter((value): value is number => typeof value === "number");
}

export function createMetricThresholdFilter(
  metricName: string,
  threshold: number,
): RunPredicate {
  return function filterByMetric(run: ExperimentRun): boolean {
    const value = run.metrics[metricName];

    return typeof value === "number" && value >= threshold;
  };
}

export function sortRunsByMetricDesc(
  runs: ExperimentRun[],
  metricName: string,
): ExperimentRun[] {
  return [...runs].sort((a, b) => {
    const aValue = a.metrics[metricName] ?? Number.NEGATIVE_INFINITY;
    const bValue = b.metrics[metricName] ?? Number.NEGATIVE_INFINITY;

    return bValue - aValue;
  });
}

export function countRunsByStatus(
  runs: ExperimentRun[],
): Record<RunStatus, number> {
  const result: Record<RunStatus, number> = {
    queued: 0,
    running: 0,
    finished: 0,
    failed: 0,
  };

  for (const run of runs) {
    result[run.status] += 1;
  }

  return result;
}

重点解释：

函数
用到的知识
createRun
参数对象模式、默认值、??
createStatusChecker
返回函数、闭包
filterRuns
callback 参数
getRunsByStatus
callback + 闭包
getMetricValues
map + filter + 类型谓词
createMetricThresholdFilter
高阶函数
sortRunsByMetricDesc
callback 排序、浅拷贝
countRunsByStatus
块级作用域、循环变量

这里有一个重要点：

return [...runs].sort(...)

不要直接：

return runs.sort(...)

因为 sort 会修改原数组。

