写入代码：

// src/object-literal-demo.ts

type RunStatus = "queued" | "running" | "finished" | "failed";

type ExperimentRun = {
  id: string;
  experimentId: string;
  status: RunStatus;
  metrics: Record<string, number>;
  startedAt: string;
  finishedAt?: string;
  failedReason?: string;
};

const run: ExperimentRun = {
  id: "run_001",
  experimentId: "exp_001",
  status: "running",
  metrics: {
    accuracy: 0.91,
    loss: 0.23,
  },
  startedAt: "2026-06-25T10:00:00.000Z",
};

console.log("run id:", run.id);
console.log("run status:", run.status);
console.log("accuracy:", run.metrics.accuracy);

const metricName = "loss";

console.log("dynamic metric:", run.metrics[metricName]);

run.status = "finished";
run.finishedAt = "2026-06-25T10:30:00.000Z";

console.log("updated status:", run.status);
console.log("finished at:", run.finishedAt);

console.log("metric keys:", Object.keys(run.metrics));
console.log("metric values:", Object.values(run.metrics));
console.log("metric entries:", Object.entries(run.metrics));

for (const [name, value] of Object.entries(run.metrics)) {
  console.log(`${name}=${value}`);
}

const runSummary = {
  id: run.id,
  status: run.status,
  metricCount: Object.keys(run.metrics).length,
};

console.log("run summary:", runSummary);

const runs: ExperimentRun[] = [
  run,
  {
    id: "run_002",
    experimentId: "exp_001",
    status: "failed",
    metrics: {
      accuracy: 0.7,
      loss: 0.9,
    },
    startedAt: "2026-06-25T11:00:00.000Z",
    failedReason: "out of memory",
  },
];

const finishedRuns = runs.filter((item) => item.status === "finished");
const runIds = runs.map((item) => item.id);

console.log("finished runs:", finishedRuns);
console.log("run ids:", runIds);

运行：

pnpm demo:object

重点观察：

对象如何表示 run。
点语法如何读取固定字段。
方括号如何读取动态 metric。
对象属性如何被修改。
Object.keys / values / entries 如何遍历对象。
对象数组如何配合 map / filter 使用。

