type ExperimentRun = {
  id: string;
  experimentId: string;
  status: "queued" | "running" | "finished" | "failed";
  metrics: Record<string, number>;
};

const metricName = "accuracy";

const run: ExperimentRun = {
  id: "run_001",
  experimentId: "exp_001",
  status: "finished",
  metrics: {
    [metricName]: 0.91,
    loss: 0.23,
  },
};

const value = run.metrics[metricName];

const statusLabels: Record<ExperimentRun["status"], string> = {
  queued: "Queued",
  running: "Running",
  finished: "Finished",
  failed: "Failed",
};

