5. 最小可运行示例

创建文件：

New-Item src/object-destructure-demo.ts

在 package.json 添加：

{
  "scripts": {
    "demo:object-destructure": "tsx src/object-destructure-demo.ts"
  }
}

写入代码：

// src/object-destructure-demo.ts

type RunStatus = "queued" | "running" | "finished" | "failed";

type ExperimentRun = {
  id: string;
  experimentId: string;
  status: RunStatus;
  metrics: Record<string, number>;
  startedAt: string;
  finishedAt?: string;
  failedReason?: string;
  internalErrorStack?: string;
};

type CreateRunInput = {
  id?: string;
  experimentId: string;
  status?: RunStatus;
  metrics?: Record<string, number>;
  startedAt?: string;
};

const run: ExperimentRun = {
  id: "run_001",
  experimentId: "exp_001",
  status: "finished",
  metrics: {
    accuracy: 0.91,
    loss: 0.23,
  },
  startedAt: "2026-06-25T10:00:00.000Z",
  finishedAt: "2026-06-25T10:30:00.000Z",
  internalErrorStack: "internal stack trace",
};

// 1. 基础解构
const { id, status, metrics } = run;

console.log("id:", id);
console.log("status:", status);
console.log("accuracy:", metrics.accuracy);

// 2. 重命名
const { id: runId, experimentId } = run;

console.log("runId:", runId);
console.log("experimentId:", experimentId);

// 3. 嵌套解构
const {
  metrics: { accuracy, loss },
} = run;

console.log("accuracy:", accuracy);
console.log("loss:", loss);

// 4. 剩余属性：去掉内部字段
const { internalErrorStack, ...publicRun } = run;

console.log("publicRun:", publicRun);
console.log("internalErrorStack:", internalErrorStack);

// 5. 参数对象解构 + 默认值
function createRun({
  id = `run_${Date.now()}`,
  experimentId,
  status = "queued",
  metrics = {},
  startedAt = new Date().toISOString(),
}: CreateRunInput): ExperimentRun {
  return {
    id,
    experimentId,
    status,
    metrics,
    startedAt,
  };
}

const newRun = createRun({
  experimentId: "exp_002",
});

console.log("newRun:", newRun);

// 6. 参数解构
function formatRunSummary({
  id,
  status,
}: ExperimentRun): string {
  return `${id} | ${status}`;
}

console.log("summary:", formatRunSummary(run));

// 7. rest 是浅拷贝
const { id: omittedId, ...restRun } = run;

console.log("restRun === run:", restRun === run);
console.log("restRun.metrics === run.metrics:", restRun.metrics === run.metrics);

restRun.metrics.accuracy = 0.95;

console.log("run.metrics.accuracy:", run.metrics.accuracy);
console.log("restRun.metrics.accuracy:", restRun.metrics.accuracy);

运行：

pnpm demo:object-destructure

重点观察：

基础解构如何提取字段。
重命名如何避免多个 id 混淆。
嵌套解构如何提取 metrics.accuracy。
rest 如何去掉 internalErrorStack。
参数解构如何处理 CreateRunInput。
rest 是浅拷贝，嵌套 metrics 仍然共享引用。

