    "demo:object-types": "tsx src/object-type-fields-demo.ts"
  }
}

写入代码：

// src/object-type-fields-demo.ts

type RunStatus = "queued" | "running" | "finished" | "failed";

type ExperimentRun = {
  readonly id: string;
  readonly experimentId: string;
  status: RunStatus;
  metrics: Record<string, number>;
  startedAt: string;
  finishedAt?: string;
  failedReason?: string;
  metadata?: Record<string, unknown>;
};

const run: ExperimentRun = {
  id: "run_001",
  experimentId: "exp_001",
  status: "running",
  metrics: {
    accuracy: 0.91,
    loss: 0.23,
  },
  startedAt: "2026-06-25T10:00:00.000Z",
};

// run.id = "run_002"; // ❌ readonly，不能重新赋值

run.status = "finished";
run.finishedAt = "2026-06-25T10:30:00.000Z";

const accuracy = run.metrics["accuracy"];

console.log("accuracy:", accuracy);

const metricName = "f1";

run.metrics[metricName] = 0.89;

console.log("metrics:", run.metrics);

function formatFinishedAt(run: ExperimentRun): string {
  return run.finishedAt ?? "not finished";
}

console.log("finishedAt:", formatFinishedAt(run));

const statusLabels: Record<RunStatus, string> = {
  queued: "Queued",
  running: "Running",
  finished: "Finished",
  failed: "Failed",
};

const statusColors: Record<RunStatus, string> = {
  queued: "gray",
  running: "blue",
  finished: "green",
  failed: "red",
};

console.log("status label:", statusLabels[run.status]);
console.log("status color:", statusColors[run.status]);

type ExperimentConfig = {
  seed: number;
  batchSize: number;
  learningRate: number;
  useAmp?: boolean;
  metadata?: Record<string, unknown>;
};

const config: ExperimentConfig = {
  seed: 42,
  batchSize: 32,
  learningRate: 0.00002,
  metadata: {
    source: "paper-reproduction",
    note: "baseline",
  },
};

function formatConfig(config: ExperimentConfig): string {
  const useAmp = config.useAmp ?? false;

  return `seed=${config.seed}, batchSize=${config.batchSize}, lr=${config.learningRate}, useAmp=${useAmp}`;
}

console.log(formatConfig(config));

const readonlyRun: Readonly<ExperimentRun> = run;

// readonlyRun.status = "failed"; // ❌ Readonly 第一层只读

console.log("readonlyRun:", readonlyRun);

运行：

pnpm demo:object-types

重点观察：

readonly id 不能重新赋值。
status 可以更新。
finishedAt 是可选属性，读取时要处理 undefined。
metrics 用 Record<string, number> 表示动态 metric map。
Record<RunStatus, string> 能强制完整覆盖所有状态。
Readonly<ExperimentRun> 会把第一层属性变成只读。

6. AI / 深度学习 / 论文复现 / 实验管理平台场景示例

6.1 ExperimentRun 类型

type RunStatus = "queued" | "running" | "finished" | "failed";

type ExperimentRun = {
  readonly id: string;
  readonly experimentId: string;
  status: RunStatus;
  metrics: Record<string, number>;
  startedAt: string;
  finishedAt?: string;
  failedReason?: string;
};

设计理由：

id 不应该变 → readonly
experimentId 不应该变 → readonly
status 会变化 → 非 readonly
metrics 动态变化 → Record<string, number>
finishedAt 只有完成后有 → ?
failedReason 只有失败后有 → ?

6.2 ExperimentConfig 类型

固定配置：

type ExperimentConfig = {
  seed: number;
  batchSize: number;
  learningRate: number;
  epochs: number;
  optimizer: "adamw" | "sgd";
  useAmp?: boolean;
};

如果配置非常灵活：

type FlexibleConfig = Record<string, string | number | boolean>;

工程建议：

论文复现常用参数明确时 → 写固定 type
插件扩展配置不确定时 → 用 Record
外部未知配置 → unknown + validate

6.3 Metric map

type Metrics = Record<string, number>;

const metrics: Metrics = {
  accuracy: 0.91,
  loss: 0.23,
  f1: 0.89,
};

动态读取：

function getMetric(
  metrics: Metrics,
  metricName: string,
): number | undefined {
  return metrics[metricName];
}

注意返回值建议写成：

number | undefined

因为动态 key 可能不存在。

6.4 Status label / color 映射

type RunStatus = "queued" | "running" | "finished" | "failed";

const statusLabels: Record<RunStatus, string> = {
  queued: "Queued",
