15. 最小可运行示例

创建文件：

New-Item src/class-access-demo.ts

在 package.json 添加：

{
  "scripts": {
    "demo:class-access": "tsx src/class-access-demo.ts"
  }
}

写入：

// src/class-access-demo.ts

type RunStatus = "queued" | "running" | "finished" | "failed";

type ExperimentRun = {
  readonly id: string;
  readonly experimentId: string;
  status: RunStatus;
  metrics: Record<string, number>;
  startedAt: string;
  finishedAt?: string;
  failedReason?: string;
};

type CreateRunInput = {
  id?: string;
  experimentId: string;
  status?: RunStatus;
  metrics?: Record<string, number>;
};

type Logger = {
  log(message: string): void;
};

class ConsoleLogger implements Logger {
  constructor(private readonly scope: string) {}

  log(message: string): void {
    console.log(`[${this.scope}] ${message}`);
  }
}

class RunService {
  private readonly runs: ExperimentRun[] = [];

  constructor(private readonly logger: Logger) {}

  createRun({
    id = `run_${Date.now()}`,
    experimentId,
    status = "queued",
    metrics = {},
  }: CreateRunInput): ExperimentRun {
    this.assertValidExperimentId(experimentId);

    const run: ExperimentRun = {
      id,
      experimentId,
      status,
      metrics,
      startedAt: new Date().toISOString(),
    };

    this.runs.push(run);

    this.logger.log(`created run ${run.id}`);

    return run;
  }

  getAllRuns(): ExperimentRun[] {
    return [...this.runs];
  }

  getReadonlyRuns(): ReadonlyArray<ExperimentRun> {
    return this.runs;
  }

  getRunsByStatus(status: RunStatus): ExperimentRun[] {
    return this.runs.filter((run) => run.status === status);
  }

  finishRun(
    runId: string,
    finishedAt = new Date().toISOString(),
  ): ExperimentRun | null {
    const run = this.findRunById(runId);

    if (run === null) {
      return null;
    }

    run.status = "finished";
    run.finishedAt = finishedAt;

    this.logger.log(`finished run ${run.id}`);

    return run;
  }

  failRun(
    runId: string,
    failedReason: string,
  ): ExperimentRun | null {
    const run = this.findRunById(runId);

    if (run === null) {
      return null;
    }

    run.status = "failed";
    run.failedReason = failedReason;

    this.logger.log(`failed run ${run.id}: ${failedReason}`);

    return run;
  }

  private findRunById(runId: string): ExperimentRun | null {
    const run = this.runs.find((item) => item.id === runId);

    return run ?? null;
  }

  private assertValidExperimentId(experimentId: string): void {
    if (experimentId.trim().length === 0) {
      throw new Error("experimentId is required");
    }
  }
}

class BaseService {
  constructor(protected readonly logger: Logger) {}

  protected log(message: string): void {
    this.logger.log(message);
  }
}

class ProjectService extends BaseService {
  createProject(projectName: string): void {
    this.log(`created project ${projectName}`);
  }
}

const logger = new ConsoleLogger("labpilot");

const runService = new RunService(logger);

const run1 = runService.createRun({
  id: "run_001",
  experimentId: "exp_001",
  metrics: {
    accuracy: 0.91,
  },
});

const run2 = runService.createRun({
  id: "run_002",
  experimentId: "exp_001",
  status: "running",
  metrics: {
    accuracy: 0.82,
  },
});

runService.finishRun("run_001");

console.log("run1:", run1);
console.log("run2:", run2);
console.log("all runs:", runService.getAllRuns());
console.log("finished runs:", runService.getRunsByStatus("finished"));

const readonlyRuns = runService.getReadonlyRuns();

console.log("readonly runs:", readonlyRuns);

// readonlyRuns.push(run1); // ❌ ReadonlyArray 不允许 push

const projectService = new ProjectService(logger);

projectService.createProject("BERT Fine-tuning");

// runService.runs; // ❌ private
// runService.findRunById("run_001"); // ❌ private
// projectService.logger; // ❌ protected
// projectService.log("hello"); // ❌ protected

运行：

pnpm demo:class-access

重点观察：

private runs 外部不能访问。
private findRunById 只能 class 内部调用。
private readonly logger 初始化后不能替换。
protected logger 可以被子类 ProjectService 使用。
getAllRuns 返回浅拷贝数组。
getReadonlyRuns 返回只读数组类型。

