// src/entities/experiment.ts

export type ExperimentConfig = {
  seed: number;
  batchSize: number;
  learningRate: number;
  epochs: number;
  optimizer: "adamw" | "sgd";
  useAmp?: boolean;
  metadata?: Record<string, unknown>;
};

export type Experiment = {
  readonly id: string;
  readonly projectId: string;
  name: string;
  tags: string[];
  config: ExperimentConfig;
  createdAt: string;
  updatedAt: string;
};

export type CreateExperimentInput = {
  id?: string;
  projectId: string;
  name: string;
  tags?: string[];
  config?: Partial<ExperimentConfig>;
  createdAt?: string;
  updatedAt?: string;
};

export type UpdateExperimentInput = {
  name?: string;
  tags?: string[];
  config?: Partial<ExperimentConfig>;
};

const DEFAULT_EXPERIMENT_CONFIG: ExperimentConfig = {
  seed: 42,
  batchSize: 32,
  learningRate: 0.00002,
  epochs: 3,
  optimizer: "adamw",
};

function createExperimentId(): string {
  return `exp_${Date.now()}`;
}

export function normalizeExperimentConfig(
  config: Partial<ExperimentConfig> = {},
): ExperimentConfig {
  return {
    ...DEFAULT_EXPERIMENT_CONFIG,
    ...config,
    metadata:
      config.metadata !== undefined
        ? {
            ...config.metadata,
          }
        : DEFAULT_EXPERIMENT_CONFIG.metadata,
  };
}

export function createExperiment({
  id = createExperimentId(),
  projectId,
  name,
  tags = [],
  config = {},
  createdAt = new Date().toISOString(),
  updatedAt = createdAt,
}: CreateExperimentInput): Experiment {
  return {
    id,
    projectId,
    name,
    tags: [...tags],
    config: normalizeExperimentConfig(config),
    createdAt,
    updatedAt,
  };
}

export function updateExperiment(
  experiment: Experiment,
  input: UpdateExperimentInput,
  updatedAt = new Date().toISOString(),
): Experiment {
  return {
    ...experiment,
    ...(input.name !== undefined ? { name: input.name } : {}),
    ...(input.tags !== undefined ? { tags: [...input.tags] } : {}),
    ...(input.config !== undefined
      ? {
          config: {
            ...experiment.config,
            ...input.config,
            metadata:
              input.config.metadata !== undefined
                ? {
                    ...input.config.metadata,
                  }
                : experiment.config.metadata,
          },
        }
      : {}),
    updatedAt,
  };
}

export function addExperimentTag(
  experiment: Experiment,
  tag: string,
  updatedAt = new Date().toISOString(),
): Experiment {
  const normalizedTag = tag.trim();

  if (normalizedTag.length === 0) {
    return experiment;
  }

  if (experiment.tags.includes(normalizedTag)) {
    return experiment;
  }

  return {
    ...experiment,
    tags: [...experiment.tags, normalizedTag],
    updatedAt,
  };
}

export function removeExperimentTag(
  experiment: Experiment,
  tag: string,
  updatedAt = new Date().toISOString(),
): Experiment {
  return {
    ...experiment,
    tags: experiment.tags.filter((item) => item !== tag),
    updatedAt,
  };
}

5.3 设计分析

重点一：DEFAULT_EXPERIMENT_CONFIG 没有 export。

const DEFAULT_EXPERIMENT_CONFIG: ExperimentConfig = {
  seed: 42,
  batchSize: 32,
  learningRate: 0.00002,
  epochs: 3,
  optimizer: "adamw",
};

它是内部默认值。

外部不需要依赖它。

重点二：tags: [...tags]

tags: [...tags],

这是数组浅拷贝。

目的：

避免外部传入的 tags 数组被后续修改时影响 Experiment 内部 tags。

重点三：更新 config 时逐层展开：

config: {
  ...experiment.config,
  ...input.config,
}

因为 config 是嵌套对象，不能直接原地修改。

