// src/entities/run.ts

export type RunStatus = "queued" | "running" | "finished" | "failed";

export type ExperimentRun = {
  readonly id: string;
  readonly experimentId: string;
  status: RunStatus;
  metrics: Record<string, number>;
  startedAt: string;
  finishedAt?: string;
  failedReason?: string;
  metadata?: Record<string, unknown>;
};

export type CreateRunInput = {
  id?: string;
  experimentId: string;
  status?: RunStatus;
  metrics?: Record<string, number>;
  startedAt?: string;
  metadata?: Record<string, unknown>;
};

export type PublicExperimentRun = {
  readonly id: string;
  readonly experimentId: string;
  status: RunStatus;
  metrics: Record<string, number>;
  startedAt: string;
  finishedAt?: string;
  failedReason?: string;
};

function createRunId(): string {
  return `run_${Date.now()}`;
}

export function createRun({
  id = createRunId(),
  experimentId,
  status = "queued",
  metrics = {},
  startedAt = new Date().toISOString(),
  metadata,
}: CreateRunInput): ExperimentRun {
  return {
    id,
    experimentId,
    status,
    metrics: {
      ...metrics,
    },
    startedAt,
    ...(metadata !== undefined
      ? {
          metadata: {
            ...metadata,
          },
        }
      : {}),
  };
}

export function startRun(
  run: ExperimentRun,
): ExperimentRun {
  return {
    ...run,
    status: "running",
  };
}

export function finishRun(
  run: ExperimentRun,
  finishedAt = new Date().toISOString(),
): ExperimentRun {
  return {
    ...run,
    status: "finished",
    finishedAt,
  };
}

export function failRun(
  run: ExperimentRun,
  failedReason: string,
): ExperimentRun {
  return {
    ...run,
    status: "failed",
    failedReason,
  };
}

export function updateRunMetric(
  run: ExperimentRun,
  metricName: string,
  value: number,
): ExperimentRun {
  return {
    ...run,
    metrics: {
      ...run.metrics,
      [metricName]: value,
    },
  };
}

export function removeRunMetric(
  run: ExperimentRun,
  metricName: string,
): ExperimentRun {
  const { [metricName]: removedMetric, ...remainingMetrics } = run.metrics;

  void removedMetric;

  return {
    ...run,
    metrics: remainingMetrics,
  };
}

export function isTerminalRun(run: ExperimentRun): boolean {
  return run.status === "finished" || run.status === "failed";
}

export function isSuccessfulRun(run: ExperimentRun): boolean {
  return run.status === "finished";
}

export function isFailedRun(run: ExperimentRun): boolean {
  return run.status === "failed";
}

export function toPublicRun(run: ExperimentRun): PublicExperimentRun {
  const { metadata, ...publicRun } = run;

  void metadata;

  return {
    ...publicRun,
    metrics: {
      ...publicRun.metrics,
    },
  };
}

