// src/utils/metric-utils.ts

export type MetricMap = Record<string, number>;

export function formatMetric(value: number, digits = 4): string {
  return value.toFixed(digits);
}

export function formatPercent(value: number, digits = 2): string {
  return `${(value * 100).toFixed(digits)}%`;
}

export function formatNamedMetric(
  metricName: string,
  value: number,
  digits = 4,
): string {
  return `${metricName}=${value.toFixed(digits)}`;
}

export function getMetricValue(
  metrics: MetricMap,
  metricName: string,
): number | undefined {
  return metrics[metricName];
}

export function countMetrics(metrics: MetricMap): number {
  return Object.keys(metrics).length;
}

export function getMetricNames(metrics: MetricMap): string[] {
  return Object.keys(metrics);
}

export function getMetricEntries(metrics: MetricMap): Array<[string, number]> {
  return Object.entries(metrics);
}

export function mergeMetrics(
  baseMetrics: MetricMap,
  patchMetrics: MetricMap,
): MetricMap {
  return {
    ...baseMetrics,
    ...patchMetrics,
  };
}

export function pickMetrics(
  metrics: MetricMap,
  metricNames: string[],
): MetricMap {
  const result: MetricMap = {};

  for (const metricName of metricNames) {
    const value = metrics[metricName];

    if (value !== undefined) {
      result[metricName] = value;
    }
  }

  return result;
}

export function sortMetricEntriesDesc(
  metrics: MetricMap,
): Array<[string, number]> {
  return Object.entries(metrics).sort(([, aValue], [, bValue]) => {
    return bValue - aValue;
  });
}

