// src/utils/object-utils.ts

export type UnknownRecord = Record<string, unknown>;

export function isRecord(value: unknown): value is UnknownRecord {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function shallowClone<T extends object>(value: T): T {
  return {
    ...value,
  };
}

export function omitUndefinedFields<T extends UnknownRecord>(
  value: T,
): UnknownRecord {
  const result: UnknownRecord = {};

  for (const [key, fieldValue] of Object.entries(value)) {
    if (fieldValue !== undefined) {
      result[key] = fieldValue;
    }
  }

  return result;
}

export function omitKey<T extends UnknownRecord>(
  value: T,
  keyToOmit: string,
): UnknownRecord {
  const { [keyToOmit]: omittedValue, ...rest } = value;

  void omittedValue;

  return rest;
}

export function hasOwnKey(
  value: UnknownRecord,
  key: string,
): boolean {
  return Object.hasOwn(value, key);
}

