// src/services/run-service.ts

import {
  createRun,
  failRun,
  finishRun,
  startRun,
  toPublicRun,
  updateRunMetric,
  type CreateRunInput,
  type ExperimentRun,
  type PublicExperimentRun,
  type RunStatus,
} from "../entities/run.js";

export type Logger = {
  log(message: string): void;
};

export class RunService {
  private readonly runs: ExperimentRun[] = [];

  constructor(private readonly logger: Logger) {}

  create(input: CreateRunInput): ExperimentRun {
    const run = createRun(input);

    this.runs.push(run);

    this.logger.log(`created run ${run.id}`);

    return run;
  }

  list(): ExperimentRun[] {
    return this.runs.map((run) => ({
      ...run,
      metrics: {
        ...run.metrics,
      },
      ...(run.metadata !== undefined
        ? {
            metadata: {
              ...run.metadata,
            },
          }
        : {}),
    }));
  }

  listPublic(): PublicExperimentRun[] {
    return this.runs.map(toPublicRun);
  }

  listByStatus(status: RunStatus): ExperimentRun[] {
    return this.list().filter((run) => run.status === status);
  }

  getById(runId: string): ExperimentRun | null {
    const run = this.findById(runId);

    if (run === null) {
      return null;
    }

    return {
      ...run,
      metrics: {
        ...run.metrics,
      },
      ...(run.metadata !== undefined
        ? {
            metadata: {
              ...run.metadata,
            },
          }
        : {}),
    };
  }

  start(runId: string): ExperimentRun | null {
    const run = this.findById(runId);

    if (run === null) {
      return null;
    }

    const updatedRun = startRun(run);

    this.replaceRun(updatedRun);

    this.logger.log(`started run ${runId}`);

    return updatedRun;
  }

  finish(runId: string): ExperimentRun | null {
    const run = this.findById(runId);

    if (run === null) {
      return null;
    }

    const updatedRun = finishRun(run);

    this.replaceRun(updatedRun);

    this.logger.log(`finished run ${runId}`);

    return updatedRun;
  }

  fail(runId: string, failedReason: string): ExperimentRun | null {
    const run = this.findById(runId);

    if (run === null) {
      return null;
    }

    const updatedRun = failRun(run, failedReason);

    this.replaceRun(updatedRun);

    this.logger.log(`failed run ${runId}: ${failedReason}`);

    return updatedRun;
  }

  updateMetric(
    runId: string,
    metricName: string,
    value: number,
  ): ExperimentRun | null {
    const run = this.findById(runId);

    if (run === null) {
      return null;
    }

    const updatedRun = updateRunMetric(run, metricName, value);

    this.replaceRun(updatedRun);

    this.logger.log(`updated ${metricName} for run ${runId}`);

    return updatedRun;
  }

  private findById(runId: string): ExperimentRun | null {
    return this.runs.find((run) => run.id === runId) ?? null;
  }

  private replaceRun(updatedRun: ExperimentRun): void {
    const index = this.runs.findIndex((run) => run.id === updatedRun.id);

    if (index === -1) {
      return;
    }

    this.runs[index] = updatedRun;
  }
}

9.3 设计分析

为什么 runs 是 private readonly

private readonly runs: ExperimentRun[] = [];

含义：

private：外部不能直接访问 runs。
readonly：this.runs 不能被重新赋值成另一个数组。

但数组内容仍然可以 push / replace：

this.runs.push(run);
this.runs[index] = updatedRun;

这正是我们想要的：

外部不能乱改。
class 内部可以维护状态。

为什么 list() 不直接返回 this.runs

不推荐：

list(): ExperimentRun[] {
  return this.runs;
}

因为外部可以：

const runs = service.list();
runs.length = 0;

这会清空内部数组。

所以这里返回拷贝：

return this.runs.map((run) => ({
  ...run,
  metrics: {
    ...run.metrics,
  },
}));

这比简单 [...this.runs] 更进一步，因为它也拷贝了每个 run 的第一层和 metrics。

注意：如果 metadata 内部还有更深层对象，仍然是浅拷贝。当前阶段足够。

为什么 findById 是 private

private findById(runId: string): ExperimentRun | null {}

它只是内部 helper。

外部不应该依赖它。

外部如果要查 run，用：

getById(runId)

这就是 public API 和 private implementation 的区别。

