10.2 代码

// src/services/tool-registry-service.ts

import type { Logger } from "./run-service.js";

export type ToolExecutor = (args: unknown) => unknown;

export type ToolCallResult =
  | {
      ok: true;
      toolName: string;
      result: unknown;
    }
  | {
      ok: false;
      toolName: string;
      error: string;
    };

export class ToolRegistryService {
  private readonly tools: Record<string, ToolExecutor> = {};

  constructor(private readonly logger: Logger) {}

  register(toolName: string, executor: ToolExecutor): void {
    if (toolName.trim().length === 0) {
      throw new Error("toolName is required");
    }

    if (this.tools[toolName] !== undefined) {
      throw new Error(`Tool already registered: ${toolName}`);
    }

    this.tools[toolName] = executor;

    this.logger.log(`registered tool ${toolName}`);
  }

  call(toolName: string, args: unknown): ToolCallResult {
    const executor = this.tools[toolName];

    if (executor === undefined) {
      return {
        ok: false,
        toolName,
        error: `Unknown tool: ${toolName}`,
      };
    }

    this.logger.log(`calling tool ${toolName}`);

    const result = executor(args);

    return {
      ok: true,
      toolName,
      result,
    };
  }

  hasTool(toolName: string): boolean {
    return this.tools[toolName] !== undefined;
  }

  listToolNames(): string[] {
    return Object.keys(this.tools);
  }
}

10.3 设计分析

这里用到了：

Record<string, ToolExecutor>
class
private readonly
public methods
动态 key
联合类型 ToolCallResult

为什么 tools 不 public？

如果 public，外部可以绕过 register 的校验。
例如重复注册、空名字注册、把工具改成 undefined。

所以：

private readonly tools: Record<string, ToolExecutor> = {};

外部只能通过：

register(...)
call(...)
hasTool(...)
listToolNames(...)

这就是 class 的封装价值。

