11.3 为什么不用 export *

你当然可以写：

export * from "./entities/project.js";
export * from "./entities/experiment.js";
export * from "./entities/run.js";
export * from "./utils/metric-utils.js";
export * from "./utils/object-utils.js";
export * from "./services/run-service.js";
export * from "./services/tool-registry-service.js";

但这次综合练习更推荐精确导出。

原因：

训练你控制 public API。
明确区分 type export 和 value export。
避免不小心导出内部内容。

12. 文件 9：src/object-module-demo.ts

12.1 文件职责

demo 文件负责组合调用整个工具包。

它不应该从 index.ts 导出。

它只通过 script 运行。

12.2 代码

// src/object-module-demo.ts

import {
  RunService,
  ToolRegistryService,
  addExperimentTag,
  createExperiment,
  createProject,
  formatPercent,
  getMetricValue,
  renameProject,
  updateExperiment,
  type Logger,
} from "./index.js";

const logger: Logger = {
  log(message: string): void {
    console.log(`[LabPilot demo] ${message}`);
  },
};

const project = createProject({
  id: "proj_001",
  name: "BERT Fine-tuning",
  description: "Fine-tune BERT on sentiment classification dataset",
});

const renamedProject = renameProject(project, "BERT Sentiment Classification");

console.log("project:", project);
console.log("renamed project:", renamedProject);

const experiment = createExperiment({
  id: "exp_001",
  projectId: project.id,
  name: "bert-base baseline",
  tags: ["baseline", "bert"],
  config: {
    seed: 42,
    batchSize: 32,
    learningRate: 0.00002,
    epochs: 3,
    optimizer: "adamw",
    useAmp: true,
  },
});

const taggedExperiment = addExperimentTag(experiment, "reproduction");

const updatedExperiment = updateExperiment(taggedExperiment, {
  config: {
    learningRate: 0.00001,
  },
});

console.log("experiment:", experiment);
console.log("tagged experiment:", taggedExperiment);
console.log("updated experiment:", updatedExperiment);

const runService = new RunService(logger);

const run1 = runService.create({
  id: "run_001",
  experimentId: experiment.id,
  metrics: {
    accuracy: 0.912345,
    loss: 0.23,
  },
  metadata: {
    device: "cuda:0",
    checkpoint: "ckpt_001.pt",
  },
});

const run2 = runService.create({
  id: "run_002",
  experimentId: experiment.id,
  status: "running",
  metrics: {
    accuracy: 0.82,
    loss: 0.4,
  },
});

runService.start("run_002");
runService.updateMetric("run_002", "accuracy", 0.88);
runService.finish("run_001");
runService.fail("run_002", "out of memory");

console.log("run1:", run1);
console.log("run2:", run2);
console.log("all runs:", runService.list());
console.log("public runs:", runService.listPublic());
console.log("finished runs:", runService.listByStatus("finished"));
console.log("failed runs:", runService.listByStatus("failed"));

const finishedRuns = runService.listByStatus("finished");
const firstFinishedRun = finishedRuns[0];

if (firstFinishedRun !== undefined) {
  const accuracy = getMetricValue(firstFinishedRun.metrics, "accuracy");

  if (accuracy !== undefined) {
    console.log("best accuracy:", formatPercent(accuracy));
  }
}

const toolRegistry = new ToolRegistryService(logger);

toolRegistry.register("summarize_runs", (args: unknown): unknown => {
  return {
    summary: "Runs summarized by demo tool",
    args,
  };
});

toolRegistry.register("plot_metric_curve", (args: unknown): unknown => {
  return {
    chartType: "line",
    args,
  };
});

console.log("tool names:", toolRegistry.listToolNames());

const summarizeResult = toolRegistry.call("summarize_runs", {
  runIds: ["run_001", "run_002"],
});

const plotResult = toolRegistry.call("plot_metric_curve", {
  runIds: ["run_001", "run_002"],
  metricName: "accuracy",
});

const unknownResult = toolRegistry.call("unknown_tool", {});

console.log("summarize result:", summarizeResult);
console.log("plot result:", plotResult);
console.log("unknown result:", unknownResult);

