12. 最小可运行示例

创建文件：

New-Item src/array-map-demo.ts

在 package.json 添加：

{
  "scripts": {
    "demo:array-map": "tsx src/array-map-demo.ts"
  }
}

写入代码：

// src/array-map-demo.ts

type RunStatus = "queued" | "running" | "finished" | "failed";

type ExperimentRun = {
  readonly id: string;
  readonly experimentId: string;
  status: RunStatus;
  metrics: Record<string, number>;
  startedAt: string;
  finishedAt?: string;
  failedReason?: string;
};

type RunTableRow = {
  id: string;
  experimentId: string;
  status: RunStatus;
  accuracy: number | null;
  loss: number | null;
  metricCount: number;
  startedAt: string;
  finishedAt: string | null;
};

type MetricChartPoint = {
  runId: string;
  value: number | null;
};

const runs: ExperimentRun[] = [
  {
    id: "run_001",
    experimentId: "exp_001",
    status: "finished",
    metrics: {
      accuracy: 0.912345,
      loss: 0.23,
    },
    startedAt: "2026-06-25T10:00:00.000Z",
    finishedAt: "2026-06-25T10:30:00.000Z",
  },
  {
    id: "run_002",
    experimentId: "exp_001",
    status: "failed",
    metrics: {
      accuracy: 0.7,
      loss: 0.9,
    },
    startedAt: "2026-06-25T11:00:00.000Z",
    failedReason: "out of memory",
  },
  {
    id: "run_003",
    experimentId: "exp_002",
    status: "running",
    metrics: {
      loss: 0.4,
    },
    startedAt: "2026-06-25T12:00:00.000Z",
  },
];

// 1. ExperimentRun[] -> string[]
const runIds = runs.map((run) => {
  return run.id;
});

console.log("runIds:", runIds);

// 2. 使用 index
const runLabels = runs.map((run, index) => {
  return `${index + 1}. ${run.id}`;
});

console.log("runLabels:", runLabels);

// 3. ExperimentRun[] -> RunTableRow[]
function createRunTableRows(runs: ExperimentRun[]): RunTableRow[] {
  return runs.map((run) => {
    return {
      id: run.id,
      experimentId: run.experimentId,
      status: run.status,
      accuracy: run.metrics.accuracy ?? null,
      loss: run.metrics.loss ?? null,
      metricCount: Object.keys(run.metrics).length,
      startedAt: run.startedAt,
      finishedAt: run.finishedAt ?? null,
    };
  });
}

const rows = createRunTableRows(runs);

console.log("rows:", rows);

// 4. ExperimentRun[] -> MetricChartPoint[]
function createMetricChartData(
  runs: ExperimentRun[],
  metricName: string,
): MetricChartPoint[] {
  return runs.map((run) => {
    return {
      runId: run.id,
      value: run.metrics[metricName] ?? null,
    };
  });
}

const accuracyChartData = createMetricChartData(runs, "accuracy");

console.log("accuracyChartData:", accuracyChartData);

// 5. map 不修改原数组
const finishedCopies = runs.map((run) => {
  return {
    ...run,
    status: "finished" as const,
  };
});

console.log("original runs:", runs);
console.log("finishedCopies:", finishedCopies);

// 6. 不推荐：map 里修改原对象
const badUpdatedRuns = runs.map((run) => {
  run.status = "finished";

  return run;
});

console.log("badUpdatedRuns:", badUpdatedRuns);
console.log("runs after bad update:", runs);

运行：

pnpm demo:array-map

重点观察：

runIds 是 string[]。
rows 是 RunTableRow[]。
accuracyChartData 中缺失 accuracy 的 run 会得到 null。
finishedCopies 没有直接改原对象。
badUpdatedRuns 会修改原 runs 中的对象。

