13. 最小可运行示例

创建文件：

New-Item src/array-filter-demo.ts

在 package.json 添加：

{
  "scripts": {
    "demo:array-filter": "tsx src/array-filter-demo.ts"
  }
}

写入代码：

// src/array-filter-demo.ts

type RunStatus = "queued" | "running" | "finished" | "failed";

type ExperimentRun = {
  readonly id: string;
  readonly experimentId: string;
  status: RunStatus;
  metrics: Record<string, number>;
  startedAt: string;
  finishedAt?: string;
  failedReason?: string;
};

function isDefined<T>(value: T | undefined): value is T {
  return value !== undefined;
}

const runs: ExperimentRun[] = [
  {
    id: "run_001",
    experimentId: "exp_001",
    status: "finished",
    metrics: {
      accuracy: 0.912345,
      loss: 0.23,
    },
    startedAt: "2026-06-25T10:00:00.000Z",
    finishedAt: "2026-06-25T10:30:00.000Z",
  },
  {
    id: "run_002",
    experimentId: "exp_001",
    status: "failed",
    metrics: {
      accuracy: 0.7,
      loss: 0.9,
    },
    startedAt: "2026-06-25T11:00:00.000Z",
    failedReason: "out of memory",
  },
  {
    id: "run_003",
    experimentId: "exp_002",
    status: "running",
    metrics: {
      loss: 0.4,
    },
    startedAt: "2026-06-25T12:00:00.000Z",
  },
  {
    id: "run_004",
    experimentId: "exp_002",
    status: "finished",
    metrics: {
      accuracy: 0,
      loss: 0.5,
    },
    startedAt: "2026-06-25T13:00:00.000Z",
    finishedAt: "2026-06-25T13:20:00.000Z",
  },
];

// 1. 按状态筛选
const finishedRuns = runs.filter((run) => {
  return run.status === "finished";
});

console.log("finishedRuns:", finishedRuns);

// 2. 按 experimentId 筛选
const exp001Runs = runs.filter((run) => {
  return run.experimentId === "exp_001";
});

console.log("exp001Runs:", exp001Runs);

// 3. 筛选有 accuracy 的 runs
const runsWithAccuracy = runs.filter((run) => {
  return run.metrics.accuracy !== undefined;
});

console.log("runsWithAccuracy:", runsWithAccuracy);

// 4. 筛选 accuracy >= 0.9
const highAccuracyRuns = runs.filter((run) => {
  const accuracy = run.metrics.accuracy;

  return accuracy !== undefined && accuracy >= 0.9;
});

console.log("highAccuracyRuns:", highAccuracyRuns);

// 5. 不推荐：filter(Boolean) 会过滤掉 0
const rawAccuracies = runs.map((run) => {
  return run.metrics.accuracy;
});

const wrongValidAccuracies = rawAccuracies.filter(Boolean);

console.log("rawAccuracies:", rawAccuracies);
console.log("wrongValidAccuracies:", wrongValidAccuracies);

// 6. 推荐：类型保护过滤 undefined，保留 0
const validAccuracies = rawAccuracies.filter(isDefined);

console.log("validAccuracies:", validAccuracies);

// 7. filter + map：只取 finished runs 的有效 accuracy
const finishedAccuracies = runs
  .filter((run) => {
    return run.status === "finished";
  })
  .map((run) => {
    return run.metrics.accuracy;
  })
  .filter(isDefined);

console.log("finishedAccuracies:", finishedAccuracies);

// 8. filter 不修改原数组
console.log("original runs length:", runs.length);
console.log("finishedRuns length:", finishedRuns.length);

运行：

pnpm demo:array-filter

重点观察：

finishedRuns 只保留 finished。
exp001Runs 只保留 experimentId 为 exp_001 的 run。
runsWithAccuracy 会保留 accuracy 为 0 的 run。
filter(Boolean) 会错误删除 0。
filter(isDefined) 会保留 0，只删除 undefined。
filter 不会修改原数组。

