写入代码：

// src/array-find-some-every-demo.ts

type RunStatus = "queued" | "running" | "finished" | "failed";

type ExperimentRun = {
  readonly id: string;
  readonly experimentId: string;
  status: RunStatus;
  metrics: Record<string, number>;
  startedAt: string;
  finishedAt?: string;
  failedReason?: string;
};

function isTerminalStatus(status: RunStatus): boolean {
  return status === "finished" || status === "failed";
}

function getRunById(
  runs: ExperimentRun[],
  runId: string,
): ExperimentRun | null {
  const run = runs.find((item) => {
    return item.id === runId;
  });

  return run ?? null;
}

function getRunIndexById(
  runs: ExperimentRun[],
  runId: string,
): number {
  return runs.findIndex((run) => {
    return run.id === runId;
  });
}

function hasFailedRun(runs: ExperimentRun[]): boolean {
  return runs.some((run) => {
    return run.status === "failed";
  });
}

function hasRunningRun(runs: ExperimentRun[]): boolean {
  return runs.some((run) => {
    return run.status === "running";
  });
}

function areAllRunsTerminal(
  runs: ExperimentRun[],
): boolean {
  if (runs.length === 0) {
    return false;
  }

  return runs.every((run) => {
    return isTerminalStatus(run.status);
  });
}

function doAllRunsHaveMetric(
  runs: ExperimentRun[],
  metricName: string,
): boolean {
  if (runs.length === 0) {
    return false;
  }

  return runs.every((run) => {
    return run.metrics[metricName] !== undefined;
  });
}

function hasAnyRunWithMetric(
  runs: ExperimentRun[],
  metricName: string,
): boolean {
  return runs.some((run) => {
    return run.metrics[metricName] !== undefined;
  });
}

function replaceRun(
  runs: ExperimentRun[],
  updatedRun: ExperimentRun,
): ExperimentRun[] {
  const index = runs.findIndex((run) => {
    return run.id === updatedRun.id;
  });

  if (index === -1) {
    return runs;
  }

  const nextRuns = [...runs];

  nextRuns[index] = updatedRun;

  return nextRuns;
}

const runs: ExperimentRun[] = [
  {
    id: "run_001",
    experimentId: "exp_001",
    status: "finished",
    metrics: {
      accuracy: 0.912345,
      loss: 0.23,
    },
    startedAt: "2026-06-25T10:00:00.000Z",
    finishedAt: "2026-06-25T10:30:00.000Z",
  },
  {
    id: "run_002",
    experimentId: "exp_001",
    status: "failed",
    metrics: {
      accuracy: 0.7,
      loss: 0.9,
    },
    startedAt: "2026-06-25T11:00:00.000Z",
    failedReason: "out of memory",
  },
  {
    id: "run_003",
    experimentId: "exp_002",
    status: "running",
    metrics: {
      loss: 0.4,
    },
    startedAt: "2026-06-25T12:00:00.000Z",
  },
];

// 1. find：根据 id 找 run
const run001 = getRunById(runs, "run_001");
const run999 = getRunById(runs, "run_999");

console.log("run001:", run001);
console.log("run999:", run999);

// 2. findIndex：根据 id 找下标
const run002Index = getRunIndexById(runs, "run_002");
const run999Index = getRunIndexById(runs, "run_999");

console.log("run002Index:", run002Index);
console.log("run999Index:", run999Index);

// 3. some：判断是否存在 failed / running
console.log("hasFailedRun:", hasFailedRun(runs));
console.log("hasRunningRun:", hasRunningRun(runs));

// 4. every：判断是否全部终态
console.log("areAllRunsTerminal:", areAllRunsTerminal(runs));

// 5. every：判断所有 run 是否都有 accuracy
console.log("doAllRunsHaveAccuracy:", doAllRunsHaveMetric(runs, "accuracy"));

// 6. some：判断是否至少有一个 run 有 accuracy
console.log("hasAnyAccuracy:", hasAnyRunWithMetric(runs, "accuracy"));

// 7. findIndex + 不可变替换
const updatedRun003: ExperimentRun = {
  ...runs[2]!,
  status: "finished",
  finishedAt: "2026-06-25T12:30:00.000Z",
};

const nextRuns = replaceRun(runs, updatedRun003);

console.log("original runs:", runs);
console.log("nextRuns:", nextRuns);

// 8. every 空数组特殊规则
