写入代码：

// src/array-reduce-demo.ts

type RunStatus = "queued" | "running" | "finished" | "failed";

type ExperimentRun = {
  readonly id: string;
  readonly experimentId: string;
  status: RunStatus;
  metrics: Record<string, number>;
  startedAt: string;
  finishedAt?: string;
  failedReason?: string;
};

type RunStatusCount = Record<RunStatus, number>;

type MetricSummary = {
  sum: number;
  count: number;
};

type RunsByStatus = Record<RunStatus, ExperimentRun[]>;

type RunDashboardSummary = {
  totalRuns: number;
  statusCount: RunStatusCount;
  metricNames: string[];
  averageAccuracy: number | null;
};

const runs: ExperimentRun[] = [
  {
    id: "run_001",
    experimentId: "exp_001",
    status: "finished",
    metrics: {
      accuracy: 0.912345,
      loss: 0.23,
    },
    startedAt: "2026-06-25T10:00:00.000Z",
    finishedAt: "2026-06-25T10:30:00.000Z",
  },
  {
    id: "run_002",
    experimentId: "exp_001",
    status: "failed",
    metrics: {
      accuracy: 0.7,
      loss: 0.9,
    },
    startedAt: "2026-06-25T11:00:00.000Z",
    failedReason: "out of memory",
  },
  {
    id: "run_003",
    experimentId: "exp_002",
    status: "running",
    metrics: {
      loss: 0.4,
    },
    startedAt: "2026-06-25T12:00:00.000Z",
  },
  {
    id: "run_004",
    experimentId: "exp_002",
    status: "queued",
    metrics: {
      accuracy: 0,
      loss: 0.5,
      f1: 0.61,
    },
    startedAt: "2026-06-25T13:00:00.000Z",
  },
];

function countRunsByStatus(
  runs: ExperimentRun[],
): RunStatusCount {
  return runs.reduce<RunStatusCount>(
    (result, run) => {
      result[run.status] += 1;

      return result;
    },
    {
      queued: 0,
      running: 0,
      finished: 0,
      failed: 0,
    },
  );
}

function getAverageMetric(
  runs: ExperimentRun[],
  metricName: string,
): number | null {
  const summary = runs.reduce<MetricSummary>(
    (result, run) => {
      const value = run.metrics[metricName];

      if (value !== undefined) {
        result.sum += value;
        result.count += 1;
      }

      return result;
    },
    {
      sum: 0,
      count: 0,
    },
  );

  if (summary.count === 0) {
    return null;
  }

  return summary.sum / summary.count;
}

function createRunIndexById(
  runs: ExperimentRun[],
): Record<string, ExperimentRun> {
  return runs.reduce<Record<string, ExperimentRun>>(
    (index, run) => {
      index[run.id] = run;

      return index;
    },
    {},
  );
}

function groupRunsByExperimentId(
  runs: ExperimentRun[],
): Record<string, ExperimentRun[]> {
  return runs.reduce<Record<string, ExperimentRun[]>>(
    (groups, run) => {
      const group = groups[run.experimentId];

      if (group === undefined) {
        groups[run.experimentId] = [run];
      } else {
        group.push(run);
      }

      return groups;
    },
    {},
  );
}

function groupRunsByStatus(
  runs: ExperimentRun[],
): RunsByStatus {
  return runs.reduce<RunsByStatus>(
    (groups, run) => {
      groups[run.status].push(run);

      return groups;
    },
    {
      queued: [],
      running: [],
      finished: [],
      failed: [],
    },
  );
}

function getAllMetricNames(runs: ExperimentRun[]): string[] {
  const metricNameSet = runs.reduce<Set<string>>(
    (names, run) => {
      for (const metricName of Object.keys(run.metrics)) {
        names.add(metricName);
      }

      return names;
    },
    new Set<string>(),
  );

  return [...metricNameSet];
}

function createRunDashboardSummary(
  runs: ExperimentRun[],
): RunDashboardSummary {
  return {
    totalRuns: runs.length,
    statusCount: countRunsByStatus(runs),
    metricNames: getAllMetricNames(runs),
    averageAccuracy: getAverageMetric(runs, "accuracy"),
  };
}

