console.log(finishedCount);

练习 3：统计各状态数量

type RunStatusCount = Record<RunStatus, number>;

function countRunsByStatus(
  runs: ExperimentRun[],
): RunStatusCount {
  return runs.reduce<RunStatusCount>(
    (result, run) => {
      result[run.status] += 1;

      return result;
    },
    {
      queued: 0,
      running: 0,
      finished: 0,
      failed: 0,
    },
  );
}

练习 4：计算平均 accuracy

type MetricSummary = {
  sum: number;
  count: number;
};

function getAverageMetric(
  runs: ExperimentRun[],
  metricName: string,
): number | null {
  const summary = runs.reduce<MetricSummary>(
    (result, run) => {
      const value = run.metrics[metricName];

      if (value !== undefined) {
        result.sum += value;
        result.count += 1;
      }

      return result;
    },
    {
      sum: 0,
      count: 0,
    },
  );

  if (summary.count === 0) {
    return null;
  }

  return summary.sum / summary.count;
}

练习 5：创建 runId 索引

function createRunIndexById(
  runs: ExperimentRun[],
): Record<string, ExperimentRun> {
  return runs.reduce<Record<string, ExperimentRun>>(
    (index, run) => {
      index[run.id] = run;

      return index;
    },
    {},
  );
}

练习 6：按 experimentId 分组

function groupRunsByExperimentId(
  runs: ExperimentRun[],
): Record<string, ExperimentRun[]> {
  return runs.reduce<Record<string, ExperimentRun[]>>(
    (groups, run) => {
      const group = groups[run.experimentId];

      if (group === undefined) {
        groups[run.experimentId] = [run];
      } else {
        group.push(run);
      }

      return groups;
    },
    {},
  );
}

练习 7：收集所有 metric names

function getAllMetricNames(runs: ExperimentRun[]): string[] {
  const names = runs.reduce<Set<string>>(
    (result, run) => {
      for (const metricName of Object.keys(run.metrics)) {
        result.add(metricName);
      }

      return result;
    },
    new Set<string>(),
  );

  return [...names];
}

22. 本小点总结

本节必须记住：

reduce 用来把数组聚合成一个最终结果。

核心规律：

map：T[] → U[]
filter：T[] → T[]
find：T[] → T | undefined
some/every：T[] → boolean
reduce：T[] → 任意结果 U

reduce 四要素：

accumulator：当前累积结果
item：当前元素
callback return：下一轮 accumulator
initialValue：初始 accumulator

工程口诀：

求和 → reduce
计数 → reduce
统计状态 → reduce
数组转对象 → reduce
数组分组 → reduce
收集唯一值 → reduce + Set
复杂 dashboard → 多个小 reduce 工具函数组合

转换数组 → 优先 map
筛选数组 → 优先 filter
查找一个 → 优先 find
判断存在 → 优先 some
判断全部 → 优先 every

LabPilot 推荐写法：

function countRunsByStatus(
  runs: ExperimentRun[],
): Record<RunStatus, number> {
  return runs.reduce<Record<RunStatus, number>>(
    (result, run) => {
      result[run.status] += 1;

      return result;
    },
    {
      queued: 0,
      running: 0,
      finished: 0,
      failed: 0,
    },
  );
}

function getAverageMetric(
  runs: ExperimentRun[],
  metricName: string,
): number | null {
  const summary = runs.reduce(
    (result, run) => {
      const value = run.metrics[metricName];

      if (value !== undefined) {
        result.sum += value;
        result.count += 1;
      }

      return result;
    },
    {
      sum: 0,
      count: 0,
    },
  );

  if (summary.count === 0) {
    return null;
  }

  return summary.sum / summary.count;
}

