写入代码：

// src/array-sort-demo.ts

type RunStatus = "queued" | "running" | "finished" | "failed";

type ExperimentRun = {
  readonly id: string;
  readonly experimentId: string;
  status: RunStatus;
  metrics: Record<string, number>;
  startedAt: string;
  finishedAt?: string;
  failedReason?: string;
};

type SortDirection = "asc" | "desc";

const runs: ExperimentRun[] = [
  {
    id: "run_001",
    experimentId: "exp_001",
    status: "finished",
    metrics: {
      accuracy: 0.912345,
      loss: 0.23,
    },
    startedAt: "2026-06-25T10:00:00.000Z",
    finishedAt: "2026-06-25T10:30:00.000Z",
  },
  {
    id: "run_002",
    experimentId: "exp_001",
    status: "failed",
    metrics: {
      accuracy: 0.7,
      loss: 0.9,
    },
    startedAt: "2026-06-25T11:00:00.000Z",
    failedReason: "out of memory",
  },
  {
    id: "run_003",
    experimentId: "exp_002",
    status: "running",
    metrics: {
      loss: 0.4,
    },
    startedAt: "2026-06-25T12:00:00.000Z",
  },
  {
    id: "run_004",
    experimentId: "exp_002",
    status: "queued",
    metrics: {
      accuracy: 0,
      loss: 0.5,
      f1: 0.61,
    },
    startedAt: "2026-06-25T13:00:00.000Z",
  },
];

function sortRunsByMetric(
  runs: ExperimentRun[],
  metricName: string,
  direction: SortDirection,
): ExperimentRun[] {
  return [...runs].sort((a, b) => {
    const missingValue =
      direction === "asc"
        ? Number.POSITIVE_INFINITY
        : Number.NEGATIVE_INFINITY;

    const aValue = a.metrics[metricName] ?? missingValue;
    const bValue = b.metrics[metricName] ?? missingValue;

    if (direction === "asc") {
      return aValue - bValue;
    }

    return bValue - aValue;
  });
}

function sortRunsByStartedAtDesc(
  runs: ExperimentRun[],
): ExperimentRun[] {
  return [...runs].sort((a, b) => {
    return new Date(b.startedAt).getTime() - new Date(a.startedAt).getTime();
  });
}

function sortRunsByIdAsc(
  runs: ExperimentRun[],
): ExperimentRun[] {
  return [...runs].sort((a, b) => {
    return a.id.localeCompare(b.id);
  });
}

function getTopRunsByMetric(
  runs: ExperimentRun[],
  metricName: string,
  limit: number,
): ExperimentRun[] {
  return runs
    .filter((run) => {
      return run.metrics[metricName] !== undefined;
    })
    .sort((a, b) => {
      const aValue = a.metrics[metricName];
      const bValue = b.metrics[metricName];

      if (aValue === undefined || bValue === undefined) {
        return 0;
      }

      return bValue - aValue;
    })
    .slice(0, limit);
}

const values = [1, 2, 10, 20];

console.log("default sort:", [...values].sort());
console.log("number asc:", [...values].sort((a, b) => a - b));
console.log("number desc:", [...values].sort((a, b) => b - a));

console.log(
  "accuracy desc:",
  sortRunsByMetric(runs, "accuracy", "desc").map((run) => ({
    id: run.id,
    accuracy: run.metrics.accuracy ?? null,
  })),
);

console.log(
  "loss asc:",
  sortRunsByMetric(runs, "loss", "asc").map((run) => ({
    id: run.id,
    loss: run.metrics.loss ?? null,
  })),
);

console.log(
  "startedAt desc:",
  sortRunsByStartedAtDesc(runs).map((run) => ({
    id: run.id,
    startedAt: run.startedAt,
  })),
);

console.log(
  "id asc:",
  sortRunsByIdAsc(runs).map((run) => run.id),
);

console.log(
  "top 2 accuracy:",
  getTopRunsByMetric(runs, "accuracy", 2).map((run) => ({
    id: run.id,
    accuracy: run.metrics.accuracy ?? null,
  })),
);

// 演示 sort 会修改原数组
const copiedRuns = [...runs];

copiedRuns.sort((a, b) => {
  return a.id.localeCompare(b.id);
});

console.log("original runs:", runs.map((run) => run.id));
console.log("copiedRuns sorted:", copiedRuns.map((run) => run.id));

运行：

pnpm demo:array-sort

重点观察：

默认 sort 对数字不是按数值大小排序。
数字排序要写 compare function。
sort 会修改被调用的数组。
