const sortedByAccuracy = [...runs].sort((a, b) => {
  const aAccuracy = a.metrics.accuracy ?? Number.NEGATIVE_INFINITY;
  const bAccuracy = b.metrics.accuracy ?? Number.NEGATIVE_INFINITY;

