练习 4：封装动态 metric 排序

type SortDirection = "asc" | "desc";

function sortRunsByMetric(
  runs: ExperimentRun[],
  metricName: string,
  direction: SortDirection,
): ExperimentRun[] {
  return [...runs].sort((a, b) => {
    const missingValue =
      direction === "asc"
        ? Number.POSITIVE_INFINITY
        : Number.NEGATIVE_INFINITY;

    const aValue = a.metrics[metricName] ?? missingValue;
    const bValue = b.metrics[metricName] ?? missingValue;

    if (direction === "asc") {
      return aValue - bValue;
    }

    return bValue - aValue;
  });
}

练习 5：按 startedAt 新到旧排序

function sortRunsByStartedAtDesc(
  runs: ExperimentRun[],
): ExperimentRun[] {
  return [...runs].sort((a, b) => {
    return new Date(b.startedAt).getTime() - new Date(a.startedAt).getTime();
  });
}

练习 6：取 Top 3

function getTopRunsByMetric(
  runs: ExperimentRun[],
  metricName: string,
  limit: number,
): ExperimentRun[] {
  return runs
    .filter((run) => {
      return run.metrics[metricName] !== undefined;
    })
    .sort((a, b) => {
      const aValue = a.metrics[metricName];
      const bValue = b.metrics[metricName];

      if (aValue === undefined || bValue === undefined) {
        return 0;
      }

      return bValue - aValue;
    })
    .slice(0, limit);
}

