写入代码：

// src/object-api-demo.ts

type RunStatus = "queued" | "running" | "finished" | "failed";

type ExperimentRun = {
  readonly id: string;
  readonly experimentId: string;
  status: RunStatus;
  metrics: Record<string, number>;
  startedAt: string;
  finishedAt?: string;
  failedReason?: string;
  metadata?: Record<string, unknown>;
};

type MetricRow = {
  runId: string;
  experimentId: string;
  metricName: string;
  value: number;
};

type MetadataRow = {
  key: string;
  value: string;
};

const runs: ExperimentRun[] = [
  {
    id: "run_001",
    experimentId: "exp_001",
    status: "finished",
    metrics: {
      accuracy: 0.912345,
      loss: 0.23,
      f1: 0.88,
    },
    startedAt: "2026-06-25T10:00:00.000Z",
    finishedAt: "2026-06-25T10:30:00.000Z",
    metadata: {
      device: "cuda:0",
      seed: 42,
      useAmp: true,
    },
  },
  {
    id: "run_002",
    experimentId: "exp_001",
    status: "failed",
    metrics: {
      accuracy: 0.7,
      loss: 0.9,
    },
    startedAt: "2026-06-25T11:00:00.000Z",
    failedReason: "out of memory",
  },
  {
    id: "run_003",
    experimentId: "exp_002",
    status: "running",
    metrics: {
      loss: 0.4,
    },
    startedAt: "2026-06-25T12:00:00.000Z",
  },
  {
    id: "run_004",
    experimentId: "exp_002",
    status: "queued",
    metrics: {
      accuracy: 0,
      loss: 0.5,
      precision: 0.61,
    },
    startedAt: "2026-06-25T13:00:00.000Z",
  },
];

function getMetricNames(metrics: Record<string, number>): string[] {
  return Object.keys(metrics);
}

function getMetricValues(metrics: Record<string, number>): number[] {
  return Object.values(metrics);
}

function getMetricEntries(
  metrics: Record<string, number>,
): Array<[string, number]> {
  return Object.entries(metrics);
}

function countMetrics(metrics: Record<string, number>): number {
  return Object.keys(metrics).length;
}

function hasMetric(
  metrics: Record<string, number>,
  metricName: string,
): boolean {
  return metrics[metricName] !== undefined;
}

function createMetricRowsFromRun(run: ExperimentRun): MetricRow[] {
  return Object.entries(run.metrics).map(([metricName, value]) => {
    return {
      runId: run.id,
      experimentId: run.experimentId,
      metricName,
      value,
    };
  });
}

function createMetricRows(runs: ExperimentRun[]): MetricRow[] {
  return runs.flatMap((run) => {
    return createMetricRowsFromRun(run);
  });
}

function getUniqueMetricNames(runs: ExperimentRun[]): string[] {
  const metricNames = runs.flatMap((run) => {
    return Object.keys(run.metrics);
  });

  return [...new Set(metricNames)].sort((a, b) => {
    return a.localeCompare(b);
  });
}

function sortMetricsByValueDesc(
  metrics: Record<string, number>,
): Array<[string, number]> {
  return Object.entries(metrics).sort(([, aValue], [, bValue]) => {
    return bValue - aValue;
  });
}

function pickMetricsAtLeast(
  metrics: Record<string, number>,
  minValue: number,
): Record<string, number> {
  return Object.fromEntries(
    Object.entries(metrics).filter(([, value]) => {
      return value >= minValue;
    }),
  );
}

function formatMetrics(
  metrics: Record<string, number>,
  digits = 4,
): Record<string, string> {
  return Object.fromEntries(
    Object.entries(metrics).map(([metricName, value]) => {
      return [metricName, value.toFixed(digits)];
    }),
  );
}

function formatMetadataValue(value: unknown): string {
  if (typeof value === "string") {
    return value;
  }

  if (typeof value === "number") {
    return String(value);
  }

  if (typeof value === "boolean") {
    return value ? "true" : "false";
  }

  if (value === null) {
    return "null";
  }

  if (value === undefined) {
    return "undefined";
  }

  return JSON.stringify(value);
}

function createMetadataRows(
  metadata: Record<string, unknown>,
): MetadataRow[] {
  return Object.entries(metadata).map(([key, value]) => {
    return {
      key,
      value: formatMetadataValue(value),
    };
  });
}

const firstRun = runs[0];

if (firstRun !== undefined) {
  console.log("metric names:", getMetricNames(firstRun.metrics));
  console.log("metric values:", getMetricValues(firstRun.metrics));
  console.log("metric entries:", getMetricEntries(firstRun.metrics));
  console.log("metric count:", countMetrics(firstRun.metrics));
  console.log("has accuracy:", hasMetric(firstRun.metrics, "accuracy"));
  console.log("has recall:", hasMetric(firstRun.metrics, "recall"));

  console.log("metric rows from first run:", createMetricRowsFromRun(firstRun));

  console.log("sorted metrics:", sortMetricsByValueDesc(firstRun.metrics));

  console.log("metrics >= 0.8:", pickMetricsAtLeast(firstRun.metrics, 0.8));

  console.log("formatted metrics:", formatMetrics(firstRun.metrics, 4));

  if (firstRun.metadata !== undefined) {
    console.log("metadata rows:", createMetadataRows(firstRun.metadata));
  }
}

console.log("all metric rows:", createMetricRows(runs));

console.log("unique metric names:", getUniqueMetricNames(runs));

运行：

pnpm demo:object-api

重点观察：

Object.keys(metrics) 得到 metricName 列表。
Object.values(metrics) 得到 metric 数值列表。
Object.entries(metrics) 得到 [metricName, value] 列表。
entries + map 可以生成 MetricRow[]。
entries + filter + fromEntries 可以过滤对象字段。
entries + sort 可以按 value 排序。
Record<string, unknown> 的 value 必须先做类型判断。
accuracy 为 0 时 hasMetric 仍然应该返回 true。

