console.log("objectSet size:", objectSet.size);

运行：

pnpm demo:set-map

重点观察：

Set 可以去重 metric names。
Set.has 可以判断 runId 是否存在。
Map.get 找不到会返回 undefined。
Map.keys / values / entries 可以转成数组。
Set 对对象是按引用去重，不是按内容去重。

14. AI / 深度学习 / 论文复现 / LabPilot 场景示例

14.1 生成 metric 下拉选项

function createMetricOptions(runs: ExperimentRun[]): string[] {
  return [
    ...new Set(
      runs.flatMap((run) => Object.keys(run.metrics)),
    ),
  ].sort((a, b) => a.localeCompare(b));
}

用于：

图表选择指标
表格动态列
Agent 工具参数候选

14.2 Agent 工具参数校验

type CompareRunsArgs = {
  runIds: string[];
  metricName: string;
};

function validateCompareRunsArgs(
  runs: ExperimentRun[],
  args: CompareRunsArgs,
): {
  ok: true;
} | {
  ok: false;
  error: string;
} {
  const runIdSet = createRunIdSet(runs);

  const missingRunIds = args.runIds.filter((runId) => {
    return !runIdSet.has(runId);
  });

  if (missingRunIds.length > 0) {
    return {
      ok: false,
      error: `Missing runIds: ${missingRunIds.join(", ")}`,
    };
  }

  const metricNames = new Set(createMetricOptions(runs));

  if (!metricNames.has(args.metricName)) {
    return {
      ok: false,
      error: `Unknown metric: ${args.metricName}`,
    };
  }

  return {
    ok: true,
  };
}

这里组合了：

Set：校验 runId 和 metricName 是否存在
filter：找出缺失 runIds

14.3 快速查找选中的 runs

function getSelectedRuns(
  runs: ExperimentRun[],
  selectedRunIds: string[],
): ExperimentRun[] {
  const runMap = createRunMapById(runs);

  return selectedRunIds.flatMap((runId) => {
    const run = runMap.get(runId);

    if (run === undefined) {
      return [];
    }

    return [run];
  });
}

