10.2 分组后找每组 best run

function getBestRunByMetric(
  runs: ExperimentRun[],
  metricName: string,
): ExperimentRun | null {
  return runs.reduce<ExperimentRun | null>((bestRun, run) => {
    const value = run.metrics[metricName];

    if (value === undefined) {
      return bestRun;
    }

    if (bestRun === null) {
      return run;
    }

    const bestValue = bestRun.metrics[metricName];

    if (bestValue === undefined) {
      return run;
    }

    return value > bestValue ? run : bestRun;
  }, null);
}

function getBestRunByExperimentId(
  runs: ExperimentRun[],
  metricName: string,
): Record<string, ExperimentRun | null> {
  const groups = groupRunsByExperimentId(runs);

  return Object.fromEntries(
    Object.entries(groups).map(([experimentId, experimentRuns]) => {
      return [experimentId, getBestRunByMetric(experimentRuns, metricName)];
    }),
  );
}

用途：

每个 experiment 下找 accuracy 最好的 run
每个实验配置选一个 best checkpoint
生成论文复现结果对比

10.3 分组后生成 Dashboard section

type ExperimentRunGroupSummary = {
  experimentId: string;
  totalRuns: number;
  finishedRuns: number;
  failedRuns: number;
  bestAccuracyRunId: string | null;
};

function createExperimentRunGroupSummaries(
  runs: ExperimentRun[],
): ExperimentRunGroupSummary[] {
  const groups = groupRunsByExperimentId(runs);

  return Object.entries(groups).map(([experimentId, experimentRuns]) => {
    const bestRun = getBestRunByMetric(experimentRuns, "accuracy");

    return {
      experimentId,
      totalRuns: experimentRuns.length,
      finishedRuns: experimentRuns.filter((run) => {
        return run.status === "finished";
      }).length,
      failedRuns: experimentRuns.filter((run) => {
        return run.status === "failed";
      }).length,
      bestAccuracyRunId: bestRun?.id ?? null,
    };
  });
}

这里组合了：

groupBy
