// src/group-by-demo.ts

type RunStatus = "queued" | "running" | "finished" | "failed";

type ExperimentRun = {
  readonly id: string;
  readonly experimentId: string;
  status: RunStatus;
  metrics: Record<string, number>;
  startedAt: string;
  finishedAt?: string;
  failedReason?: string;
};

type RunsByStatus = Record<RunStatus, ExperimentRun[]>;

type MetricRow = {
  runId: string;
  experimentId: string;
  metricName: string;
  value: number;
};

type ExperimentRunGroupSummary = {
  experimentId: string;
  totalRuns: number;
  finishedRuns: number;
  failedRuns: number;
  bestAccuracyRunId: string | null;
};

const runs: ExperimentRun[] = [
  {
    id: "run_001",
    experimentId: "exp_001",
    status: "finished",
    metrics: {
      accuracy: 0.91,
      loss: 0.23,
    },
    startedAt: "2026-06-25T10:00:00.000Z",
    finishedAt: "2026-06-25T10:30:00.000Z",
  },
  {
    id: "run_002",
    experimentId: "exp_001",
    status: "failed",
    metrics: {
      accuracy: 0.7,
      loss: 0.9,
    },
    startedAt: "2026-06-25T11:00:00.000Z",
    failedReason: "out of memory",
  },
  {
    id: "run_003",
    experimentId: "exp_002",
    status: "running",
    metrics: {
      loss: 0.4,
    },
    startedAt: "2026-06-25T12:00:00.000Z",
  },
  {
    id: "run_004",
    experimentId: "exp_002",
    status: "queued",
    metrics: {
      accuracy: 0,
      loss: 0.5,
      f1: 0.61,
    },
    startedAt: "2026-06-25T13:00:00.000Z",
  },
];

function groupRunsByExperimentId(
  runs: ExperimentRun[],
): Record<string, ExperimentRun[]> {
  return runs.reduce<Record<string, ExperimentRun[]>>(
    (groups, run) => {
      const group = groups[run.experimentId];

      if (group === undefined) {
        groups[run.experimentId] = [run];
      } else {
        group.push(run);
      }

      return groups;
    },
    {},
  );
}

function groupRunsByStatus(
  runs: ExperimentRun[],
): RunsByStatus {
  return runs.reduce<RunsByStatus>(
    (groups, run) => {
      groups[run.status].push(run);

      return groups;
    },
    {
      queued: [],
      running: [],
      finished: [],
      failed: [],
    },
  );
}

function groupBy<T>(
  items: T[],
  getKey: (item: T) => string,
): Record<string, T[]> {
  return items.reduce<Record<string, T[]>>(
    (groups, item) => {
      const key = getKey(item);
      const group = groups[key];

      if (group === undefined) {
        groups[key] = [item];
      } else {
        group.push(item);
      }

      return groups;
    },
    {},
  );
}

function countGroupSizes<T>(
  groups: Record<string, T[]>,
): Record<string, number> {
  return Object.fromEntries(
    Object.entries(groups).map(([key, items]) => {
      return [key, items.length];
    }),
  );
}

function createMetricRows(runs: ExperimentRun[]): MetricRow[] {
  return runs.flatMap((run) => {
    return Object.entries(run.metrics).map(([metricName, value]) => {
      return {
        runId: run.id,
        experimentId: run.experimentId,
        metricName,
        value,
      };
    });
  });
}

function groupMetricRowsByName(
  rows: MetricRow[],
): Record<string, MetricRow[]> {
  return rows.reduce<Record<string, MetricRow[]>>(
    (groups, row) => {
      const group = groups[row.metricName];

      if (group === undefined) {
        groups[row.metricName] = [row];
      } else {
        group.push(row);
      }

      return groups;
    },
    {},
  );
}

function getBestRunByMetric(
  runs: ExperimentRun[],
  metricName: string,
): ExperimentRun | null {
  return runs.reduce<ExperimentRun | null>((bestRun, run) => {
    const value = run.metrics[metricName];

    if (value === undefined) {
      return bestRun;
    }

    if (bestRun === null) {
      return run;
    }

    const bestValue = bestRun.metrics[metricName];

    if (bestValue === undefined) {
      return run;
    }

    return value > bestValue ? run : bestRun;
  }, null);
}

function createExperimentRunGroupSummaries(
  runs: ExperimentRun[],
): ExperimentRunGroupSummary[] {
  const groups = groupRunsByExperimentId(runs);

  return Object.entries(groups).map(([experimentId, experimentRuns]) => {
    const bestRun = getBestRunByMetric(experimentRuns, "accuracy");

    return {
      experimentId,
      totalRuns: experimentRuns.length,
      finishedRuns: experimentRuns.filter((run) => {
        return run.status === "finished";
      }).length,
      failedRuns: experimentRuns.filter((run) => {
        return run.status === "failed";
      }).length,
      bestAccuracyRunId: bestRun?.id ?? null,
    };
  });
}

function groupByToMap<T>(
  items: T[],
  getKey: (item: T) => string,
): Map<string, T[]> {
  const groups = new Map<string, T[]>();

  for (const item of items) {
    const key = getKey(item);
    const group = groups.get(key);

    if (group === undefined) {
      groups.set(key, [item]);
    } else {
      group.push(item);
    }
  }

  return groups;
}

