现在把前面的函数组合起来。

function createRunDashboardData(
  runs: ExperimentRun[],
): RunDashboardData {
  return {
    totalRuns: runs.length,
    statusCount: countRunsByStatus(runs),
    hasFailedRun: hasRunWithStatus(runs, "failed"),
    hasRunningRun: hasRunWithStatus(runs, "running"),
    areAllRunsTerminal: areAllRunsTerminal(runs),
    metricNames: getUniqueMetricNames(runs),
    averageAccuracy: getAverageMetric(runs, "accuracy"),
    averageLoss: getAverageMetric(runs, "loss"),
    bestAccuracyRun: getBestRunByMetric(runs, "accuracy"),
    lowestLossRun: getLowestRunByMetric(runs, "loss"),
