  runsByExperimentId: Record<string, ExperimentRun[]>;
};

const runs: ExperimentRun[] = [
  {
    id: "run_001",
    experimentId: "exp_001",
    status: "finished",
    metrics: {
      accuracy: 0.91,
      loss: 0.23,
    },
    startedAt: "2026-06-25T10:00:00.000Z",
    finishedAt: "2026-06-25T10:30:00.000Z",
  },
  {
    id: "run_002",
    experimentId: "exp_001",
    status: "failed",
    metrics: {
      accuracy: 0.7,
      loss: 0.9,
    },
    startedAt: "2026-06-25T11:00:00.000Z",
    failedReason: "out of memory",
  },
  {
    id: "run_003",
    experimentId: "exp_002",
    status: "running",
    metrics: {
      loss: 0.4,
    },
    startedAt: "2026-06-25T12:00:00.000Z",
  },
  {
    id: "run_004",
    experimentId: "exp_002",
    status: "queued",
    metrics: {
      accuracy: 0,
      loss: 0.5,
      f1: 0.61,
    },
    startedAt: "2026-06-25T13:00:00.000Z",
  },
];

function countRunsByStatus(
  runs: ExperimentRun[],
): Record<RunStatus, number> {
  return runs.reduce<Record<RunStatus, number>>(
    (result, run) => {
      result[run.status] += 1;

      return result;
    },
    {
      queued: 0,
      running: 0,
      finished: 0,
      failed: 0,
    },
  );
}

function hasRunWithStatus(
  runs: ExperimentRun[],
  status: RunStatus,
): boolean {
  return runs.some((run) => {
    return run.status === status;
  });
}

function isTerminalStatus(status: RunStatus): boolean {
  return status === "finished" || status === "failed";
}

function areAllRunsTerminal(runs: ExperimentRun[]): boolean {
  if (runs.length === 0) {
    return false;
  }

  return runs.every((run) => {
    return isTerminalStatus(run.status);
  });
}

function getUniqueMetricNames(runs: ExperimentRun[]): string[] {
  const metricNames = runs.flatMap((run) => {
    return Object.keys(run.metrics);
  });

  return [...new Set(metricNames)].sort((a, b) => {
    return a.localeCompare(b);
  });
}

function getAverageMetric(
  runs: ExperimentRun[],
  metricName: string,
): number | null {
  const summary = runs.reduce<MetricSummary>(
    (result, run) => {
      const value = run.metrics[metricName];

      if (value !== undefined) {
        result.sum += value;
        result.count += 1;
      }

      return result;
    },
    {
      sum: 0,
      count: 0,
    },
  );

  if (summary.count === 0) {
    return null;
  }

  return summary.sum / summary.count;
}

function getBestRunByMetric(
  runs: ExperimentRun[],
  metricName: string,
): ExperimentRun | null {
  return runs.reduce<ExperimentRun | null>((bestRun, run) => {
    const value = run.metrics[metricName];

    if (value === undefined) {
      return bestRun;
    }

    if (bestRun === null) {
      return run;
    }

    const bestValue = bestRun.metrics[metricName];

    if (bestValue === undefined) {
      return run;
    }

    return value > bestValue ? run : bestRun;
  }, null);
}

function getLowestRunByMetric(
  runs: ExperimentRun[],
  metricName: string,
): ExperimentRun | null {
  return runs.reduce<ExperimentRun | null>((bestRun, run) => {
    const value = run.metrics[metricName];

    if (value === undefined) {
      return bestRun;
    }

    if (bestRun === null) {
      return run;
    }

    const bestValue = bestRun.metrics[metricName];

    if (bestValue === undefined) {
      return run;
    }

    return value < bestValue ? run : bestRun;
  }, null);
}

function createRunTableRows(runs: ExperimentRun[]): RunTableRow[] {
  return runs.map((run) => {
    return {
      id: run.id,
      experimentId: run.experimentId,
      status: run.status,
      accuracy: run.metrics.accuracy ?? null,
      loss: run.metrics.loss ?? null,
      metricCount: Object.keys(run.metrics).length,
      startedAt: run.startedAt,
      finishedAt: run.finishedAt ?? null,
      failedReason: run.failedReason ?? null,
    };
  });
}

function createMetricChartData(
  runs: ExperimentRun[],
  metricName: string,
): MetricChartPoint[] {
  return runs.map((run) => {
    return {
      runId: run.id,
      experimentId: run.experimentId,
      value: run.metrics[metricName] ?? null,
    };
  });
}

function groupRunsByStatus(
  runs: ExperimentRun[],
): Record<RunStatus, ExperimentRun[]> {
  return runs.reduce<Record<RunStatus, ExperimentRun[]>>(
    (groups, run) => {
      groups[run.status].push(run);

      return groups;
    },
    {
      queued: [],
      running: [],
      finished: [],
      failed: [],
    },
  );
}

function groupRunsByExperimentId(
  runs: ExperimentRun[],
): Record<string, ExperimentRun[]> {
  return runs.reduce<Record<string, ExperimentRun[]>>(
    (groups, run) => {
      const group = groups[run.experimentId];

      if (group === undefined) {
        groups[run.experimentId] = [run];
      } else {
        group.push(run);
      }

      return groups;
    },
    {},
  );
}

function createRunDashboardData(
  runs: ExperimentRun[],
): RunDashboardData {
  return {
    totalRuns: runs.length,
    statusCount: countRunsByStatus(runs),
    hasFailedRun: hasRunWithStatus(runs, "failed"),
    hasRunningRun: hasRunWithStatus(runs, "running"),
    areAllRunsTerminal: areAllRunsTerminal(runs),
    metricNames: getUniqueMetricNames(runs),
    averageAccuracy: getAverageMetric(runs, "accuracy"),
    averageLoss: getAverageMetric(runs, "loss"),
    bestAccuracyRun: getBestRunByMetric(runs, "accuracy"),
    lowestLossRun: getLowestRunByMetric(runs, "loss"),
    tableRows: createRunTableRows(runs),
    accuracyChartData: createMetricChartData(runs, "accuracy"),
    lossChartData: createMetricChartData(runs, "loss"),
    runsByStatus: groupRunsByStatus(runs),
    runsByExperimentId: groupRunsByExperimentId(runs),
  };
}

