4. 第一步：定义核心实体类型

文件：

src/entities/run.ts

建议内容：

// src/entities/run.ts

export type RunStatus = "queued" | "running" | "finished" | "failed";

export type MetricMap = Record<string, number>;

export type ExperimentRun = {
  readonly id: string;
  readonly experimentId: string;
  status: RunStatus;
  metrics: MetricMap;
  startedAt: string;
  finishedAt?: string;
  failedReason?: string;
};

export type RunTableRow = {
  id: string;
  experimentId: string;
  status: RunStatus;
  accuracy: number | null;
  loss: number | null;
  metricCount: number;
  startedAt: string;
  finishedAt: string | null;
  failedReason: string | null;
};

export type MetricChartPoint = {
  runId: string;
  experimentId: string;
  value: number | null;
};

export type MetricRow = {
  runId: string;
  experimentId: string;
  metricName: string;
  value: number;
};

export type RunStatusCount = Record<RunStatus, number>;

export type RunsByStatus = Record<RunStatus, ExperimentRun[]>;

export type RunDashboardData = {
  totalRuns: number;
  statusCount: RunStatusCount;
  hasFailedRun: boolean;
  hasRunningRun: boolean;
  areAllRunsTerminal: boolean;
  metricNames: string[];
  averageAccuracy: number | null;
  averageLoss: number | null;
  bestAccuracyRun: ExperimentRun | null;
  lowestLossRun: ExperimentRun | null;
  tableRows: RunTableRow[];
  accuracyChartData: MetricChartPoint[];
  lossChartData: MetricChartPoint[];
  metricRows: MetricRow[];
  runsByStatus: RunsByStatus;
  runsByExperimentId: Record<string, ExperimentRun[]>;
};

这里要注意几个设计点：

MetricMap 用 Record<string, number> 表示动态指标。
RunStatus 是固定 union。
RunStatusCount 用 Record<RunStatus, number>。
RunsByStatus 用 Record<RunStatus, ExperimentRun[]>。
展示层缺失值用 null。
动态读取缺失值仍然是 undefined。

5. 第二步：实现 metric-utils.ts

文件：

src/utils/metric-utils.ts

负责处理单个 MetricMap 或多个 runs 的 metric 相关逻辑。

// src/utils/metric-utils.ts

import type {
  ExperimentRun,
  MetricMap,
  MetricRow,
} from "../entities/run.js";

export function getMetricNames(metrics: MetricMap): string[] {
  return Object.keys(metrics);
}

export function getMetricValues(metrics: MetricMap): number[] {
  return Object.values(metrics);
}

export function countMetrics(metrics: MetricMap): number {
  return Object.keys(metrics).length;
}

export function hasMetric(
  metrics: MetricMap,
  metricName: string,
): boolean {
  return metrics[metricName] !== undefined;
}

export function getUniqueMetricNames(
  runs: ExperimentRun[],
): string[] {
  const metricNames = runs.flatMap((run) => {
    return Object.keys(run.metrics);
  });

  return [...new Set(metricNames)].sort((a, b) => {
    return a.localeCompare(b);
  });
}

export function createMetricRowsFromRun(
  run: ExperimentRun,
): MetricRow[] {
  return Object.entries(run.metrics).map(([metricName, value]) => {
    return {
      runId: run.id,
      experimentId: run.experimentId,
      metricName,
      value,
    };
  });
}

export function createMetricRows(
  runs: ExperimentRun[],
): MetricRow[] {
  return runs.flatMap((run) => {
    return createMetricRowsFromRun(run);
  });
}

export function formatMetrics(
  metrics: MetricMap,
  digits = 4,
): Record<string, string> {
  return Object.fromEntries(
    Object.entries(metrics).map(([metricName, value]) => {
      return [metricName, value.toFixed(digits)];
    }),
  );
}

export function pickMetrics(
  metrics: MetricMap,
  metricNames: string[],
): MetricMap {
  const metricNameSet = new Set(metricNames);

  return Object.fromEntries(
    Object.entries(metrics).filter(([metricName]) => {
      return metricNameSet.has(metricName);
    }),
  );
}

export function omitMetrics(
  metrics: MetricMap,
  metricNamesToOmit: string[],
): MetricMap {
  const omitSet = new Set(metricNamesToOmit);

  return Object.fromEntries(
    Object.entries(metrics).filter(([metricName]) => {
      return !omitSet.has(metricName);
    }),
  );
}

这一组函数主要练习：

Object.keys
Object.values
Object.entries
Object.fromEntries
flatMap
Set
map
filter

关键坑：

判断 metric 是否存在时，不要用 Boolean(metrics[name])。
因为 0 是合法 metric 值。

6. 第三步：实现 run-query-utils.ts

文件：

src/utils/run-query-utils.ts

负责查询、判断、筛选。

// src/utils/run-query-utils.ts

import type {
  ExperimentRun,
  RunStatus,
} from "../entities/run.js";

export function getRunById(
  runs: ExperimentRun[],
  runId: string,
): ExperimentRun | null {
  return runs.find((run) => {
    return run.id === runId;
  }) ?? null;
}

export function getRunsByStatus(
  runs: ExperimentRun[],
  status: RunStatus,
): ExperimentRun[] {
  return runs.filter((run) => {
    return run.status === status;
  });
}

export function getRunsByExperimentId(
  runs: ExperimentRun[],
  experimentId: string,
): ExperimentRun[] {
  return runs.filter((run) => {
    return run.experimentId === experimentId;
  });
}

export function hasRunWithStatus(
  runs: ExperimentRun[],
  status: RunStatus,
): boolean {
  return runs.some((run) => {
    return run.status === status;
  });
}

export function hasFailedRun(runs: ExperimentRun[]): boolean {
  return hasRunWithStatus(runs, "failed");
}

export function hasRunningRun(runs: ExperimentRun[]): boolean {
  return hasRunWithStatus(runs, "running");
}

export function isTerminalStatus(status: RunStatus): boolean {
  return status === "finished" || status === "failed";
}

export function areAllRunsTerminal(
  runs: ExperimentRun[],
): boolean {
  if (runs.length === 0) {
    return false;
  }

  return runs.every((run) => {
    return isTerminalStatus(run.status);
  });
}

export function getRunsWithMetric(
  runs: ExperimentRun[],
  metricName: string,
): ExperimentRun[] {
  return runs.filter((run) => {
    return run.metrics[metricName] !== undefined;
  });
}

export function getRunsByMetricAtLeast(
  runs: ExperimentRun[],
  metricName: string,
  minValue: number,
): ExperimentRun[] {
  return runs.filter((run) => {
    const value = run.metrics[metricName];

    return value !== undefined && value >= minValue;
  });
}

这一组函数主要练习：

find
filter
some
every
动态 metric 判断
空数组 every 处理

核心坑：

find 返回 T | undefined，所以业务函数建议转成 T | null。
every 对空数组原生返回 true，但业务上通常要先判断 length。

7. 第四步：实现 run-index-utils.ts

文件：

src/utils/run-index-utils.ts

负责 Set / Map 相关工具。

// src/utils/run-index-utils.ts

import type { ExperimentRun } from "../entities/run.js";

export function createRunIdSet(
  runs: ExperimentRun[],
): Set<string> {
  return new Set(
    runs.map((run) => {
      return run.id;
    }),
  );
}

export function createRunMapById(
  runs: ExperimentRun[],
): Map<string, ExperimentRun> {
  return new Map<string, ExperimentRun>(
    runs.map((run) => {
      return [run.id, run] as const;
    }),
  );
}

export function findMissingRunIds(
  runs: ExperimentRun[],
  runIds: string[],
): string[] {
  const runIdSet = createRunIdSet(runs);

  return runIds.filter((runId) => {
    return !runIdSet.has(runId);
  });
}

export function doAllRunIdsExist(
  runs: ExperimentRun[],
  runIds: string[],
): boolean {
  const runIdSet = createRunIdSet(runs);

  return runIds.every((runId) => {
    return runIdSet.has(runId);
  });
}

export function getRunsByIds(
  runs: ExperimentRun[],
  runIds: string[],
): ExperimentRun[] {
  const runMap = createRunMapById(runs);

  return runIds.flatMap((runId) => {
    const run = runMap.get(runId);

    if (run === undefined) {
      return [];
    }

    return [run];
  });
}

export function hasDuplicateRunId(
  runs: ExperimentRun[],
): boolean {
  const seenIds = new Set<string>();

  return runs.some((run) => {
    if (seenIds.has(run.id)) {
      return true;
    }

    seenIds.add(run.id);
    return false;
  });
}

export function findDuplicateRunIds(
  runs: ExperimentRun[],
): string[] {
  const seenIds = new Set<string>();
  const duplicateIds = new Set<string>();

  for (const run of runs) {
    if (seenIds.has(run.id)) {
      duplicateIds.add(run.id);
    } else {
      seenIds.add(run.id);
    }
  }

  return [...duplicateIds];
}

export function uniqueRunsById(
  runs: ExperimentRun[],
): ExperimentRun[] {
  const seenIds = new Set<string>();
  const result: ExperimentRun[] = [];

  for (const run of runs) {
    if (seenIds.has(run.id)) {
      continue;
    }

    seenIds.add(run.id);
    result.push(run);
  }

  return result;
}

这一组函数主要练习：

Set 去重
Set.has
Map.get
Map.has
flatMap 返回 [] / [value]
some 短路判断

核心坑：

Map.get(key) 可能是 undefined。
Set 对对象按引用去重，不能直接用 new Set(runs) 实现按 id 去重。

8. 第五步：实现 run-group-utils.ts

文件：

src/utils/run-group-utils.ts

负责分组。

// src/utils/run-group-utils.ts

import type {
  ExperimentRun,
  MetricRow,
  RunsByStatus,
} from "../entities/run.js";

export function groupBy<T>(
  items: T[],
  getKey: (item: T) => string,
): Record<string, T[]> {
  return items.reduce<Record<string, T[]>>(
    (groups, item) => {
      const key = getKey(item);
      const group = groups[key];

      if (group === undefined) {
        groups[key] = [item];
      } else {
        group.push(item);
      }

      return groups;
    },
    {},
  );
}

export function groupRunsByExperimentId(
  runs: ExperimentRun[],
): Record<string, ExperimentRun[]> {
  return groupBy(runs, (run) => {
    return run.experimentId;
  });
}

export function groupRunsByStatus(
  runs: ExperimentRun[],
): RunsByStatus {
  return runs.reduce<RunsByStatus>(
    (groups, run) => {
      groups[run.status].push(run);

      return groups;
    },
    {
      queued: [],
      running: [],
      finished: [],
      failed: [],
    },
  );
}

export function groupMetricRowsByName(
  rows: MetricRow[],
): Record<string, MetricRow[]> {
  return groupBy(rows, (row) => {
    return row.metricName;
  });
}

export function countGroupSizes<T>(
  groups: Record<string, T[]>,
): Record<string, number> {
  return Object.fromEntries(
    Object.entries(groups).map(([key, items]) => {
      return [key, items.length];
    }),
  );
}

这一组函数主要练习：

reduce
Record<string, T[]>
Record<RunStatus, T[]>
Object.entries
Object.fromEntries
通用 groupBy

核心坑：

动态 key 分组要先初始化数组。
固定 union key 分组要完整初始化。
通用 groupBy 返回 Record<string, T[]>，不如专用 groupRunsByStatus 类型严格。

