12. 第九步：实现 run-dashboard-utils.ts

文件：

src/utils/run-dashboard-utils.ts

负责组合所有底层函数。

// src/utils/run-dashboard-utils.ts

import type {
  ExperimentRun,
  RunDashboardData,
  RunStatus,
} from "../entities/run.js";

import { getUniqueMetricNames, createMetricRows } from "./metric-utils.js";
import {
  areAllRunsTerminal,
  hasRunWithStatus,
} from "./run-query-utils.js";
import {
  groupRunsByExperimentId,
  groupRunsByStatus,
} from "./run-group-utils.js";
import { createRunTableRows } from "./run-table-utils.js";
import { createMetricChartData } from "./run-chart-utils.js";

type MetricSummary = {
  sum: number;
  count: number;
};

export function countRunsByStatus(
  runs: ExperimentRun[],
): Record<RunStatus, number> {
  return runs.reduce<Record<RunStatus, number>>(
    (result, run) => {
      result[run.status] += 1;

      return result;
    },
    {
      queued: 0,
      running: 0,
      finished: 0,
      failed: 0,
    },
  );
}

export function getAverageMetric(
  runs: ExperimentRun[],
  metricName: string,
): number | null {
  const summary = runs.reduce<MetricSummary>(
    (result, run) => {
      const value = run.metrics[metricName];

      if (value !== undefined) {
        result.sum += value;
        result.count += 1;
      }

      return result;
    },
    {
      sum: 0,
      count: 0,
    },
  );

  if (summary.count === 0) {
    return null;
  }

  return summary.sum / summary.count;
}

export function getBestRunByMetric(
  runs: ExperimentRun[],
  metricName: string,
): ExperimentRun | null {
  return runs.reduce<ExperimentRun | null>((bestRun, run) => {
    const value = run.metrics[metricName];

    if (value === undefined) {
      return bestRun;
    }

    if (bestRun === null) {
      return run;
    }

    const bestValue = bestRun.metrics[metricName];

    if (bestValue === undefined) {
      return run;
    }

    return value > bestValue ? run : bestRun;
  }, null);
}

export function getLowestRunByMetric(
  runs: ExperimentRun[],
  metricName: string,
): ExperimentRun | null {
  return runs.reduce<ExperimentRun | null>((bestRun, run) => {
    const value = run.metrics[metricName];

    if (value === undefined) {
      return bestRun;
    }

    if (bestRun === null) {
      return run;
    }

    const bestValue = bestRun.metrics[metricName];

    if (bestValue === undefined) {
      return run;
    }

    return value < bestValue ? run : bestRun;
  }, null);
}

export function createRunDashboardData(
  runs: ExperimentRun[],
): RunDashboardData {
  return {
    totalRuns: runs.length,
    statusCount: countRunsByStatus(runs),
    hasFailedRun: hasRunWithStatus(runs, "failed"),
    hasRunningRun: hasRunWithStatus(runs, "running"),
    areAllRunsTerminal: areAllRunsTerminal(runs),
    metricNames: getUniqueMetricNames(runs),
    averageAccuracy: getAverageMetric(runs, "accuracy"),
    averageLoss: getAverageMetric(runs, "loss"),
    bestAccuracyRun: getBestRunByMetric(runs, "accuracy"),
    lowestLossRun: getLowestRunByMetric(runs, "loss"),
    tableRows: createRunTableRows(runs),
    accuracyChartData: createMetricChartData(runs, "accuracy"),
    lossChartData: createMetricChartData(runs, "loss"),
    metricRows: createMetricRows(runs),
    runsByStatus: groupRunsByStatus(runs),
    runsByExperimentId: groupRunsByExperimentId(runs),
  };
}

这里体现的工程原则是：

底层函数负责具体数据处理。
Dashboard 函数负责组合。

不要把所有逻辑全写进 createRunDashboardData 里。

