}

console.log("1. program start");

const runsPromise = fetchRunsByProjectId("proj_001");

console.log("3. promise created:", runsPromise);

runsPromise
  .then((runs) => {
    console.log("5. runs loaded:", runs);

    const dashboardData = createRunDashboardData(runs);

    console.log("6. dashboard data:", dashboardData);
  })
  .catch((error) => {
