写入代码：

// src/async-error-demo.ts

type RunStatus = "queued" | "running" | "finished" | "failed";

type ExperimentRun = {
  readonly id: string;
  readonly experimentId: string;
  status: RunStatus;
  metrics: Record<string, number>;
  startedAt: string;
};

type RunDashboardData = {
  totalRuns: number;
  hasFailedRun: boolean;
};

function createRunDashboardData(
  runs: ExperimentRun[],
): RunDashboardData {
  return {
    totalRuns: runs.length,
    hasFailedRun: runs.some((run) => {
      return run.status === "failed";
    }),
  };
}

function fetchRunsByProjectId(
  projectId: string,
): Promise<ExperimentRun[]> {
  return new Promise<ExperimentRun[]>((resolve, reject) => {
    console.log("fetchRunsByProjectId started:", projectId);

    setTimeout(() => {
      if (projectId.trim() === "") {
        reject(new Error("projectId is required"));

        return;
      }

      resolve([
        {
          id: "run_001",
          experimentId: projectId,
          status: "finished",
          metrics: {
            accuracy: 0.91,
          },
          startedAt: "2026-06-25T10:00:00.000Z",
        },
        {
          id: "run_002",
          experimentId: projectId,
          status: "failed",
          metrics: {
            loss: 0.9,
          },
          startedAt: "2026-06-25T11:00:00.000Z",
        },
      ]);
    }, 1000);
  });
}

function getErrorMessage(error: unknown): string {
  if (error instanceof Error) {
    return error.message;
  }

  if (typeof error === "string") {
    return error;
  }

  return "Unknown error";
}

async function loadRunDashboardData(
  projectId: string,
): Promise<RunDashboardData> {
  try {
    console.log("before await fetchRunsByProjectId");

    const runs = await fetchRunsByProjectId(projectId);

    console.log("after await fetchRunsByProjectId");

    return createRunDashboardData(runs);
  } catch (error) {
    console.error("load dashboard failed:", getErrorMessage(error));

    throw error;
  } finally {
    console.log("loadRunDashboardData finally:", projectId);
  }
}

async function loadRunDashboardDataOrNull(
  projectId: string,
): Promise<RunDashboardData | null> {
  try {
    const runs = await fetchRunsByProjectId(projectId);

    return createRunDashboardData(runs);
  } catch (error) {
    console.error("safe load failed:", getErrorMessage(error));

    return null;
  } finally {
    console.log("loadRunDashboardDataOrNull finally:", projectId);
  }
}

const fallbackDashboardData: RunDashboardData = {
  totalRuns: 0,
  hasFailedRun: false,
};

async function loadRunDashboardDataSafe(
  projectId: string,
): Promise<RunDashboardData> {
  try {
    const runs = await fetchRunsByProjectId(projectId);

    return createRunDashboardData(runs);
  } catch (error) {
    console.error("fallback load failed:", getErrorMessage(error));

    return fallbackDashboardData;
  } finally {
    console.log("loadRunDashboardDataSafe finally:", projectId);
  }
}

async function main(): Promise<void> {
  console.log("1. success case");

  try {
    const dashboardData = await loadRunDashboardData("proj_001");

    console.log("success dashboard:", dashboardData);
  } catch (error) {
    console.error("success case should not fail:", getErrorMessage(error));
  }

  console.log("2. throw to upper layer case");

  try {
    const dashboardData = await loadRunDashboardData("");

    console.log("this will not run:", dashboardData);
  } catch (error) {
    console.error("upper layer caught:", getErrorMessage(error));
  }

  console.log("3. null fallback case");

  const nullableDashboardData = await loadRunDashboardDataOrNull("");

  if (nullableDashboardData === null) {
    console.log("show empty state");
  } else {
    console.log("nullable dashboard:", nullableDashboardData);
  }

  console.log("4. fallback dashboard case");

  const safeDashboardData = await loadRunDashboardDataSafe("");

  console.log("safe dashboard:", safeDashboardData);
}

main().catch((error) => {
  console.error("main failed:", getErrorMessage(error));
});

运行：

pnpm demo:async-error

重点观察：

成功时：try 中 await 后继续执行。
失败时：await 后面的成功逻辑被跳过，进入 catch。
finally 无论成功失败都会执行。
throw error 后，上层 try/catch 能继续捕获。
返回 null 时，调用方要判断 null。
返回 fallback 时，调用方能继续渲染默认数据。

17. async 函数最外层调用也要处理错误

错误示例：

async function main(): Promise<void> {
  const dashboardData = await loadRunDashboardData("");

  console.log(dashboardData);
}

main();

如果 main() 内部失败，它返回 rejected Promise。

但你没有处理这个 Promise。

推荐：

main().catch((error) => {
  console.error("main failed:", getErrorMessage(error));
});

或者在 main 内部包 try/catch：

async function main(): Promise<void> {
  try {
    const dashboardData = await loadRunDashboardData("");

    console.log(dashboardData);
  } catch (error) {
    console.error("main failed:", getErrorMessage(error));
  }
}

main();

工程口诀：

顶层 async 调用不要裸奔。
要么 main 内部 catch。
要么 main().catch(...).

18. try / catch 和函数分层

LabPilot 中推荐分三层：

API 层：fetchRunsByProjectId
业务转换层：createRunDashboardData
编排层：loadRunDashboardData
页面层：调用 loadRunDashboardData 并处理 loading / error / success

示例：

async function fetchRunsByProjectId(
  projectId: string,
): Promise<ExperimentRun[]> {
  // 只负责请求或模拟请求
  return [];
}

function createRunDashboardData(
  runs: ExperimentRun[],
): RunDashboardData {
  // 只负责同步数据转换
  return {
    totalRuns: runs.length,
    hasFailedRun: runs.some((run) => run.status === "failed"),
  };
}

async function loadRunDashboardData(
  projectId: string,
): Promise<RunDashboardData> {
  // 负责编排：异步加载 + 同步转换
  const runs = await fetchRunsByProjectId(projectId);

  return createRunDashboardData(runs);
}

async function renderDashboardPage(
  projectId: string,
): Promise<void> {
  // 页面层负责错误展示
  try {
    const dashboardData = await loadRunDashboardData(projectId);

    console.log("render:", dashboardData);
  } catch (error) {
    console.error("show error page:", getErrorMessage(error));
  }
}

工程原则：

越底层越专注。
越上层越负责用户体验。
错误可以在中间层补充日志，但不要无意识吞掉。

19. 当前工业界常用做法

19.1 async / await 中用 try / catch 处理失败

推荐：

async function loadData(): Promise<Data> {
  try {
    const data = await fetchData();

    return data;
  } catch (error) {
    console.error(getErrorMessage(error));

    throw error;
  }
}

19.2 catch 中按 unknown 处理 error

推荐：

catch (error) {
  console.error(getErrorMessage(error));
}

不推荐：

catch (error) {
  console.error(error.message);
}

19.3 明确错误策略

推荐：

// 关键数据：失败就抛
async function loadCriticalData(): Promise<Data> {
  try {
    return await fetchData();
  } catch (error) {
    console.error(getErrorMessage(error));

    throw error;
  }
}

// 可选数据：失败返回 null
async function loadOptionalData(): Promise<Data | null> {
  try {
    return await fetchData();
  } catch {
    return null;
  }
}

// 可降级数据：失败返回 fallback
async function loadDataWithFallback(): Promise<Data> {
  try {
    return await fetchData();
  } catch {
    return fallbackData;
  }
}

19.4 finally 用于 loading

前端中常见：

async function handleLoad(): Promise<void> {
  setLoading(true);

  try {
    const data = await loadData();

    setData(data);
  } catch (error) {
    setErrorMessage(getErrorMessage(error));
  } finally {
    setLoading(false);
  }
}

对应 LabPilot：

开始加载 Dashboard → loading = true
加载成功 → data = dashboardData
加载失败 → errorMessage = ...
无论成功失败 → loading = false

20. 老项目 / 常见写法

20.1 Promise 链错误处理

loadRunDashboardData("proj_001")
  .then((dashboardData) => {
    console.log(dashboardData);
  })
  .catch((error) => {
    console.error(error);
  })
  .finally(() => {
    console.log("done");
  });

等价的 async / await：

try {
  const dashboardData = await loadRunDashboardData("proj_001");

  console.log(dashboardData);
} catch (error) {
  console.error(error);
} finally {
  console.log("done");
}

20.2 callback 风格错误处理

loadRunsByProjectId("proj_001", (error, runs) => {
  if (error !== null) {
    console.error(error);

    return;
  }

  if (runs === null) {
    console.error("runs is null");

    return;
  }

  const dashboardData = createRunDashboardData(runs);

  console.log(dashboardData);
});

现代 async / await：

try {
  const runs = await fetchRunsByProjectId("proj_001");

  const dashboardData = createRunDashboardData(runs);

  console.log(dashboardData);
} catch (error) {
  console.error(error);
}

