}

写入代码：

// src/promise-all-demo.ts

type Project = {
  id: string;
  name: string;
};

type Paper = {
  id: string;
  title: string;
};

type Experiment = {
  id: string;
  projectId: string;
  name: string;
};

type RunStatus = "queued" | "running" | "finished" | "failed";

type ExperimentRun = {
  readonly id: string;
  readonly experimentId: string;
  status: RunStatus;
  metrics: Record<string, number>;
  startedAt: string;
};

type WorkspaceData = {
  projects: Project[];
  papers: Paper[];
  experiments: Experiment[];
  runs: ExperimentRun[];
};

type RunDashboardData = {
  totalRuns: number;
  hasFailedRun: boolean;
};

function getErrorMessage(error: unknown): string {
  if (error instanceof Error) {
    return error.message;
  }

  if (typeof error === "string") {
    return error;
  }

  return "Unknown error";
}

function delayValue<T>(
  value: T,
  delayMs: number,
  label: string,
): Promise<T> {
  return new Promise<T>((resolve) => {
    console.log(`${label} started`);

    setTimeout(() => {
      console.log(`${label} finished`);

      resolve(value);
    }, delayMs);
  });
}

function fetchProjects(workspaceId: string): Promise<Project[]> {
  return delayValue(
    [
      {
        id: "proj_001",
        name: `Project for ${workspaceId}`,
      },
    ],
    1000,
    "fetchProjects",
  );
}

function fetchPapers(workspaceId: string): Promise<Paper[]> {
  return delayValue(
    [
      {
        id: "paper_001",
        title: `Paper for ${workspaceId}`,
      },
    ],
    1000,
    "fetchPapers",
  );
}

function fetchExperiments(
  workspaceId: string,
): Promise<Experiment[]> {
  return delayValue(
    [
      {
        id: "exp_001",
        projectId: "proj_001",
        name: `Experiment for ${workspaceId}`,
      },
    ],
    1000,
    "fetchExperiments",
  );
}

function fetchRuns(workspaceId: string): Promise<ExperimentRun[]> {
  return delayValue(
    [
      {
        id: "run_001",
        experimentId: "exp_001",
        status: "finished",
        metrics: {
          accuracy: 0.91,
          loss: 0.23,
        },
        startedAt: "2026-06-25T10:00:00.000Z",
      },
      {
        id: "run_002",
        experimentId: "exp_001",
        status: "failed",
        metrics: {
          loss: 0.9,
        },
        startedAt: "2026-06-25T11:00:00.000Z",
      },
    ],
    1000,
    "fetchRuns",
  );
}

function createRunDashboardData(
  runs: ExperimentRun[],
): RunDashboardData {
  return {
    totalRuns: runs.length,
    hasFailedRun: runs.some((run) => {
      return run.status === "failed";
    }),
  };
}

async function loadWorkspaceSerial(
  workspaceId: string,
): Promise<WorkspaceData> {
  console.log("loadWorkspaceSerial started");

  const projects = await fetchProjects(workspaceId);
  const papers = await fetchPapers(workspaceId);
  const experiments = await fetchExperiments(workspaceId);
  const runs = await fetchRuns(workspaceId);

  console.log("loadWorkspaceSerial finished");

  return {
    projects,
    papers,
    experiments,
    runs,
  };
}

async function loadWorkspaceConcurrent(
  workspaceId: string,
): Promise<WorkspaceData> {
  console.log("loadWorkspaceConcurrent started");

  const [projects, papers, experiments, runs] = await Promise.all([
    fetchProjects(workspaceId),
    fetchPapers(workspaceId),
    fetchExperiments(workspaceId),
    fetchRuns(workspaceId),
  ]);

  console.log("loadWorkspaceConcurrent finished");

  return {
    projects,
    papers,
    experiments,
    runs,
  };
}

async function loadWorkspaceDashboard(
  workspaceId: string,
): Promise<{
  workspaceData: WorkspaceData;
  runDashboardData: RunDashboardData;
}> {
  const workspaceData = await loadWorkspaceConcurrent(workspaceId);

  const runDashboardData = createRunDashboardData(
    workspaceData.runs,
  );

  return {
    workspaceData,
    runDashboardData,
  };
}

async function main(): Promise<void> {
  console.log("=== serial ===");

  console.time("serial");
  const serialData = await loadWorkspaceSerial("workspace_001");
  console.timeEnd("serial");

  console.log("serial result:", serialData);

  console.log("=== concurrent ===");

  console.time("concurrent");
  const concurrentData = await loadWorkspaceConcurrent("workspace_001");
  console.timeEnd("concurrent");

  console.log("concurrent result:", concurrentData);

  console.log("=== dashboard ===");

  const dashboardResult = await loadWorkspaceDashboard("workspace_001");

  console.log("dashboard result:", dashboardResult);
}

main().catch((error) => {
  console.error("main failed:", getErrorMessage(error));
});

运行：

pnpm demo:promise-all

你会观察到：

serial 大约 4 秒。
concurrent 大约 1 秒。
Promise.all 中四个请求几乎同时 started。
Promise.all 的结果可以直接解构。
拿到 runs 后继续同步生成 runDashboardData。

22. 失败示例：Promise.all 一个失败整体失败

可以再写一个失败版函数：

function fetchPapersWithError(
  workspaceId: string,
): Promise<Paper[]> {
  return new Promise<Paper[]>((resolve, reject) => {
    console.log("fetchPapersWithError started");

    setTimeout(() => {
      reject(new Error(`Failed to fetch papers for ${workspaceId}`));
    }, 1000);
  });
}

失败版加载：

async function loadWorkspaceWithError(
  workspaceId: string,
): Promise<WorkspaceData> {
  const [projects, papers, experiments, runs] = await Promise.all([
    fetchProjects(workspaceId),
    fetchPapersWithError(workspaceId),
    fetchExperiments(workspaceId),
    fetchRuns(workspaceId),
  ]);

  return {
    projects,
    papers,
    experiments,
    runs,
  };
}

调用：

async function errorDemo(): Promise<void> {
  try {
    const data = await loadWorkspaceWithError("workspace_001");

    console.log(data);
  } catch (error) {
    console.error("workspace failed:", getErrorMessage(error));
  }
}

结果：

只要 fetchPapersWithError reject，整个 Promise.all reject。
catch 捕获错误。
不会得到部分成功结果。

23. Promise.all 空数组

一个小细节：

const results = await Promise.all([]);

结果是：

[]

它会立刻成功。

在批量请求中可能出现：

async function fetchRunsByIds(
  runIds: string[],
): Promise<ExperimentRun[]> {
  return Promise.all(
    runIds.map((runId) => {
      return fetchRunById(runId);
    }),
  );
}

如果：

runIds = []

那么：

Promise.all([])

会返回：

[]

这通常是合理的。

24. Promise.all 和 tuple 类型推断

在 TypeScript 中，直接写数组字面量：

const [projects, papers, runs] = await Promise.all([
  fetchProjects(workspaceId),
  fetchPapers(workspaceId),
  fetchRuns(workspaceId),
]);

TypeScript 一般能推断：

projects // Project[]
papers   // Paper[]
runs     // ExperimentRun[]

但如果你先把 Promise 放进普通数组：

const tasks = [
  fetchProjects(workspaceId),
  fetchPapers(workspaceId),
  fetchRuns(workspaceId),
];

const results = await Promise.all(tasks);

有些情况下，类型可能变宽成：

(Project[] | Paper[] | ExperimentRun[])[]

这样解构后类型不够精确。

学习阶段建议：

如果每个 Promise 返回不同类型，直接在 Promise.all([...]) 里写数组字面量。

或者使用对象封装，避免顺序错位。

25. Promise.all 顺序错位的问题

这种写法：

const [projects, papers, experiments, runs] = await Promise.all([
  fetchProjects(workspaceId),
  fetchPapers(workspaceId),
  fetchExperiments(workspaceId),
  fetchRuns(workspaceId),
]);

要求：

左边变量顺序必须和右边 Promise 顺序一致。

如果你写错：

const [projects, runs, papers, experiments] = await Promise.all([
  fetchProjects(workspaceId),
  fetchPapers(workspaceId),
  fetchExperiments(workspaceId),
  fetchRuns(workspaceId),
]);

逻辑就乱了。

为了减少顺序错位，可以拆成：

const projectsPromise = fetchProjects(workspaceId);
const papersPromise = fetchPapers(workspaceId);
const experimentsPromise = fetchExperiments(workspaceId);
const runsPromise = fetchRuns(workspaceId);

const [projects, papers, experiments, runs] = await Promise.all([
  projectsPromise,
  papersPromise,
  experimentsPromise,
  runsPromise,
]);

或者封装成函数：

async function loadWorkspace(
  workspaceId: string,
): Promise<WorkspaceData> {
  const [projects, papers, experiments, runs] = await Promise.all([
    fetchProjects(workspaceId),
    fetchPapers(workspaceId),
    fetchExperiments(workspaceId),
    fetchRuns(workspaceId),
  ]);

  return {
    projects,
    papers,
    experiments,
    runs,
  };
}

返回对象后，外部就不再关心顺序。

工程口诀：

Promise.all 内部可以用数组。
函数对外最好返回对象。

26. 当前工业界常用做法

26.1 页面初始化并发加载

常见：

async function loadInitialData(
  workspaceId: string,
): Promise<WorkspaceData> {
  const [projects, papers, experiments, runs] = await Promise.all([
    fetchProjects(workspaceId),
    fetchPapers(workspaceId),
    fetchExperiments(workspaceId),
    fetchRuns(workspaceId),
  ]);

  return {
    projects,
    papers,
    experiments,
    runs,
  };
}

适合页面首屏：

Dashboard
Workspace 首页
Project overview
Experiment overview

26.2 批量请求

async function fetchRunsByIds(
  runIds: string[],
): Promise<ExperimentRun[]> {
  return Promise.all(
    runIds.map((runId) => {
      return fetchRunById(runId);
    }),
  );
}

适合：

批量加载 selected runs
批量加载 paper metadata
批量加载 experiment detail
批量执行独立 Agent tools

26.3 并发后同步转换

async function loadRunDashboardData(
  workspaceId: string,
): Promise<RunDashboardData> {
  const runs = await fetchRuns(workspaceId);

  return createRunDashboardData(runs);
}

或者：

async function loadWorkspaceDashboard(
  workspaceId: string,
): Promise<{
  workspaceData: WorkspaceData;
  runDashboardData: RunDashboardData;
}> {
  const [projects, papers, experiments, runs] = await Promise.all([
    fetchProjects(workspaceId),
    fetchPapers(workspaceId),
    fetchExperiments(workspaceId),
    fetchRuns(workspaceId),
  ]);

  return {
    workspaceData: {
      projects,
      papers,
      experiments,
      runs,
    },
    runDashboardData: createRunDashboardData(runs),
  };
}

26.4 并发失败策略要明确

Promise.all 默认：

一个失败，整体失败。

所以使用前要问：

这些任务是否都必须成功？
如果其中一个失败，页面是否应该整体失败？

如果答案是是，用 Promise.all。

如果答案是否，下一节用：

Promise.allSettled

27. 老项目 / 常见写法

27.1 串行 await 导致慢

常见低效代码：

const projects = await fetchProjects(workspaceId);
const papers = await fetchPapers(workspaceId);
const experiments = await fetchExperiments(workspaceId);
const runs = await fetchRuns(workspaceId);

如果这些任务无依赖，应改为：

const [projects, papers, experiments, runs] = await Promise.all([
  fetchProjects(workspaceId),
  fetchPapers(workspaceId),
  fetchExperiments(workspaceId),
  fetchRuns(workspaceId),
]);

27.2 forEach async

错误：

runIds.forEach(async (runId) => {
  await fetchRunById(runId);
});

改为并发：

await Promise.all(
  runIds.map((runId) => {
    return fetchRunById(runId);
  }),
);

改为串行：

for (const runId of runIds) {
  await fetchRunById(runId);
}

27.3 then 风格 Promise.all

老项目中也常见：

Promise.all([
  fetchProjects(workspaceId),
  fetchPapers(workspaceId),
  fetchExperiments(workspaceId),
  fetchRuns(workspaceId),
])
  .then(([projects, papers, experiments, runs]) => {
    return {
      projects,
      papers,
      experiments,
      runs,
    };
  })
  .catch((error) => {
    console.error(error);
  });

你要能读懂，但自己写业务代码更推荐：

const [projects, papers, experiments, runs] = await Promise.all([...]);

