代码：

type AgentPanelData = {
  summary: AgentSummary | null;
  recommendedPapers: Paper[];
  activityItems: ActivityItem[];
  anomalyResult: AnomalyResult | null;
  warnings: string[];
};

async function loadAgentPanelData(
  projectId: string,
): Promise<AgentPanelData> {
  const [
    summaryResult,
    recommendedPapersResult,
    activityItemsResult,
    anomalyResult,
  ] = await Promise.allSettled([
    fetchAgentSummary(projectId),
    fetchRecommendedPapers(projectId),
    fetchActivityByProjectId(projectId),
    fetchAnomalyResult(projectId),
  ]);

  const warnings: string[] = [];

  const summary =
    summaryResult.status === "fulfilled"
      ? summaryResult.value
      : null;

  if (summaryResult.status === "rejected") {
    warnings.push(getErrorMessage(summaryResult.reason));
  }

  const recommendedPapers =
    recommendedPapersResult.status === "fulfilled"
      ? recommendedPapersResult.value
      : [];

  if (recommendedPapersResult.status === "rejected") {
    warnings.push(getErrorMessage(recommendedPapersResult.reason));
  }

  const activityItems =
    activityItemsResult.status === "fulfilled"
      ? activityItemsResult.value
      : [];

  if (activityItemsResult.status === "rejected") {
    warnings.push(getErrorMessage(activityItemsResult.reason));
  }

  const anomalyResultValue =
    anomalyResult.status === "fulfilled"
      ? anomalyResult.value
      : null;

  if (anomalyResult.status === "rejected") {
    warnings.push(getErrorMessage(anomalyResult.reason));
  }

  return {
    summary,
    recommendedPapers,
    activityItems,
    anomalyResult: anomalyResultValue,
    warnings,
  };
}

