// src/serial-vs-concurrent-demo.ts

type RunStatus = "queued" | "running" | "finished" | "failed";

type Project = {
  id: string;
  name: string;
};

type Paper = {
  id: string;
  title: string;
};

type Experiment = {
  id: string;
  projectId: string;
  name: string;
};

type ExperimentRun = {
  readonly id: string;
  readonly experimentId: string;
  status: RunStatus;
  metrics: Record<string, number>;
  startedAt: string;
};

type WorkspaceData = {
  projects: Project[];
  papers: Paper[];
  experiments: Experiment[];
  runs: ExperimentRun[];
};

function getErrorMessage(error: unknown): string {
  if (error instanceof Error) {
    return error.message;
  }

  if (typeof error === "string") {
    return error;
  }

  return "Unknown error";
}

function delayValue<T>(
  value: T,
  delayMs: number,
  label: string,
): Promise<T> {
  return new Promise<T>((resolve) => {
    console.log(`${label} started`);

    setTimeout(() => {
      console.log(`${label} finished`);

      resolve(value);
    }, delayMs);
  });
}

function fetchProjects(workspaceId: string): Promise<Project[]> {
  return delayValue(
    [
      {
        id: "proj_001",
        name: `Project for ${workspaceId}`,
      },
    ],
    1000,
    "fetchProjects",
  );
}

function fetchPapers(workspaceId: string): Promise<Paper[]> {
  return delayValue(
    [
      {
        id: "paper_001",
        title: `Paper for ${workspaceId}`,
      },
    ],
    1000,
    "fetchPapers",
  );
}

function fetchExperiments(
  workspaceId: string,
): Promise<Experiment[]> {
  return delayValue(
    [
      {
        id: "exp_001",
        projectId: "proj_001",
        name: `Experiment for ${workspaceId}`,
      },
    ],
    1000,
    "fetchExperiments",
  );
}

function fetchRuns(workspaceId: string): Promise<ExperimentRun[]> {
  return delayValue(
    [
      {
        id: "run_001",
        experimentId: "exp_001",
        status: "finished",
        metrics: {
          accuracy: 0.91,
        },
        startedAt: "2026-06-25T10:00:00.000Z",
      },
    ],
    1000,
    "fetchRuns",
  );
}

function fetchRunById(runId: string): Promise<ExperimentRun> {
  return delayValue(
    {
      id: runId,
      experimentId: "exp_001",
      status: "finished",
      metrics: {
        accuracy: 0.91,
      },
      startedAt: "2026-06-25T10:00:00.000Z",
    },
    1000,
    `fetchRunById(${runId})`,
  );
}

async function loadWorkspaceSerial(
  workspaceId: string,
): Promise<WorkspaceData> {
  const projects = await fetchProjects(workspaceId);
  const papers = await fetchPapers(workspaceId);
  const experiments = await fetchExperiments(workspaceId);
  const runs = await fetchRuns(workspaceId);

  return {
    projects,
    papers,
    experiments,
    runs,
  };
}

async function loadWorkspaceConcurrent(
  workspaceId: string,
): Promise<WorkspaceData> {
  const [projects, papers, experiments, runs] = await Promise.all([
    fetchProjects(workspaceId),
    fetchPapers(workspaceId),
    fetchExperiments(workspaceId),
    fetchRuns(workspaceId),
  ]);

  return {
    projects,
    papers,
    experiments,
    runs,
  };
}

async function fetchRunsByIdsSerial(
  runIds: string[],
): Promise<ExperimentRun[]> {
  const runs: ExperimentRun[] = [];

  for (const runId of runIds) {
    const run = await fetchRunById(runId);

    runs.push(run);
  }

  return runs;
}

async function fetchRunsByIdsConcurrent(
  runIds: string[],
): Promise<ExperimentRun[]> {
  return Promise.all(
    runIds.map((runId) => {
      return fetchRunById(runId);
    }),
  );
}

function chunkArray<T>(
  items: T[],
  chunkSize: number,
): T[][] {
  const chunks: T[][] = [];

  for (let index = 0; index < items.length; index += chunkSize) {
    chunks.push(items.slice(index, index + chunkSize));
  }

  return chunks;
}

async function fetchRunsByIdsInBatches(
  runIds: string[],
  batchSize: number,
): Promise<ExperimentRun[]> {
  const batches = chunkArray(runIds, batchSize);
  const allRuns: ExperimentRun[] = [];

  for (const batch of batches) {
    const runs = await Promise.all(
      batch.map((runId) => {
        return fetchRunById(runId);
      }),
    );

    allRuns.push(...runs);
  }

  return allRuns;
}

async function main(): Promise<void> {
  console.log("=== serial workspace load ===");

  console.time("serial workspace");
  await loadWorkspaceSerial("workspace_001");
  console.timeEnd("serial workspace");

  console.log("=== concurrent workspace load ===");

  console.time("concurrent workspace");
  await loadWorkspaceConcurrent("workspace_001");
  console.timeEnd("concurrent workspace");

  const runIds = ["run_001", "run_002", "run_003", "run_004"];

  console.log("=== serial run load ===");

  console.time("serial runs");
  await fetchRunsByIdsSerial(runIds);
  console.timeEnd("serial runs");

  console.log("=== concurrent run load ===");

  console.time("concurrent runs");
  await fetchRunsByIdsConcurrent(runIds);
  console.timeEnd("concurrent runs");

  console.log("=== batched run load ===");

  console.time("batched runs");
  await fetchRunsByIdsInBatches(runIds, 2);
  console.timeEnd("batched runs");
}

main().catch((error) => {
  console.error("main failed:", getErrorMessage(error));
});

运行：

pnpm demo:serial-concurrent

重点观察：

serial workspace 大约 4 秒
concurrent workspace 大约 1 秒

serial runs 大约 4 秒
concurrent runs 大约 1 秒
batched runs batchSize=2 大约 2 秒

这能直观看出三种策略：

串行：最慢，但最稳，顺序最清楚
全并发：最快，但压力最大
分批并发：速度和稳定性折中

