): Promise<T> {
  let timeoutId: ReturnType<typeof setTimeout> | undefined;

  const timeoutPromise = new Promise<never>((resolve, reject) => {
    timeoutId = setTimeout(() => {
      reject(new Error(`Task timed out after ${timeoutMs}ms`));
    }, timeoutMs);
  });

  try {
    return await Promise.race([
      task,
      timeoutPromise,
    ]);
  } finally {
    if (timeoutId !== undefined) {
      clearTimeout(timeoutId);
    }
  }
}

用途：

防止外部服务无限等待。
适合 LLM、Agent 工具、第三方 API、慢请求。

注意：

withTimeout 不一定真正取消底层任务。
它只是让调用方不继续等待。
真实取消请求后面需要 AbortController。

4.4 src/async/retry.ts

// src/async/retry.ts

import { sleep } from "./sleep.js";

export type RetryOptions = {
  retries: number;
  delayMs: number;
  backoffFactor?: number;
  maxDelayMs?: number;
  shouldRetry?: (error: unknown) => boolean;
  onRetry?: (error: unknown, attempt: number, delayMs: number) => void;
};

function calculateRetryDelay(
  attempt: number,
  options: RetryOptions,
): number {
  const backoffFactor = options.backoffFactor ?? 1;

  const rawDelay =
    options.delayMs * Math.pow(backoffFactor, attempt - 1);

  if (options.maxDelayMs === undefined) {
    return rawDelay;
  }

  return Math.min(rawDelay, options.maxDelayMs);
}

export async function retry<T>(
  task: () => Promise<T>,
  options: RetryOptions,
): Promise<T> {
  let lastError: unknown;

  for (let attempt = 0; attempt <= options.retries; attempt += 1) {
    try {
      return await task();
    } catch (error) {
      lastError = error;

      const canRetry =
        options.shouldRetry === undefined
          ? true
          : options.shouldRetry(error);

      if (!canRetry) {
        throw error;
      }

      if (attempt >= options.retries) {
        break;
      }

      const retryAttempt = attempt + 1;

      const delayMs = calculateRetryDelay(
        retryAttempt,
        options,
      );

      options.onRetry?.(error, retryAttempt, delayMs);

      await sleep(delayMs);
    }
  }

  throw lastError;
}

重点：

retry 的 task 必须是 () => Promise<T>
不能是 Promise<T>
因为 retry 需要每次重新发起任务。

错误写法：

const task = fetchRuns();

await retry(() => task, {
  retries: 3,
  delayMs: 1000,
});

正确写法：

await retry(() => fetchRuns(), {
  retries: 3,
  delayMs: 1000,
});

