// src/labpilot/loaders.ts

import {
  getErrorMessage,
  retry,
  withTimeout,
} from "../async/index.js";

import { createRunDashboardData } from "./dashboard.js";

import {
  fetchActivityItems,
  fetchAgentSummary,
  fetchExperiments,
  fetchPapers,
  fetchProjects,
  fetchRecommendedPapers,
  fetchRuns,
} from "./mock-api.js";

import type {
  ActivityItem,
  AgentPanelData,
  AgentSummary,
  Paper,
  WorkspaceData,
  WorkspacePageData,
  RunDashboardData,
} from "./types.js";

export async function loadWorkspaceData(
  workspaceId: string,
): Promise<WorkspaceData> {
  try {
    const [projects, papers, experiments, runs] = await Promise.all([
      fetchProjects(workspaceId),
      fetchPapers(workspaceId),
      fetchExperiments(workspaceId),
      fetchRuns(workspaceId),
    ]);

    return {
      projects,
      papers,
      experiments,
      runs,
    };
  } catch (error) {
    console.error(
      "loadWorkspaceData failed:",
      getErrorMessage(error),
    );

    throw error;
  }
}

这里用 Promise.all，因为这些是核心数据。

语义：

projects / papers / experiments / runs 全部成功，Workspace 才能正常展示。
任何一个失败，整个 workspace data 加载失败。

