  switch (state.status) {
    case "idle":
      return "Idle";

    case "loading":
      return "Loading";

    case "success":
      return "Success";

    case "error":
      return `Error: ${state.errorMessage}`;
  }
}

练习 5：定义 AsyncResult

type AsyncResult<T> =
  | {
      ok: true;
      data: T;
    }
  | {
      ok: false;
      errorMessage: string;
    };

使用：

function renderResult<T>(
  result: AsyncResult<T>,
): string {
  if (result.ok) {
    return "Success";
  }

  return result.errorMessage;
}

练习 6：AgentToolResult

type AgentToolResult =
  | {
      status: "success";
      output: unknown;
    }
  | {
      status: "failed";
      errorMessage: string;
    };

渲染：

function renderAgentToolResult(
  result: AgentToolResult,
): string {
  if (result.status === "success") {
    return JSON.stringify(result.output);
  }

  return result.errorMessage;
}

34. 本小点总结

本节必须记住：

字面量类型表示某个具体值本身。
联合类型表示一个值可以是几种类型之一。

最重要写法：

type RunStatus = "queued" | "running" | "finished" | "failed";

适合用联合类型的场景：

业务状态
加载状态
用户角色
Agent 工具状态
成功 / 失败结果
固定优先级
有限选项

核心工程判断：

固定状态，不用 string。
多状态，不用多个 boolean。
成功 / 失败，不用 data? + errorMessage? 硬凑。
用字面量联合或判别联合表达真实业务约束。

判别联合口诀：

每个分支有共同字段。
共同字段使用不同字面量值。
先判断共同字段，再访问该分支特有字段。

LabPilot 建模口诀：

RunStatus → "queued" | "running" | "finished" | "failed"
LoadState<T> → idle / loading / success / error
AsyncResult<T> → ok true / ok false
AgentToolResult → success / failed
WorkspaceRole → owner / admin / member / viewer

下一步进入：

7.10 函数类型：参数与返回值

阶段 1：JavaScript + TypeScript 语言基础

第 7 章：TypeScript 类型系统基础

小点 7.10：函数类型：参数与返回值

1. 当前小点解决什么工程问题

本小点解决的是：

TypeScript 中函数参数怎么写类型？
函数返回值怎么写类型？
什么时候返回 string / number / boolean / object？
什么时候返回 void？
什么时候返回 null？
什么时候返回 Promise<T>？
callback 函数类型怎么写？
为什么函数边界一定要有清晰类型？
LabPilot 中数据处理函数、异步加载函数、工具函数应该如何标注类型？

前面你已经学了：

type ExperimentRun = {
  readonly id: string;
  readonly experimentId: string;
  status: "queued" | "running" | "finished" | "failed";
  metrics: Record<string, number>;
  readonly startedAt: string;
  finishedAt?: string;
};

type RunDashboardData = {
  totalRuns: number;
  finishedRuns: number;
  failedRuns: number;
  hasFailedRun: boolean;
};

现在你要学会把它们用于函数边界：

function createRunDashboardData(
  runs: readonly ExperimentRun[],
): RunDashboardData {
  // ...
}

函数类型的核心价值是：

明确这个函数需要什么输入。
明确这个函数会产生什么输出。
让调用方知道怎么用。
让 TypeScript 帮你检查参数和返回值。

2. 函数类型的基本结构

TypeScript 中函数一般写成：

function functionName(
  parameterName: ParameterType,
): ReturnType {
  // function body
}

例如：

function formatAccuracy(accuracy: number): string {
  return `${(accuracy * 100).toFixed(2)}%`;
}

这里有两个类型位置：

accuracy: number    参数类型
): string           返回值类型

含义：

这个函数接收 number。
这个函数返回 string。

调用：

const text = formatAccuracy(0.9123);

text 的类型是：

string

3. 参数类型

3.1 基础参数类型

function getProjectUrl(projectId: string): string {
  return `/projects/${projectId}`;
}

调用：

const url = getProjectUrl("proj_001");

错误：

getProjectUrl(123); // ❌

因为 projectId 必须是 string。

3.2 多个参数

function formatMetric(
  metricName: string,
  value: number,
): string {
  return `${metricName}: ${value.toFixed(4)}`;
}

调用：

const text = formatMetric("loss", 0.23456);

返回：

loss: 0.2346

如果传错顺序：

formatMetric(0.23456, "loss"); // ❌

TypeScript 会报错。

3.3 boolean 参数

function getRunLabel(
  runId: string,
  isFinished: boolean,
): string {
  if (isFinished) {
    return `${runId} finished`;
  }

  return `${runId} not finished`;
}

这能工作，但如果 boolean 参数很多，可读性会变差。

不推荐：

createChart(true, false, true);

调用方很难知道这三个 true / false 分别是什么意思。

更推荐 options 对象：

type CreateChartOptions = {
  showLegend: boolean;
  enableZoom: boolean;
  showTooltip: boolean;
};

function createChart(options: CreateChartOptions): void {
  console.log(options.showLegend);
  console.log(options.enableZoom);
  console.log(options.showTooltip);
}

调用：

createChart({
  showLegend: true,
  enableZoom: false,
  showTooltip: true,
});

工程口诀：

少量语义明确的参数，可以直接写。
参数多、有 optional、有 boolean 时，优先用对象参数。

4. 返回值类型

4.1 返回 string

function getRunStatusLabel(
  status: RunStatus,
): string {
  switch (status) {
    case "queued":
      return "Queued";

    case "running":
      return "Running";

    case "finished":
      return "Finished";

    case "failed":
      return "Failed";
  }
}

这个函数输入 RunStatus，输出展示文本 string。

4.2 返回 number

function countRuns(
  runs: readonly ExperimentRun[],
): number {
  return runs.length;
}

返回值是 number。

4.3 返回 boolean

function hasFailedRuns(
  runs: readonly ExperimentRun[],
): boolean {
  return runs.some((run) => {
    return run.status === "failed";
  });
}

返回值是 boolean。

布尔函数常见命名：

isXxx
hasXxx
canXxx
shouldXxx

例如：

function isFinishedRun(run: ExperimentRun): boolean {
  return run.status === "finished";
}

function canCancelRun(run: ExperimentRun): boolean {
  return run.status === "queued" || run.status === "running";
}

4.4 返回对象

function createRunDashboardData(
  runs: readonly ExperimentRun[],
): RunDashboardData {
  const finishedRuns = runs.filter((run) => {
    return run.status === "finished";
  });

  const failedRuns = runs.filter((run) => {
    return run.status === "failed";
  });

  return {
    totalRuns: runs.length,
    finishedRuns: finishedRuns.length,
    failedRuns: failedRuns.length,
    hasFailedRun: failedRuns.length > 0,
  };
}

显式写返回类型的好处是：

如果你漏字段，TypeScript 会提醒。
如果字段类型写错，TypeScript 会提醒。
如果返回了错误结构，TypeScript 会提醒。

错误：

function createRunDashboardData(
  runs: readonly ExperimentRun[],
): RunDashboardData {
  return {
    totalRuns: runs.length,
    finishedRuns: 1,
    failedRuns: 0,
    // ❌ 缺少 hasFailedRun
  };
}

5. void：没有业务返回值

void 表示：

这个函数没有返回业务值。

例如：

function logProjectName(name: string): void {
  console.log(name);
}

调用：

const result = logProjectName("LabPilot");

result 实际上是：

undefined

但类型层面通常写 void，表示你不应该依赖它的返回值。

5.1 void 适合什么场景

适合：

打印日志
发送埋点
更新外部状态
事件处理函数
没有返回业务数据的 callback

示例：

function reportError(errorMessage: string): void {
  console.error("[ERROR]", errorMessage);
}

5.2 不要把有业务结果的函数写成 void

错误：

function formatAccuracy(accuracy: number): void {
  return `${(accuracy * 100).toFixed(2)}%`; // ❌
}

这个函数明显要返回字符串，所以应该写：

function formatAccuracy(accuracy: number): string {
  return `${(accuracy * 100).toFixed(2)}%`;
}

工程口诀：

有业务结果 → 返回 T。
只是执行动作 → 返回 void。

6. null：找不到或没有结果

有些函数可能找不到结果。

例如：

function findRunById(
  runs: readonly ExperimentRun[],
  runId: string,
): ExperimentRun | undefined {
  return runs.find((run) => {
    return run.id === runId;
  });
}

find 的语义是：

找到了就返回 ExperimentRun。
找不到就返回 undefined。

如果你想自己设计函数，也可以返回 null：

function getBestRunByAccuracy(
  runs: readonly ExperimentRun[],
): ExperimentRun | null {
  let bestRun: ExperimentRun | null = null;
  let bestAccuracy = -Infinity;

  for (const run of runs) {
    const accuracy = run.metrics.accuracy;

    if (accuracy === undefined) {
      continue;
    }

    if (accuracy > bestAccuracy) {
      bestAccuracy = accuracy;
      bestRun = run;
    }
  }

  return bestRun;
}

为什么返回：

ExperimentRun | null

因为：

可能没有任何 run 有 accuracy。
这时不存在 bestRun。

调用方必须判断：

const bestRun = getBestRunByAccuracy(runs);

if (bestRun === null) {
  console.log("No run has accuracy");
} else {
  console.log(bestRun.id);
}

工程口诀：

find 风格 → T | undefined。
业务上明确“没有结果” → T | null。
找不到就是异常 → throw error，返回 T。

7. throw 后函数仍可以返回 T

有些函数业务上要求必须找到。

例如：

function getRunById(
  runs: readonly ExperimentRun[],
  runId: string,
): ExperimentRun {
  const run = runs.find((item) => {
    return item.id === runId;
  });

  if (run === undefined) {
    throw new Error(`Run not found: ${runId}`);
  }

  return run;
}

这个函数返回类型是：

ExperimentRun

不是：

ExperimentRun | undefined

因为找不到时直接抛错，不会正常返回。

这类命名很常见：

findXxx：找不到返回 undefined / null
getXxx：找不到抛错或保证一定返回

示例：

const run = getRunById(runs, "run_001");

console.log(run.status);

这里不需要判断 undefined。

8. 异步函数返回 Promise<T>

第 6 章已经反复讲过：

同步函数返回 T。
异步函数返回 Promise<T>。

例如：

async function loadRuns(
  workspaceId: string,
): Promise<ExperimentRun[]> {
  return [
    {
      id: "run_001",
      experimentId: "exp_001",
      status: "finished",
      metrics: {
        accuracy: 0.91,
      },
      startedAt: "2026-06-25T10:00:00.000Z",
    },
  ];
}

调用：

const runs = await loadRuns("workspace_001");

runs 是：

ExperimentRun[]

但不 await 时：

const runsPromise = loadRuns("workspace_001");

runsPromise 是：

Promise<ExperimentRun[]>

8.1 async 函数不能写返回 T

错误：

async function loadRuns(
  workspaceId: string,
): ExperimentRun[] {
  return [];
}

应该写：

async function loadRuns(
  workspaceId: string,
): Promise<ExperimentRun[]> {
  return [];
}

即使函数内部 return []，外部看到的仍然是 Promise<ExperimentRun[]>。

8.2 异步函数返回 null

async function loadAgentSummaryOrNull(
  workspaceId: string,
): Promise<AgentSummary | null> {
  try {
    return await fetchAgentSummary(workspaceId);
  } catch {
    return null;
  }
}

注意返回类型：

Promise<AgentSummary | null>

不是：

AgentSummary | null

因为它是异步函数。

8.3 异步函数返回 Result

type AsyncResult<T> =
  | {
      ok: true;
      data: T;
    }
  | {
      ok: false;
      errorMessage: string;
    };

async function loadWorkspaceDataResult(
  workspaceId: string,
): Promise<AsyncResult<WorkspaceData>> {
  try {
    const data = await loadWorkspaceData(workspaceId);

    return {
      ok: true,
      data,
    };
  } catch (error) {
    return {
      ok: false,
      errorMessage: getErrorMessage(error),
    };
  }
}

调用：

const result = await loadWorkspaceDataResult("workspace_001");

if (result.ok) {
  console.log(result.data.projects.length);
} else {
  console.error(result.errorMessage);
}

9. 函数类型别名

你可以用 type 给函数类型起名字。

9.1 基础函数类型

type MetricFormatter = (value: number) => string;

使用：

const formatAccuracy: MetricFormatter = (value) => {
  return `${(value * 100).toFixed(2)}%`;
};

这里 TypeScript 知道：

value 是 number。
函数必须返回 string。

错误：

const badFormatter: MetricFormatter = (value) => {
  return value; // ❌ number 不能作为 string 返回
};

9.2 predicate 函数类型

predicate 是判断函数，通常返回 boolean。

type RunPredicate = (run: ExperimentRun) => boolean;

使用：

const isFailedRun: RunPredicate = (run) => {
  return run.status === "failed";
};

用于筛选：

function filterRuns(
  runs: readonly ExperimentRun[],
  predicate: RunPredicate,
): ExperimentRun[] {
  return runs.filter(predicate);
}

调用：

const failedRuns = filterRuns(runs, isFailedRun);

9.3 异步函数类型

type WorkspaceLoader = (
  workspaceId: string,
) => Promise<WorkspaceData>;

实现：

const loadWorkspaceData: WorkspaceLoader = async (workspaceId) => {
  return {
    projects: [],
    papers: [],
    experiments: [],
    runs: [],
  };
};

如果返回普通对象数组结构，TypeScript 会自动包装成 Promise，因为函数是 async。

10. callback 参数类型

函数可以接收另一个函数作为参数。

例如：

function mapRunsToText(
  runs: readonly ExperimentRun[],
  formatter: (run: ExperimentRun) => string,
): string[] {
  return runs.map(formatter);
}

调用：

const texts = mapRunsToText(runs, (run) => {
  return `${run.id}: ${run.status}`;
});

这里：

formatter: (run: ExperimentRun) => string

表示：

formatter 是一个函数。
它接收 ExperimentRun。
它返回 string。

如果 callback 复杂或复用多，就抽成 type：

type RunFormatter = (run: ExperimentRun) => string;

function mapRunsToText(
  runs: readonly ExperimentRun[],
  formatter: RunFormatter,
): string[] {
  return runs.map(formatter);
}

工程口诀：

一次性简单 callback 可以内联写。
复用型 callback 抽成 type。

11. options 参数对象类型

参数多时，用对象参数。

不推荐：

function createRun(
  id: string,
  experimentId: string,
  status: RunStatus,
  accuracy: number | undefined,
  loss: number | undefined,
): ExperimentRun {
  // ...
}

调用很难读：

createRun("run_001", "exp_001", "finished", 0.91, 0.23);

更推荐：

type CreateRunInput = {
  id: string;
  experimentId: string;
  status: RunStatus;
  metrics?: Record<string, number>;
  startedAt?: string;
  finishedAt?: string;
};

function createRun(input: CreateRunInput): ExperimentRun {
  return {
    id: input.id,
    experimentId: input.experimentId,
    status: input.status,
    metrics: input.metrics ?? {},
    startedAt: input.startedAt ?? new Date().toISOString(),
    finishedAt: input.finishedAt,
  };
}

调用：

const run = createRun({
  id: "run_001",
  experimentId: "exp_001",
  status: "finished",
  metrics: {
    accuracy: 0.91,
    loss: 0.23,
  },
  finishedAt: "2026-06-25T10:30:00.000Z",
});

更清晰。

工程口诀：

创建对象的函数，参数也用对象。

12. 默认参数类型

function formatMetric(
  value: number,
  digits = 4,
): string {
  return value.toFixed(digits);
}

这里 digits 会被推断为：

number

因为默认值 4 是 number。

调用：

formatMetric(0.912345);
formatMetric(0.912345, 2);

如果你传错：

formatMetric(0.912345, "2"); // ❌

会报错。

13. 可选参数

可选参数用 ?：

function createProjectTitle(
  name: string,
  prefix?: string,
): string {
  if (prefix === undefined) {
    return name;
  }

  return `${prefix}: ${name}`;
}

调用：

createProjectTitle("LabPilot");
createProjectTitle("LabPilot", "Project");

注意：

prefix?: string

在函数内部类型是：

string | undefined

所以要判断。

如果你只是想给默认值，更推荐默认参数：

function createProjectTitle(
  name: string,
  prefix = "Project",
): string {
  return `${prefix}: ${name}`;
}

14. 剩余参数

有时函数接收任意数量参数。

function joinTags(
  ...tags: string[]
): string {
  return tags.join(", ");
}

调用：

const text = joinTags("llm", "agent", "research");

tags 的类型是：

string[]

再比如：

function sumMetrics(
  ...values: number[]
): number {
  return values.reduce((sum, value) => {
    return sum + value;
  }, 0);
}

调用：

const total = sumMetrics(0.91, 0.88, 0.94);

15. 函数重载：先了解，不深入

TypeScript 支持函数重载，但初学阶段不要滥用。

例如：

function formatValue(value: string): string;
function formatValue(value: number): string;
function formatValue(value: string | number): string {
  if (typeof value === "number") {
    return value.toFixed(2);
  }

  return value.trim();
}

调用：

formatValue(" LabPilot ");
formatValue(0.9123);

当前阶段你只需要知道：

函数重载可以根据不同参数类型给出不同调用签名。
但业务代码中优先用联合类型和清晰函数设计。

很多时候这样就够了：

function formatValue(value: string | number): string {
  if (typeof value === "number") {
    return value.toFixed(2);
  }

  return value.trim();
}

16. 函数返回联合类型

函数可能返回不同类型。

例如：

function parsePositiveNumber(
  value: string,
): number | null {
  const parsed = Number(value);

  if (!Number.isFinite(parsed) || parsed <= 0) {
    return null;
  }

  return parsed;
}

调用：

const learningRate = parsePositiveNumber("0.001");

if (learningRate === null) {
  console.log("Invalid learning rate");
} else {
  console.log(learningRate.toFixed(4));
}

这里返回：

number | null

调用方必须判断。

17. 函数返回判别联合

更清晰的方式是返回 Result。

type ParseNumberResult =
  | {
      ok: true;
      value: number;
    }
  | {
      ok: false;
      errorMessage: string;
    };

function parsePositiveNumberResult(
  value: string,
): ParseNumberResult {
  const parsed = Number(value);

  if (!Number.isFinite(parsed)) {
    return {
      ok: false,
      errorMessage: "Value is not a valid number",
    };
  }

  if (parsed <= 0) {
    return {
      ok: false,
      errorMessage: "Value must be positive",
    };
  }

  return {
    ok: true,
    value: parsed,
  };
}

调用：

const result = parsePositiveNumberResult("0.001");

if (result.ok) {
  console.log(result.value);
} else {
  console.error(result.errorMessage);
}

工程选择：

简单失败 → T | null。
需要错误原因 → Result 联合类型。
异常情况 → throw Error。

18. 函数边界为什么建议显式写返回值

TypeScript 可以推断返回值：

function countRuns(runs: ExperimentRun[]) {
  return runs.length;
}

TypeScript 能推断返回 number。

但公共函数、业务函数、导出函数建议显式写：

function countRuns(
  runs: readonly ExperimentRun[],
): number {
  return runs.length;
}

原因：

返回值是函数契约的一部分。
显式写返回值可以防止你误返回错误结构。
重构时更安全。
调用方更容易理解。

尤其是对象返回值：

function createRunDashboardData(
  runs: readonly ExperimentRun[],
): RunDashboardData {
  // ...
}

这样如果漏字段，TypeScript 会立刻报错。

19. 什么时候可以不写返回值

函数内部很短、局部使用、不导出时，可以依赖推断。

例如：

const failedRuns = runs.filter((run) => {
  return run.status === "failed";
});

这里 callback 返回 boolean，TypeScript 能推断，不需要显式写：

const failedRuns = runs.filter((run): boolean => {
  return run.status === "failed";
});

简单箭头函数也可以依赖推断：

const runIds = runs.map((run) => run.id);

工程口诀：

公共函数返回值显式。
局部 callback 依赖推断。

20. LabPilot 函数分类

20.1 纯同步数据处理函数

function createRunDashboardData(
  runs: readonly ExperimentRun[],
): RunDashboardData {
  // ...
}

特点：

输入已有数据。
不请求网络。
不读文件。
不 await。
返回普通 T。

20.2 异步加载函数

async function loadWorkspaceData(
  workspaceId: string,
): Promise<WorkspaceData> {
  // await fetch...
}

特点：

需要等待 API / DB / 文件 / LLM。
返回 Promise<T>。

20.3 格式化函数

function formatAccuracy(accuracy: number): string {
  return `${(accuracy * 100).toFixed(2)}%`;
}

特点：

输入业务值。
输出展示字符串。
通常保持同步。

20.4 判断函数

function hasFailedRuns(
  runs: readonly ExperimentRun[],
): boolean {
  return runs.some((run) => run.status === "failed");
}

特点：

返回 boolean。
命名通常 is / has / can / should。

20.5 查找函数

function findRunById(
  runs: readonly ExperimentRun[],
  runId: string,
): ExperimentRun | undefined {
  return runs.find((run) => run.id === runId);
}

或：

function getRunById(
  runs: readonly ExperimentRun[],
  runId: string,
): ExperimentRun {
  const run = findRunById(runs, runId);

  if (run === undefined) {
    throw new Error(`Run not found: ${runId}`);
  }

  return run;
}

21. 最小可运行示例

创建文件：

New-Item src/function-types-demo.ts

在 package.json 添加：

{
  "scripts": {
    "demo:function-types": "tsx src/function-types-demo.ts"
  }
}

写入代码：

// src/function-types-demo.ts

type RunStatus = "queued" | "running" | "finished" | "failed";

type ExperimentRun = {
  readonly id: string;
  readonly experimentId: string;
  status: RunStatus;
  metrics: Record<string, number>;
  readonly startedAt: string;
  finishedAt?: string;
};

type RunDashboardData = {
  totalRuns: number;
  finishedRuns: number;
  failedRuns: number;
  runningRuns: number;
  hasFailedRun: boolean;
};

type MetricFormatter = (value: number) => string;

type RunPredicate = (run: ExperimentRun) => boolean;

type ParseNumberResult =
  | {
      ok: true;
      value: number;
    }
  | {
      ok: false;
      errorMessage: string;
    };

const formatAccuracy: MetricFormatter = (value) => {
  return `${(value * 100).toFixed(2)}%`;
};

const isFailedRun: RunPredicate = (run) => {
  return run.status === "failed";
};

function getRunStatusLabel(status: RunStatus): string {
  switch (status) {
    case "queued":
      return "Queued";

    case "running":
      return "Running";

    case "finished":
      return "Finished";

    case "failed":
      return "Failed";
  }
}

function canCancelRun(run: ExperimentRun): boolean {
  return run.status === "queued" || run.status === "running";
}

function findRunById(
  runs: readonly ExperimentRun[],
  runId: string,
): ExperimentRun | undefined {
  return runs.find((run) => {
    return run.id === runId;
  });
}

function getRunById(
  runs: readonly ExperimentRun[],
  runId: string,
): ExperimentRun {
  const run = findRunById(runs, runId);

  if (run === undefined) {
    throw new Error(`Run not found: ${runId}`);
  }

  return run;
}

function createRunDashboardData(
  runs: readonly ExperimentRun[],
): RunDashboardData {
  const finishedRuns = runs.filter((run) => {
    return run.status === "finished";
  });

  const failedRuns = runs.filter(isFailedRun);

  const runningRuns = runs.filter((run) => {
    return run.status === "running";
  });

  return {
    totalRuns: runs.length,
    finishedRuns: finishedRuns.length,
    failedRuns: failedRuns.length,
    runningRuns: runningRuns.length,
    hasFailedRun: failedRuns.length > 0,
  };
}

function parsePositiveNumberResult(
  value: string,
): ParseNumberResult {
  const parsed = Number(value);

  if (!Number.isFinite(parsed)) {
    return {
      ok: false,
      errorMessage: "Value is not a valid number",
    };
  }

  if (parsed <= 0) {
    return {
      ok: false,
      errorMessage: "Value must be positive",
    };
  }

  return {
    ok: true,
    value: parsed,
  };
}

async function loadRuns(
  workspaceId: string,
): Promise<ExperimentRun[]> {
  console.log("loading runs for:", workspaceId);

  return [
    {
      id: "run_001",
      experimentId: "exp_001",
      status: "finished",
      metrics: {
        accuracy: 0.91,
        loss: 0.23,
      },
      startedAt: "2026-06-25T10:00:00.000Z",
      finishedAt: "2026-06-25T10:30:00.000Z",
    },
    {
      id: "run_002",
      experimentId: "exp_001",
      status: "failed",
      metrics: {
        loss: 0.9,
      },
      startedAt: "2026-06-25T11:00:00.000Z",
    },
    {
      id: "run_003",
      experimentId: "exp_002",
      status: "running",
      metrics: {
        loss: 0.4,
      },
      startedAt: "2026-06-25T12:00:00.000Z",
    },
  ];
}

async function main(): Promise<void> {
  const runs = await loadRuns("workspace_001");

  const dashboardData = createRunDashboardData(runs);

  const targetRun = getRunById(runs, "run_001");

  const accuracy = targetRun.metrics.accuracy;

  console.log("dashboard:", dashboardData);
  console.log("target label:", getRunStatusLabel(targetRun.status));
  console.log("can cancel:", canCancelRun(targetRun));

  if (accuracy !== undefined) {
    console.log("accuracy:", formatAccuracy(accuracy));
  }

  const learningRateResult = parsePositiveNumberResult("0.001");

  if (learningRateResult.ok) {
    console.log("learning rate:", learningRateResult.value);
  } else {
    console.error("parse failed:", learningRateResult.errorMessage);
  }
}

main().catch((error: unknown) => {
  console.error(error);
});

运行：

pnpm demo:function-types

你应该重点观察：

formatAccuracy 是函数类型别名。
isFailedRun 是 predicate callback。
createRunDashboardData 是同步数据处理函数。
loadRuns 是异步函数，返回 Promise<ExperimentRun[]>。
findRunById 返回 ExperimentRun | undefined。
getRunById 找不到直接 throw，返回 ExperimentRun。
parsePositiveNumberResult 返回判别联合。

22. 故意制造错误，观察 TypeScript 保护

22.1 参数类型传错

formatAccuracy("0.91"); // ❌

原因：

formatAccuracy 需要 number。
你传了 string。

22.2 返回值类型写错

function countRuns(
  runs: readonly ExperimentRun[],
): number {
  return "3"; // ❌
}

原因：

函数声明返回 number。
实际返回 string。

22.3 async 函数返回类型写错

async function loadRuns(): ExperimentRun[] {
  return [];
}

修复：

async function loadRuns(): Promise<ExperimentRun[]> {
  return [];
}

22.4 find 结果不处理 undefined

const run = findRunById(runs, "run_001");

console.log(run.status); // ❌

修复：

if (run !== undefined) {
  console.log(run.status);
}

或者：

const run = getRunById(runs, "run_001");

console.log(run.status);

22.5 callback 返回值错误

const badPredicate: RunPredicate = (run) => {
  return run.id; // ❌
};

原因：

RunPredicate 要求返回 boolean。
run.id 是 string。

修复：

const goodPredicate: RunPredicate = (run) => {
  return run.status === "failed";
};

23. 当前工业界常用做法

23.1 导出函数显式写参数和返回值

推荐：

export function createRunDashboardData(
  runs: readonly ExperimentRun[],
): RunDashboardData {
  // ...
}

23.2 内部简单 callback 依赖推断

推荐：

const failedRuns = runs.filter((run) => {
  return run.status === "failed";
});

不必写：

const failedRuns = runs.filter((run: ExperimentRun): boolean => {
  return run.status === "failed";
});

23.3 异步函数返回 Promise

推荐：

export async function loadWorkspaceData(
  workspaceId: string,
): Promise<WorkspaceData> {
  // ...
}

23.4 options 对象替代复杂参数列表

推荐：

type CreateRunInput = {
  id: string;
  experimentId: string;
  status: RunStatus;
  metrics?: Record<string, number>;
};

function createRun(input: CreateRunInput): ExperimentRun {
  // ...
}

23.5 Result 类型替代不清晰的 null

如果失败原因重要：

type AsyncResult<T> =
  | {
      ok: true;
      data: T;
    }
  | {
      ok: false;
      errorMessage: string;
    };

比单纯返回 T | null 更清楚。

24. 老项目 / 常见写法

24.1 函数参数不写类型

function createDashboardData(runs) {
  return {
    totalRuns: runs.length,
  };
}

问题：

runs 是什么不清楚。
调用方可能传错。
函数内部没有自动提示。

更好：

function createDashboardData(
  runs: readonly ExperimentRun[],
): RunDashboardData {
  return {
    totalRuns: runs.length,
    finishedRuns: 0,
    failedRuns: 0,
    runningRuns: 0,
    hasFailedRun: false,
  };
}

24.2 返回值不写，导致漏字段不明显

function createDashboardData(runs: ExperimentRun[]) {
  return {
    totalRuns: runs.length,
  };
}

如果你本来期望 RunDashboardData，应该显式写：

function createDashboardData(
  runs: readonly ExperimentRun[],
): RunDashboardData {
  // ...
}

24.3 使用 any 函数

function handleData(data: any): any {
  return data.result.value;
}

问题：

TypeScript 完全失去保护。
字段写错也不报错。

更好：

function handleData(data: unknown): string {
  // 先校验，再使用
  return "TODO";
}

后面会详细讲 unknown。

24.4 callback 类型写得太长

function retry(
  task: () => Promise<unknown>,
  onRetry?: (
    error: unknown,
    attempt: number,
    delayMs: number,
  ) => void,
): Promise<unknown> {
  // ...
}

可以抽成：

type OnRetry = (
  error: unknown,
  attempt: number,
  delayMs: number,
) => void;

