formatAccuracy(value: number): string
isFailedRun(run: ExperimentRun): boolean
createRunDashboardData(runs): RunDashboardData
findRunById(runs, id): ExperimentRun | undefined
getRunById(runs, id): ExperimentRun
loadWorkspaceData(workspaceId): Promise<WorkspaceData>
loadWorkspaceDataResult(workspaceId): Promise<AsyncResult<WorkspaceData>>

