  // ...
}

26. 老项目 / 常见写法

26.1 到处写冗余类型

const totalRuns: number = runs.length;
const projectName: string = project.name;
const hasFailedRun: boolean = failedRuns.length > 0;

不是错误，但很多时候冗余。

更简洁：

const totalRuns = runs.length;
const projectName = project.name;
const hasFailedRun = failedRuns.length > 0;

26.2 函数参数不写类型

function createDashboardData(runs) {
  return {
    totalRuns: runs.length,
  };
}

这是更严重的问题。

应该改成：

function createDashboardData(
  runs: readonly ExperimentRun[],
): RunDashboardData {
  // ...
}

26.3 大量 as 强行断言

const config = {
  appName: "LabPilot",
  enableAgent: true,
} as AppConfig;

如果只是为了检查结构，更推荐：

const config = {
  appName: "LabPilot",
  enableAgent: true,
} satisfies AppConfig;

as 是告诉 TypeScript “相信我”。

satisfies 是让 TypeScript “帮我检查”。

