export function createXxx(...): Xxx {
  return { ... };
}

28.4 看到 as，问能不能用 satisfies

如果是常量配置：

const labels = { ... } as Record<RunStatus, string>;

更推荐：

const labels = { ... } satisfies Record<RunStatus, string>;

如果是外部输入：

const project = raw as Project;

更推荐：

unknown + 类型守卫 / Zod

