// src/labpilot-types/agent.ts

export type AgentToolStatus =
  | "pending"
  | "running"
  | "success"
  | "failed"
  | "cancelled";

export type AgentToolResult =
  | {
      status: "success";
      output: unknown;
    }
  | {
      status: "failed";
      errorMessage: string;
    };

export type AgentToolCall = {
  readonly id: string;
  toolName: string;
  status: AgentToolStatus;
  input: unknown;
  output?: unknown;
  errorMessage?: string;
  readonly createdAt: string;
  finishedAt?: string;
};

export interface AgentTool {
  readonly name: string;
  readonly description: string;
  execute(input: unknown): Promise<AgentToolResult>;
}

这里的选择很关键：

AgentToolStatus → type union
AgentToolResult → type 判别联合
AgentToolCall → type 业务数据
AgentTool → interface 能力契约

为什么 AgentTool 用 interface？

因为它描述的是工具必须具备的能力：

name
description
execute

未来不同 class 都可以实现它。

