// src/labpilot-utils/metric-utils.ts

export type MetricFormatter = (value: number) => string;

export const formatAccuracy: MetricFormatter = (value) => {
  return `${(value * 100).toFixed(2)}%`;
};

export function formatMetric(
  metricName: string,
  value: number,
  digits = 4,
): string {
  return `${metricName}: ${value.toFixed(digits)}`;
}

export function getMetricValue(
  metrics: Record<string, number>,
  metricName: string,
): number | null {
  const value = metrics[metricName];

  if (value === undefined) {
    return null;
  }

  return value;
}

export function getBestMetricValue(
  metricMaps: readonly Record<string, number>[],
  metricName: string,
): number | null {
  let bestValue: number | null = null;

  for (const metrics of metricMaps) {
    const value = metrics[metricName];

    if (value === undefined) {
      continue;
    }

    if (bestValue === null || value > bestValue) {
      bestValue = value;
    }
  }

  return bestValue;
}

重点：

getMetricValue(...): number | null

表示：

metric 可能不存在。
不存在时返回 null。

不要返回 0，因为 0 是合法指标值。

