// src/labpilot-utils/run-utils.ts

import type {
  CreateRunInput,
  ExperimentRun,
  RunDashboardData,
  RunStatus,
  RunStatusCounts,
} from "../labpilot-types/index.js";

import {
  RUN_STATUSES,
} from "../labpilot-types/index.js";

export const RUN_STATUS_LABELS = {
  queued: "Queued",
  running: "Running",
  finished: "Finished",
  failed: "Failed",
} satisfies Record<RunStatus, string>;

export function createRun(
  input: CreateRunInput,
): ExperimentRun {
  return {
    id: input.id,
    experimentId: input.experimentId,
    status: input.status ?? "queued",
    metrics: input.metrics ?? {},
    startedAt: input.startedAt ?? new Date().toISOString(),
    finishedAt: input.finishedAt,
  };
}

export function getRunStatusLabel(
  status: RunStatus,
): string {
  return RUN_STATUS_LABELS[status];
}

export function isRunStatus(
  value: unknown,
): value is RunStatus {
  return RUN_STATUSES.includes(value as RunStatus);
}

export function isFinishedRun(
  run: ExperimentRun,
): boolean {
  return run.status === "finished";
}

export function isFailedRun(
  run: ExperimentRun,
): boolean {
  return run.status === "failed";
}

export function canCancelRun(
  run: ExperimentRun,
): boolean {
  return run.status === "queued" || run.status === "running";
}

export function findRunById(
  runs: readonly ExperimentRun[],
  runId: string,
): ExperimentRun | undefined {
  return runs.find((run) => {
    return run.id === runId;
  });
}

export function getRunById(
  runs: readonly ExperimentRun[],
  runId: string,
): ExperimentRun {
  const run = findRunById(runs, runId);

  if (run === undefined) {
    throw new Error(`Run not found: ${runId}`);
  }

  return run;
}

export function createInitialRunStatusCounts(): RunStatusCounts {
  return {
    queued: 0,
    running: 0,
    finished: 0,
    failed: 0,
  };
}

export function createRunDashboardData(
  runs: readonly ExperimentRun[],
): RunDashboardData {
  const statusCounts = createInitialRunStatusCounts();

  for (const run of runs) {
    statusCounts[run.status] += 1;
  }

  const accuracyValues = runs.flatMap((run) => {
    const accuracy = run.metrics.accuracy;

    if (accuracy === undefined) {
      return [];
    }

    return [accuracy];
  });

  const bestAccuracy =
    accuracyValues.length === 0
      ? null
      : Math.max(...accuracyValues);

  return {
    totalRuns: runs.length,
    statusCounts,
    queuedRuns: statusCounts.queued,
    runningRuns: statusCounts.running,
    finishedRuns: statusCounts.finished,
    failedRuns: statusCounts.failed,
    hasFailedRun: statusCounts.failed > 0,
    bestAccuracy,
  };
}

