// src/labpilot-type-modeling-demo.ts

import type {
  AgentTool,
  AgentToolResult,
  AsyncResult,
  Experiment,
  ExperimentRun,
  LoadState,
  Paper,
  Project,
  WorkspaceData,
} from "./labpilot-types/index.js";

import {
  createProject,
  createRun,
  createRunDashboardData,
  formatAccuracy,
  getErrorMessage,
  getProjectDescription,
  getRunById,
  getRunStatusLabel,
  isProject,
  parseProjectFromJson,
  readPositiveNumberConfig,
} from "./labpilot-utils/index.js";

class EchoAgentTool implements AgentTool {
  readonly name = "echo";

  readonly description = "Return input as output";

  async execute(input: unknown): Promise<AgentToolResult> {
    return {
      status: "success",
      output: input,
    };
  }
}

function createSuccessResult<T>(data: T): AsyncResult<T> {
  return {
    ok: true,
    data,
  };
}

function createErrorResult<T>(
  errorMessage: string,
): AsyncResult<T> {
  return {
    ok: false,
    errorMessage,
  };
}

function renderWorkspaceLoadState(
  state: LoadState<WorkspaceData>,
): string {
  switch (state.status) {
    case "idle":
      return "Workspace is idle";

    case "loading":
      return "Workspace is loading";

    case "success":
      return `Workspace loaded: ${state.data.projects.length} projects`;

    case "error":
      return `Workspace failed: ${state.errorMessage}`;
  }
}

function renderProjectListItem(
  project: {
    id: string;
    name: string;
  },
): string {
  return `${project.id}: ${project.name}`;
}

async function loadWorkspaceData(): Promise<WorkspaceData> {
  const project = createProject({
    id: "proj_001",
    name: "LabPilot",
    description: "AI ResearchOps Platform",
  });

  const paper: Paper = {
    id: "paper_001",
    title: "A Survey on Efficient LLM Agents",
    authors: ["Alice", "Bob"],
    citationCount: 128,
    isRead: true,
    createdAt: "2026-06-25T10:00:00.000Z",
    updatedAt: "2026-06-25T10:00:00.000Z",
  };

  const experiment: Experiment = {
    id: "exp_001",
    projectId: project.id,
    name: "Baseline Experiment",
    createdAt: "2026-06-25T10:00:00.000Z",
    updatedAt: "2026-06-25T10:00:00.000Z",
  };

  const runs: ExperimentRun[] = [
    createRun({
      id: "run_001",
      experimentId: experiment.id,
      status: "finished",
      metrics: {
        accuracy: 0.91,
        loss: 0.23,
      },
      startedAt: "2026-06-25T10:00:00.000Z",
      finishedAt: "2026-06-25T10:30:00.000Z",
    }),
    createRun({
      id: "run_002",
      experimentId: experiment.id,
      status: "failed",
      metrics: {
        loss: 0.9,
      },
      startedAt: "2026-06-25T11:00:00.000Z",
    }),
    createRun({
      id: "run_003",
      experimentId: "exp_002",
      status: "running",
      metrics: {
        loss: 0.4,
      },
      startedAt: "2026-06-25T12:00:00.000Z",
    }),
  ];

  return {
    id: "workspace_001",
    name: "LabPilot Workspace",
    projects: [project],
    papers: [paper],
    experiments: [experiment],
    runs,
  };
}

async function main(): Promise<void> {
  const workspaceData = await loadWorkspaceData();

  const workspaceResult = createSuccessResult(workspaceData);

  if (workspaceResult.ok) {
    console.log("workspace:", workspaceResult.data.name);
  }

  const loadState: LoadState<WorkspaceData> = {
    status: "success",
    data: workspaceData,
  };

  console.log("load state:", renderWorkspaceLoadState(loadState));

  const firstProject = workspaceData.projects[0];

  if (firstProject !== undefined) {
    console.log("project item:", renderProjectListItem(firstProject));
    console.log("project description:", getProjectDescription(firstProject));
  }

  const dashboardData = createRunDashboardData(workspaceData.runs);

  console.log("dashboard:", dashboardData);

  const run = getRunById(workspaceData.runs, "run_001");

  console.log("run status:", getRunStatusLabel(run.status));

  const accuracy = run.metrics.accuracy;

  if (accuracy !== undefined) {
    console.log("accuracy:", formatAccuracy(accuracy));
  }

  const rawProjectJson = JSON.stringify({
    id: "proj_002",
    name: "Parsed Project",
    createdAt: "2026-06-25T13:00:00.000Z",
    updatedAt: "2026-06-25T13:00:00.000Z",
    archivedAt: null,
  });

  const parsedProject = parseProjectFromJson(rawProjectJson);

  if (parsedProject !== null) {
    console.log("parsed project:", parsedProject.name);
  }

  const rawValue: unknown = {
    id: "proj_003",
    name: "Unknown Input Project",
    createdAt: "2026-06-25T14:00:00.000Z",
    updatedAt: "2026-06-25T14:00:00.000Z",
    archivedAt: null,
  };

  if (isProject(rawValue)) {
    const project: Project = rawValue;

    console.log("unknown narrowed to project:", project.name);
  }

  const config: Record<string, unknown> = {
    learningRate: 0.001,
    batchSize: 32,
  };

  const learningRate = readPositiveNumberConfig(
    config,
    "learningRate",
  );

  console.log("learning rate:", learningRate);

  const tool = new EchoAgentTool();

  const toolResult = await tool.execute({
    message: "hello from LabPilot Agent",
  });

  if (toolResult.status === "success") {
    console.log("tool output:", toolResult.output);
  } else {
    console.error("tool failed:", toolResult.errorMessage);
  }

  const failedResult = createErrorResult<WorkspaceData>(
    "Failed to load workspace",
  );

  if (!failedResult.ok) {
    console.log("failed result:", failedResult.errorMessage);
  }
}

main().catch((error: unknown) => {
  console.error("main failed:", getErrorMessage(error));
});

