  finishedAt?: string;
};

练习 4：创建 Project

type CreateProjectInput = {
  id: string;
  name: string;
  description?: string;
};

function createProject(input: CreateProjectInput): Project {
  const now = new Date().toISOString();

  return {
    id: input.id,
    name: input.name,
    description: input.description,
    createdAt: now,
    updatedAt: now,
    archivedAt: null,
  };
}

练习 5：安全读取 description

function getProjectDescription(project: Project): string {
  return project.description ?? "No description";
}

练习 6：判断 archivedAt

function isProjectArchived(project: Project): boolean {
  return project.archivedAt !== null;
}

练习 7：返回 Dashboard 对象

type RunDashboardData = {
  totalRuns: number;
  failedRuns: number;
  hasFailedRun: boolean;
};

function createRunDashboardData(
  runs: readonly ExperimentRun[],
): RunDashboardData {
  const failedRuns = runs.filter((run) => {
    return run.status === "failed";
  });

  return {
    totalRuns: runs.length,
    failedRuns: failedRuns.length,
    hasFailedRun: failedRuns.length > 0,
  };
}

25. 本小点总结

本节必须记住：

对象类型描述的是对象结构。
每个字段都应该有明确类型。

字段规则：

默认字段必需。
? 表示字段可选。
| null 表示字段存在但值可为空。
readonly 表示字段不能直接修改。
对象字段可以是 string / number / boolean / null / 数组 / 另一个对象。
动态 key 可以用 Record<string, T>。

工程口诀：

业务对象抽成 type。
函数边界写对象类型。
可选字段读取要处理 undefined。
可空字段读取要判断 null。
ID / createdAt / 外键通常 readonly。
参数多时用 input/options 对象。
返回对象时显式写返回类型。
对象展开是浅拷贝。

LabPilot 建模口诀：

Project → 项目实体
Paper → 论文实体
Experiment → 实验实体
ExperimentRun → 实验运行记录
WorkspaceData → 多个对象数组组合
RunDashboardData → Dashboard 派生数据
CreateProjectInput → 创建对象的输入参数
metrics → Record<string, number>

下一步进入：

7.6 type 类型别名

阶段 1：JavaScript + TypeScript 语言基础

第 7 章：TypeScript 类型系统基础

小点 7.6：type 类型别名

1. 当前小点解决什么工程问题

这一节解决的是：

TypeScript 中 type 到底是什么？
为什么要给类型起名字？
type 可以定义哪些类型？
type 只能定义对象吗？
type 如何表达业务状态？
type 如何表达函数类型？
type 如何组合已有类型？
LabPilot 中 Project / Paper / ExperimentRun / RunStatus 应该如何用 type 建模？

前面 7.5 你已经开始这样写：

type Project = {
  readonly id: string;
  name: string;
  description?: string;
  archivedAt: string | null;
};

这里的 type Project = ... 就是类型别名。

它的核心作用是：

给一个类型起名字，让它可以复用、组合、导出、导入。

2. type 是什么

type 的英文完整含义是：

type alias

也就是：

类型别名

它不是创建运行时变量，而是给 TypeScript 的类型结构起一个名字。

例如：

type ProjectId = string;

表示：

ProjectId 是 string 的一个类型别名。

再比如：

type Project = {
  id: string;
  name: string;
};

表示：

Project 是一个对象类型的名字。
这个对象必须有 id 和 name。

注意：

type 只存在于 TypeScript 编译期。
编译成 JavaScript 后会消失。

所以不能写：

console.log(Project); // ❌

也不能写：

value instanceof Project; // ❌

因为 Project 不是运行时 class。

3. 为什么要用 type

假设你不使用 type，函数可能会这样写：

function getProjectName(project: {
  id: string;
  name: string;
  description?: string;
}): string {
  return project.name;
}

另一个函数也要用同样结构：

function renameProject(
  project: {
    id: string;
    name: string;
    description?: string;
  },
  nextName: string,
): {
  id: string;
  name: string;
  description?: string;
} {
  return {
    ...project,
    name: nextName,
  };
}

问题很明显：

对象结构重复。
代码很长。
修改字段时要改很多地方。
读者看不出这是 Project。

更好：

type Project = {
  id: string;
  name: string;
  description?: string;
};

function getProjectName(project: Project): string {
  return project.name;
}

function renameProject(
  project: Project,
  nextName: string,
): Project {
  return {
    ...project,
    name: nextName,
  };
}

这样更清楚：

Project 是一个明确的业务类型。
多个函数复用同一个模型。
修改字段只需要改 Project 定义。

4. type 可以定义基础类型别名

最简单的 type：

type ProjectId = string;
type ExperimentId = string;
type RunId = string;

使用：

const projectId: ProjectId = "proj_001";
const experimentId: ExperimentId = "exp_001";
const runId: RunId = "run_001";

这有什么用？

它主要提升可读性。

对比：

function loadProject(projectId: string): void {}

和：

function loadProject(projectId: ProjectId): void {}

第二种更有业务语义。

但是要注意：

type ProjectId = string;
type UserId = string;

const projectId: ProjectId = "proj_001";
const userId: UserId = projectId;

在普通 TypeScript 中，这通常是允许的。

因为：

ProjectId 和 UserId 本质上都是 string 的别名。
type 基础别名主要提升语义，不提供强隔离。

后面进阶会讲 branded type，它可以更严格地区分 ProjectId 和 UserId。

当前阶段先记住：

基础类型别名是语义提示，不是强品牌隔离。

5. type 可以定义对象类型

这是你目前最常用的写法。

type Project = {
  readonly id: string;
  name: string;
  description?: string;
  readonly createdAt: string;
  updatedAt: string;
  archivedAt: string | null;
};

使用：

const project: Project = {
  id: "proj_001",
  name: "LabPilot",
  description: "AI ResearchOps Platform",
  createdAt: "2026-06-25T10:00:00.000Z",
  updatedAt: "2026-06-25T10:00:00.000Z",
  archivedAt: null,
};

对象类型中可以包含：

必需字段
可选字段
readonly 字段
nullable 字段
数组字段
嵌套对象字段
动态 Record 字段

例如：

type Paper = {
  readonly id: string;
  title: string;
  authors: string[];
  abstract?: string;
  citationCount: number;
  isRead: boolean;
};

6. type 可以定义联合类型

这是 type 非常重要的能力。

例如：

type RunStatus = "queued" | "running" | "finished" | "failed";

表示：

RunStatus 只能是这四个字符串之一。

使用：

const statusA: RunStatus = "queued";
const statusB: RunStatus = "running";
const statusC: RunStatus = "finished";
const statusD: RunStatus = "failed";

非法：

const status: RunStatus = "finish"; // ❌

因为 "finish" 不在联合类型中。

LabPilot 中常见状态：

type RunStatus = "queued" | "running" | "finished" | "failed";

type LoadStatus = "idle" | "loading" | "success" | "error";

type AgentToolStatus =
  | "pending"
  | "running"
  | "success"
  | "failed"
  | "cancelled";

type WorkspaceRole = "owner" | "admin" | "member" | "viewer";

工程口诀：

固定业务状态，不要用裸 string。
用 type + 字面量联合类型。

7. 为什么状态不要写成 string

不推荐：

type ExperimentRun = {
  id: string;
  status: string;
};

这样任何字符串都能传：

const run: ExperimentRun = {
  id: "run_001",
  status: "anything",
};

这对业务没有约束。

更推荐：

type RunStatus = "queued" | "running" | "finished" | "failed";

type ExperimentRun = {
  id: string;
  status: RunStatus;
};

这样：

const run: ExperimentRun = {
  id: "run_001",
  status: "finish", // ❌
};

TypeScript 会提前报错。

这就是类型系统的价值：

把运行时才会暴露的状态拼写错误，提前变成开发期错误。

8. type 可以定义数组类型

可以给数组类型起别名：

type ProjectList = Project[];
type RunList = ExperimentRun[];
type ProjectIds = string[];

使用：

const projects: ProjectList = [
  {
    id: "proj_001",
    name: "LabPilot",
    createdAt: "2026-06-25T10:00:00.000Z",
    updatedAt: "2026-06-25T10:00:00.000Z",
    archivedAt: null,
  },
];

不过工程中不一定每个数组都要起别名。

很多时候：

Project[]
ExperimentRun[]
string[]

已经很清楚。

适合起数组别名的场景：

这个数组概念经常复用。
这个数组本身有业务语义。
类型较长，需要简化。

例如：

type RunHistory = ExperimentRun[];
type MetricSeries = number[];

9. type 可以定义函数类型

函数类型也可以用 type 命名。

type MetricFormatter = (value: number) => string;

含义：

MetricFormatter 是一个函数类型。
它接收 number。
它返回 string。

使用：

const formatAccuracy: MetricFormatter = (value) => {
  return `${(value * 100).toFixed(2)}%`;
};

如果返回值错误：

const badFormatter: MetricFormatter = (value) => {
  return value; // ❌
};

会报错。

因为 MetricFormatter 要求返回 string，但这里返回了 number。

10. 常见函数类型别名

10.1 判断函数 Predicate

type RunPredicate = (run: ExperimentRun) => boolean;

使用：

const isFailedRun: RunPredicate = (run) => {
  return run.status === "failed";
};

用于筛选：

function filterRuns(
  runs: readonly ExperimentRun[],
  predicate: RunPredicate,
): ExperimentRun[] {
  return runs.filter(predicate);
}

10.2 格式化函数 Formatter

type MetricFormatter = (value: number) => string;

使用：

const formatLoss: MetricFormatter = (value) => {
  return value.toFixed(4);
};

10.3 异步加载函数 Loader

type WorkspaceLoader = (
  workspaceId: string,
) => Promise<WorkspaceData>;

使用：

const loadWorkspaceData: WorkspaceLoader = async (workspaceId) => {
  return {
    id: workspaceId,
    name: "LabPilot Workspace",
    projects: [],
    papers: [],
    experiments: [],
    runs: [],
  };
};

10.4 回调函数 Callback

type OnRetry = (
  error: unknown,
  attempt: number,
  delayMs: number,
) => void;

使用：

type RetryOptions = {
  retries: number;
  delayMs: number;
  onRetry?: OnRetry;
};

工程口诀：

简单 callback 可以内联。
重要 callback 抽成 type。

11. type 可以定义交叉类型 &

交叉类型用：

&

表示：

把多个对象类型合并成一个更大的类型。

例如很多实体都有公共字段：

type EntityBase = {
  readonly id: string;
  readonly createdAt: string;
  updatedAt: string;
};

Project 可以组合它：

type Project = EntityBase & {
  name: string;
  description?: string;
  archivedAt: string | null;
};

等价理解：

type Project = {
  readonly id: string;
  readonly createdAt: string;
  updatedAt: string;
  name: string;
  description?: string;
  archivedAt: string | null;
};

Paper 也可以组合：

type Paper = EntityBase & {
  title: string;
  authors: string[];
  abstract?: string;
  citationCount: number;
  isRead: boolean;
};

这样公共字段只定义一次。

12. 交叉类型的注意点

不要乱合并不相关的大类型。

例如：

type Project = {
  id: string;
  name: string;
};

type Paper = {
  id: string;
  title: string;
};

type Weird = Project & Paper;

Weird 需要同时有：

id
name
title

这不一定有业务意义。

更危险的是同名字段类型冲突：

type A = {
  id: string;
};

type B = {
  id: number;
};

type C = A & B;

这里 id 同时要是 string 和 number，会变得不可用。

工程建议：

交叉类型适合抽公共字段。
不要乱把两个业务实体硬合并。

13. type 可以定义判别联合

这是 TypeScript 工程中非常重要的能力。

例如成功 / 失败结果：

type AsyncResult<T> =
  | {
      ok: true;
      data: T;
    }
  | {
      ok: false;
      errorMessage: string;
    };

它表示：

成功时：ok 是 true，并且一定有 data。
失败时：ok 是 false，并且一定有 errorMessage。

使用：

function renderProjectResult(
  result: AsyncResult<Project>,
): string {
  if (result.ok) {
    return `Project: ${result.data.name}`;
  }

  return `Error: ${result.errorMessage}`;
}

TypeScript 会自动知道：

result.ok 为 true 时，result 有 data。
result.ok 为 false 时，result 有 errorMessage。

不要写成：

type BadResult<T> = {
  ok: boolean;
  data?: T;
  errorMessage?: string;
};

因为它允许这种矛盾状态：

const result: BadResult<Project> = {
  ok: true,
  errorMessage: "failed",
};

业务上不合理，但类型允许。

更好的就是判别联合。

14. LoadState<T> 示例

页面加载状态也适合用 type 判别联合。

type LoadState<T> =
  | {
      status: "idle";
    }
  | {
      status: "loading";
    }
  | {
      status: "success";
      data: T;
    }
  | {
      status: "error";
      errorMessage: string;
    };

使用：

function renderWorkspaceState(
  state: LoadState<WorkspaceData>,
): string {
  switch (state.status) {
    case "idle":
      return "Not loaded";

    case "loading":
      return "Loading workspace";

    case "success":
      return `Loaded ${state.data.projects.length} projects`;

    case "error":
      return `Failed: ${state.errorMessage}`;
  }
}

这里 TypeScript 会根据 state.status 自动收窄类型。

工程口诀：

成功失败结果、加载状态、工具调用状态，都适合判别联合。

15. type 和泛型简单预告

你刚才看到：

type AsyncResult<T> = ...
type LoadState<T> = ...

这里的：

<T>

就是泛型。

当前你只需要先理解：

T 是一个类型参数。
使用时可以替换成具体类型。

例如：

type ProjectResult = AsyncResult<Project>;
type WorkspaceLoadState = LoadState<WorkspaceData>;

等价于：

ProjectResult 是 Project 的成功 / 失败结果。
WorkspaceLoadState 是 WorkspaceData 的加载状态。

泛型会在第 8 章系统讲。

当前先会使用即可。

16. type 不能重复声明

type 不支持重复声明。

type Project = {
  id: string;
};

type Project = {
  name: string;
}; // ❌

会报错：

Duplicate identifier 'Project'

这和 interface 不一样。

interface 支持声明合并，后面 7.7 会讲。

对业务模型来说，type 不能重复声明反而是好事：

它能避免业务模型被多个地方悄悄合并，导致字段来源混乱。

17. type 不存在于运行时

再次强调：

type Project = {
  id: string;
  name: string;
};

它编译后不存在。

所以不能：

console.log(Project); // ❌

不能：

if (value instanceof Project) {} // ❌

也不能：

const schema = Project; // ❌

如果你需要运行时校验，要写类型守卫：

function isProject(value: unknown): value is Project {
  // ...
}

或者后面用 Zod：

const ProjectSchema = z.object({
  id: z.string(),
  name: z.string(),
});

工程口诀：

type 管开发期。
Zod / 类型守卫管运行时。

18. type 和 as 的区别

你可能会看到：

const project = JSON.parse(rawJson) as Project;

这里的 as Project 不是把数据转换成 Project。

它只是告诉 TypeScript：

相信我，这个值就是 Project。

但如果真实 JSON 是：

{
  "id": 123,
  "title": "Wrong"
}

TypeScript 也不会自动知道。

所以：

const project = JSON.parse(rawJson) as Project;

是危险写法。

更安全：

const rawData: unknown = JSON.parse(rawJson);

if (!isProject(rawData)) {
  throw new Error("Invalid project");
}

const project: Project = rawData;

当前先记住：

type 不是运行时校验。
as 不是数据转换。
as 只是告诉 TypeScript 你相信它。

19. 跨文件导出 type

在真实项目中，类型通常会拆文件。

例如：

src/
  labpilot-types/
    project.ts
    paper.ts
    run.ts
    workspace.ts
    index.ts

文件：

// src/labpilot-types/project.ts

export type ProjectId = string;

export type Project = {
  readonly id: ProjectId;
  name: string;
  description?: string;
  readonly createdAt: string;
  updatedAt: string;
  archivedAt: string | null;
};

导入：

import type { Project } from "./labpilot-types/project.js";

这里用：

import type

表示只导入类型。

工程口诀：

导入类型，用 import type。
导入函数 / 常量 / class，用 import。

20. 统一导出类型

可以建立：

// src/labpilot-types/index.ts

export type {
  ProjectId,
  Project,
} from "./project.js";

export type {
  PaperId,
  Paper,
} from "./paper.js";

export type {
  RunStatus,
  ExperimentRun,
} from "./run.js";

然后其他地方导入：

import type {
  Project,
  ExperimentRun,
  RunStatus,
} from "./labpilot-types/index.js";

这样类型入口更清楚。

21. LabPilot 推荐类型组织

当前阶段建议：

src/
  labpilot-types/
