}

写入：

// src/function-types-demo.ts

type RunStatus = "queued" | "running" | "finished" | "failed";

type Project = {
  readonly id: string;
  name: string;
  description?: string;
  readonly createdAt: string;
  updatedAt: string;
  archivedAt: string | null;
};

type ExperimentRun = {
  readonly id: string;
  readonly experimentId: string;
  status: RunStatus;
  metrics: Record<string, number>;
  readonly startedAt: string;
  finishedAt?: string;
};

type RunDashboardData = {
  totalRuns: number;
  queuedRuns: number;
  runningRuns: number;
  finishedRuns: number;
  failedRuns: number;
  hasFailedRun: boolean;
  bestAccuracy: number | null;
};

type WorkspaceData = {
  id: string;
  name: string;
  projects: Project[];
  runs: ExperimentRun[];
};

type CreateProjectInput = {
  id: string;
  name: string;
  description?: string;
};

type CreateRunInput = {
  id: string;
  experimentId: string;
  status?: RunStatus;
  metrics?: Record<string, number>;
  startedAt?: string;
  finishedAt?: string;
};

type MetricFormatter = (value: number) => string;

type RunPredicate = (run: ExperimentRun) => boolean;

type AsyncResult<T> =
  | {
      ok: true;
      data: T;
    }
  | {
      ok: false;
      errorMessage: string;
    };

function createProject(input: CreateProjectInput): Project {
  const now = new Date().toISOString();

  return {
    id: input.id,
    name: input.name,
    description: input.description,
    createdAt: now,
    updatedAt: now,
    archivedAt: null,
  };
}

function createRun(input: CreateRunInput): ExperimentRun {
  return {
    id: input.id,
    experimentId: input.experimentId,
    status: input.status ?? "queued",
    metrics: input.metrics ?? {},
    startedAt: input.startedAt ?? new Date().toISOString(),
    finishedAt: input.finishedAt,
  };
}

const formatAccuracy: MetricFormatter = (value) => {
  return `${(value * 100).toFixed(2)}%`;
};

const isFailedRun: RunPredicate = (run) => {
  return run.status === "failed";
};

function findRunById(
  runs: readonly ExperimentRun[],
  runId: string,
): ExperimentRun | undefined {
  return runs.find((run) => {
    return run.id === runId;
  });
}

function getRunById(
  runs: readonly ExperimentRun[],
  runId: string,
): ExperimentRun {
  const run = findRunById(runs, runId);

  if (run === undefined) {
    throw new Error(`Run not found: ${runId}`);
  }

  return run;
}

function getBestAccuracy(
  runs: readonly ExperimentRun[],
): number | null {
  const accuracies = runs.flatMap((run) => {
    const accuracy = run.metrics.accuracy;

    if (accuracy === undefined) {
      return [];
    }

    return [accuracy];
  });

  if (accuracies.length === 0) {
    return null;
  }

  return Math.max(...accuracies);
}

function createRunDashboardData(
  runs: readonly ExperimentRun[],
): RunDashboardData {
  const queuedRuns = runs.filter((run) => {
    return run.status === "queued";
  });

  const runningRuns = runs.filter((run) => {
    return run.status === "running";
  });

  const finishedRuns = runs.filter((run) => {
    return run.status === "finished";
  });

  const failedRuns = runs.filter(isFailedRun);

  return {
    totalRuns: runs.length,
    queuedRuns: queuedRuns.length,
    runningRuns: runningRuns.length,
    finishedRuns: finishedRuns.length,
    failedRuns: failedRuns.length,
    hasFailedRun: failedRuns.length > 0,
    bestAccuracy: getBestAccuracy(runs),
  };
}

async function loadWorkspaceData(
  workspaceId: string,
): Promise<WorkspaceData> {
  const project = createProject({
    id: "proj_001",
    name: "LabPilot",
    description: "AI ResearchOps Platform",
  });

  const runs: ExperimentRun[] = [
    createRun({
      id: "run_001",
      experimentId: "exp_001",
      status: "finished",
      metrics: {
        accuracy: 0.91,
        loss: 0.23,
      },
      startedAt: "2026-06-25T10:00:00.000Z",
      finishedAt: "2026-06-25T10:30:00.000Z",
    }),
    createRun({
      id: "run_002",
      experimentId: "exp_001",
      status: "failed",
      metrics: {
        loss: 0.9,
      },
      startedAt: "2026-06-25T11:00:00.000Z",
    }),
  ];

  return {
    id: workspaceId,
    name: "LabPilot Workspace",
    projects: [project],
    runs,
  };
}

async function safeLoadWorkspaceData(
  workspaceId: string,
): Promise<AsyncResult<WorkspaceData>> {
  try {
    const data = await loadWorkspaceData(workspaceId);

    return {
      ok: true,
      data,
    };
  } catch (error: unknown) {
    return {
      ok: false,
      errorMessage:
        error instanceof Error ? error.message : "Unknown error",
    };
  }
}

async function main(): Promise<void> {
  const result = await safeLoadWorkspaceData("workspace_001");

  if (!result.ok) {
    console.error(result.errorMessage);
    return;
  }

  const workspaceData = result.data;

  const dashboard = createRunDashboardData(workspaceData.runs);

  const targetRun = getRunById(workspaceData.runs, "run_001");

  const accuracy = targetRun.metrics.accuracy;

  console.log("workspace:", workspaceData.name);
  console.log("dashboard:", dashboard);

  if (accuracy !== undefined) {
    console.log("accuracy:", formatAccuracy(accuracy));
  }
}

main().catch((error: unknown) => {
  console.error(error);
});

运行：

pnpm demo:function-types

